local function b64decode(data)
    local fns = {
        function() return crypt and crypt.base64decode and crypt.base64decode(data) end,
        function() return crypt and crypt.base64 and crypt.base64.decode and crypt.base64.decode(data) end,
        function() return base64_decode and base64_decode(data) end,
        function() return base64 and base64.decode and base64.decode(data) end,
    }
    for _, fn in ipairs(fns) do
        local ok, r = pcall(fn)
        if ok and type(r) == "string" and #r > 0 then return r end
    end
    local chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local map = {}
    for i = 1, 64 do map[string.byte(chars, i)] = i - 1 end
    local out, buf, n = {}, {}, 0
    local acc, bits = 0, 0
    for i = 1, #data do
        local v = map[string.byte(data, i)]
        if v then
            acc = acc * 64 + v
            bits = bits + 6
            if bits >= 8 then
                bits = bits - 8
                local p = 2 ^ bits
                local byte = math.floor(acc / p)
                acc = acc - byte * p
                n = n + 1
                buf[n] = string.char(byte)
                if n >= 4096 then
                    out[#out + 1] = table.concat(buf, "", 1, n)
                    n = 0
                end
            end
        end
    end
    if n > 0 then out[#out + 1] = table.concat(buf, "", 1, n) end
    return table.concat(out)
end

local function has(s, ...)
    for _, w in ipairs({...}) do
        if string.find(s, w, 1, true) then return true end
    end
    return false
end
--[[PURE-END]]

