--==================================================================
local function sanitize(v, depth)
    depth = depth or 0
    local t = type(v)
    if t == "string" then
        if utf8 and utf8.len(v) == nil then return (string.gsub(v, "[\128-\255]", "?")) end
        return v
    elseif t == "number" then
        if v ~= v or v == math.huge or v == -math.huge then return 0 end
        return v
    elseif t == "boolean" then
        return v
    elseif t == "table" then
        if depth > 25 then return nil end
        local out = {}
        for k, x in pairs(v) do
            local kk = k
            if type(k) == "string" then kk = sanitize(k, depth + 1) end
            out[kk] = sanitize(x, depth + 1)
        end
        return out
    end
    return nil
end
local function rawRead(path)
    if type(readfile) ~= "function" then return nil end
    if type(isfile) == "function" then
        local ok, ex = pcall(isfile, path)
        if not ok or not ex then return nil end
    end
    local ok, c = pcall(readfile, path)
    if ok and type(c) == "string" then return c end
    return nil
end
local function jsonOk(name, content)
    if string.sub(name, -5) ~= ".json" then return true end
    return (pcall(function() return HttpService:JSONDecode(content) end))
end
-- สร้างโฟลเดอร์ทีละชั้น (รองรับ BALL_KUN_AI_Dump/<PlaceId>)
local function ensureDir(dir)
    if type(makefolder) ~= "function" then return end
    local acc
    for part in string.gmatch(dir, "[^/]+") do
        acc = acc and (acc .. "/" .. part) or part
        local exists = false
        if type(isfolder) == "function" then
            local ok, v = pcall(isfolder, acc)
            exists = ok and v == true
        end
        if not exists then pcall(makefolder, acc) end
    end
end

-- เขียนไฟล์แบบปลอดภัย: สำรองรุ่นเดิม 2 รุ่น → เขียน → อ่านกลับ → เช็กขนาด/JSON → ลองซ้ำ 3 ครั้ง → ถ้าไม่ผ่านคืนไฟล์เดิม
-- noRotate = true: ไม่หมุนสำรองและไม่อ่านไฟล์เดิม (ใช้กับ partial_ ที่เซฟถี่ และ settings.json) ยังอ่านกลับตรวจทุกครั้ง
local function writeFile(name, content, noRotate, folderOverride)
    local dir = folderOverride or FOLDER
    if type(writefile) ~= "function" then return false, "ตัวรันนี้ไม่มี writefile" end
    ensureDir(dir)
    local path = dir .. "/" .. name
    local old = (not noRotate) and rawRead(path) or nil
    if old and #old > 2 and old ~= content then
        local b1 = rawRead(dir .. "/backup1_" .. name)
        if b1 and #b1 > 2 then pcall(writefile, dir .. "/backup2_" .. name, b1) end
        pcall(writefile, dir .. "/backup1_" .. name, old)
    end
    local lastErr = "ไม่ทราบสาเหตุ"
    for _ = 1, 3 do
        local ok, err = pcall(writefile, path, content)
        if not ok then
            lastErr = tostring(err)
        elseif type(readfile) ~= "function" then
            return true, path
        else
            local back = rawRead(path)
            if not back or #back ~= #content then lastErr = "อ่านไฟล์กลับมาตรวจแล้วไม่ตรง"
            elseif not jsonOk(name, back) then lastErr = "อ่านกลับมาแล้ว JSON เสีย"
            else return true, path end
        end
        task.wait(0.3)
    end
    if old and #old > 2 then pcall(writefile, path, old) end -- คืนไฟล์เดิม
    return false, lastErr
end

local function readFile(name)
    if type(readfile) ~= "function" then return nil end
    local path = FOLDER .. "/" .. name
    if type(isfile) == "function" then
        local ok, ex = pcall(isfile, path)
        if not ok or not ex then return nil end
    end
    local ok, c = pcall(readfile, path)
    if ok then return c end
    return nil
end

--==================================================================
-- ตัวช่วยอ่านข้อมูล
--==================================================================
local function r1(x)
    if type(x) ~= "number" or x ~= x or x == math.huge or x == -math.huge then return 0 end
    return math.floor(x * 10 + 0.5) / 10
end
local function v3(v) return {r1(v.X), r1(v.Y), r1(v.Z)} end
local function cut(s, n)
    s = tostring(s or "")
    n = n or 120
    if #s <= n then return s end
    local e = n
    while e > 0 do -- ไม่ตัดกลางตัวอักษรไทย (UTF-8)
        local b = string.byte(s, e + 1)
        if b and b >= 128 and b < 192 then e = e - 1 else break end
    end
    return string.sub(s, 1, e)
end
local function attrsOf(inst)
    local out, n = {}, 0
    local ok, a = pcall(function() return inst:GetAttributes() end)
    if ok and a then
        for k, v in pairs(a) do
            if n >= 20 then break end
            local tv = type(v)
            if tv == "string" or tv == "number" or tv == "boolean" then out[k] = (tv == "string") and cut(v, 80) or v
            else out[k] = cut(tostring(v), 80) end
            n = n + 1
        end
    end
    if n == 0 then return nil end
    return out
end
local function posOf(inst)
    local ok, p = pcall(function()
        if inst:IsA("BasePart") then return inst.Position end
        if inst:IsA("Attachment") then return inst.WorldPosition end
        if inst:IsA("Model") then return inst:GetPivot().Position end
        local part = inst:FindFirstAncestorWhichIsA("BasePart")
        if part then return part.Position end
        return nil
    end)
    if ok and p then return v3(p) end
    return nil
end
local function pathOf(inst)
    local ok, p = pcall(function() return inst:GetFullName() end)
    return ok and p or tostring(inst)
end
local function myPos()
    local ch = LP.Character
    local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
    return hrp and hrp.Position or nil
end
local function dist3(a, b)
    return math.sqrt((a[1] - b.X) ^ 2 + (a[2] - b.Y) ^ 2 + (a[3] - b.Z) ^ 2)
end

