local CAP = 4000
local Scanners = {}
local ORDER = {"map", "vehicle", "npc", "job", "ui", "remote"}
local St = {}

-- ตัวจัดการ Scanner (งาน 2): เปิดปิดแยกหมวด และกำหนดรัศมีค้นหาจากตัวละคร (nil = ไม่จำกัด)
local ScanMgr = {enabled = {}, radius = nil, center = nil}
for _, id in ipairs(ORDER) do ScanMgr.enabled[id] = true end
function ScanMgr.setEnabled(id, on)
    if not Scanners[id] then return false, "ไม่มีหมวด " .. tostring(id) end
    ScanMgr.enabled[id] = on and true or false
    return true
end
function ScanMgr.setRadius(r)
    if r == nil then ScanMgr.radius = nil return true end
    if type(r) ~= "number" or r <= 0 then return false, "รัศมีต้องเป็นตัวเลขมากกว่า 0" end
    ScanMgr.radius = r
    return true
end
function ScanMgr.status()
    local out = {}
    for _, id in ipairs(ORDER) do
        out[#out + 1] = {id = id, thai = Scanners[id] and Scanners[id].thai or id, enabled = ScanMgr.enabled[id] ~= false, scans = St[id] and St[id].scans or 0}
    end
    return {scanners = out, radius = ScanMgr.radius, map = ScanMgr.mapCfg}
end
for _, id in ipairs(ORDER) do St[id] = {status = "idle", scans = 0, saved = nil, truncated = false, last = nil} end

local function sortedList(map)
    local keys = {}
    for k in pairs(map) do keys[#keys + 1] = k end
    table.sort(keys)
    local out = {}
    for i, k in ipairs(keys) do out[i] = map[k] end
    return out
end
local function put(store, cnt, ckey, key, rec, id)
    if store[key] == nil then
        if (cnt[ckey] or 0) >= CAP then St[id].truncated = true return end
        cnt[ckey] = (cnt[ckey] or 0) + 1
    end
    store[key] = rec
end
local function tableCount(t) local n = 0 for _ in pairs(t) do n = n + 1 end return n end

