    {"รับงาน / รับออเดอร์", {"รับงาน", "รับออเดอร์", "accept", "ออเดอร์"}},
    {"รับของ / รับอาหาร / รับพัสดุ", {"รับอาหาร", "รับของ", "รับพัสดุ", "pickup", "pick up"}},
    {"ส่งของ / ส่งถึงลูกค้า", {"ส่งอาหาร", "ส่งถึง", "ส่งพัสดุ", "ส่งงาน", "deliver", "ลูกค้า"}},
    {"ยืนยัน / รับเงิน / รางวัล", {"ยืนยัน", "confirm", "รับเงิน", "รางวัล", "reward", "claim"}},
}
local JOBKW = {"งาน", "job", "deliver", "ส่ง", "รับ", "ออเดอร์", "order", "ภารกิจ", "quest", "ตู้เก็บของ", "locker", "ช่าง", "ไรเดอร์", "ล้างรถ", "carwash", "racing", "teleport", "ยืนยัน", "confirm", "accept", "cancel", "ยกเลิก", "start"}
-- [ไม่ได้ใช้งาน] เก็บไว้ตามข้อกำหนดห้ามลบโค้ด ตรวจแล้วว่าไม่มีจุดอ้างอิง
local BLOCKBUY = {"robux", "โดเนท", "donate"}

local function jobCategory(text)
    local l = string.lower(text)
    if has(l, "ไรเดอร์", "rider", "delivery") then return "ไรเดอร์/ส่งอาหาร" end
    if has(l, "ก่อสร้าง", "builder") then return "ช่างก่อสร้าง" end
    if has(l, "ช่างซ่อม", "mechanic", "repair") then return "ช่างซ่อมรถ" end
    if has(l, "ล้างรถ", "carwash", "car wash") then return "ล้างรถ" end
    if has(l, "racing", "drag", "แข่ง", "teleport") then return "แข่งขัน/เทเลพอร์ต" end
    if has(l, "group", "กลุ่ม", "get ฿") then return "รางวัลกลุ่ม" end
    if has(l, "ซื้อ", "robux", "โดเนท", "donate", "ยังไม่เปิดขาย") then return "ร้านค้า/ซื้อ" end
    if has(l, "ลิฟต์", "mrt", "station") then return "ขนส่ง/ลิฟต์" end
    return "อื่น ๆ"
end

-- ===== 1) MAP =====
do
    local d
    local function reset()
        d = {roads = {}, buildings = {}, labels = {}, landmarks = {}, cnt = {}, classCounts = {}, parts = 0, models = 0, extentChecks = 0,
            bmin = {math.huge, math.huge, math.huge}, bmax = {-math.huge, -math.huge, -math.huge}}
    end
    reset()
    local ROADKW = {"road", "street", "lane", "highway", "ถนน", "asphalt"}
    local BLDKW = {"building", "tower", "condo", "อาคาร", "ตึก", "mall", "hotel"}
-- ขอบเขตแมพ (งาน 2): ปิดการเก็บถนน อาคาร ป้ายข้อความ Terrain และวัตถุทั่วไป เหลือเฉพาะจุดสำคัญในโฟลเดอร์ Map
-- โค้ดเดิมยังครบ เปิดกลับได้ด้วยการแก้ค่าใน MAP_CFG
local MAP_CFG = {roads = false, buildings = false, labels = false, genericLandmarks = false}
ScanMgr.mapCfg = MAP_CFG
    Scanners.map = {
        id = "map", icon = "🗺️", title = "Map Scanner", thai = "สแกนแมพ",
        desc = "เก็บถนน อาคาร จุดสำคัญ ป้ายข้อความในโลก และขอบเขตพิกัดของแมพ",
        file = "map.json", roots = {Workspace = true},
        reset = reset,
        begin = function() d.parts, d.models, d.extentChecks, d.classCounts = 0, 0, 0, {} end,
        visit = function(inst)
            if inst:IsA("BasePart") then
                if inst:IsA("Terrain") then return end -- ไม่เก็บ Terrain
                d.parts = d.parts + 1
                local c = inst.ClassName
                d.classCounts[c] = (d.classCounts[c] or 0) + 1
                local p = inst.Position
                if p.X < d.bmin[1] then d.bmin[1] = p.X end
                if p.Y < d.bmin[2] then d.bmin[2] = p.Y end
                if p.Z < d.bmin[3] then d.bmin[3] = p.Z end
                if p.X > d.bmax[1] then d.bmax[1] = p.X end
                if p.Y > d.bmax[2] then d.bmax[2] = p.Y end
                if p.Z > d.bmax[3] then d.bmax[3] = p.Z end
                local sz = inst.Size
                local mn = math.min(sz.X, sz.Y, sz.Z)
                local mx = math.max(sz.X, sz.Y, sz.Z)
                local nm = string.lower(inst.Name)
                local byName = has(nm, unpack(ROADKW))
                local mat = inst.Material.Name
                local byMat = (mat == "Asphalt" or mat == "Concrete" or mat == "Pavement" or mat == "Cobblestone")
                if MAP_CFG.roads and ((mn <= 3 and mx >= 20 and mx / math.max(mn, 0.1) >= 2.5 and (byName or byMat)) or (byName and mx >= 10)) then
                    put(d.roads, d.cnt, "roads", pathOf(inst), {n = inst.Name, p = v3(p), s = v3(sz), m = mat, path = cut(pathOf(inst), 160)}, "map")
                end
            elseif inst:IsA("Model") then
                d.models = d.models + 1
                if not MAP_CFG.buildings then return end
                if inst:FindFirstChildOfClass("Humanoid") then return end
                local nm = string.lower(inst.Name)
                local byName = has(nm, unpack(BLDKW))
                if byName or (d.extentChecks < 4000 and #inst:GetChildren() >= 4) then
                    d.extentChecks = d.extentChecks + 1
                    local sz = inst:GetExtentsSize()
                    if (byName and sz.Y >= 8) or (sz.Y >= 12 and sz.X >= 6 and sz.Z >= 6) then
                        put(d.buildings, d.cnt, "buildings", pathOf(inst), {n = inst.Name, p = posOf(inst), s = v3(sz), parts = #inst:GetChildren(), byName = byName, path = cut(pathOf(inst), 160)}, "map")
                    end
                end
            elseif MAP_CFG.labels and (inst:IsA("TextLabel") or inst:IsA("TextButton")) then
                local t = inst.Text
                if t and t ~= "" and #t < 200 then
                    put(d.labels, d.cnt, "labels", pathOf(inst), {text = cut(t, 100), p = posOf(inst), path = cut(pathOf(inst), 160)}, "map")
                end
            end
        end,
        finish = function()
            d.landmarks = {}
            local map = Workspace:FindFirstChild("Map")
            local function scanFolder(folder, prefix)
                for _, ch in ipairs(folder:GetChildren()) do
                    d.landmarks[#d.landmarks + 1] = {n = prefix .. ch.Name, class = ch.ClassName, p = posOf(ch), children = #ch:GetChildren()}
                end
            end
            if map then
                scanFolder(map, "Map/")
                local lm = map:FindFirstChild("Landmarks")
                if lm then scanFolder(lm, "Map/Landmarks/") end
            else
                if MAP_CFG.genericLandmarks then scanFolder(Workspace, "") end
            end
        end,
        items = function()
            return {
                {"ถนนที่คาดว่าใช่", tableCount(d.roads)}, {"อาคารที่คาดว่าใช่", tableCount(d.buildings)},
                {"จุดสำคัญ (Landmarks)", #d.landmarks}, {"ป้ายข้อความในโลก", tableCount(d.labels)},
                {"ชิ้นส่วนที่โหลดตอนสแกนล่าสุด", d.parts}, {"โมเดลที่โหลดตอนสแกนล่าสุด", d.models},
            }
        end,
        export = function()
            local b = d.parts > 0 and {min = v3(Vector3.new(unpack(d.bmin))), max = v3(Vector3.new(unpack(d.bmax)))} or nil
            return {bounds = b, parts = d.parts, models = d.models, classCounts = d.classCounts, roads = sortedList(d.roads),
                buildings = sortedList(d.buildings), landmarks = d.landmarks, labels = sortedList(d.labels),
                note = "ถนน/อาคารเป็นการเดาจากขนาด วัสดุ ชื่อ ควรตรวจซ้ำ"}
        end,
        list = function()
            local out = {}
            for _, r in pairs(d.roads) do out[#out + 1] = {n = r.n, p = r.p, path = r.path, kind = "ถนน"} end
            for _, r in pairs(d.buildings) do out[#out + 1] = {n = r.n, p = r.p, path = r.path, kind = "อาคาร"} end
            for _, r in ipairs(d.landmarks) do out[#out + 1] = {n = r.n, p = r.p, path = r.n, kind = "จุดสำคัญ"} end
            for _, r in pairs(d.labels) do out[#out + 1] = {n = r.text, p = r.p, path = r.path, kind = "ป้าย"} end
            return out
        end,
        total = function() return tableCount(d.roads) + tableCount(d.buildings) + #d.landmarks end,
    }
end

-- ===== 2) VEHICLE =====
do
    local d
    local function reset() d = {v = {}, cnt = {}, containers = {}} end
    reset()
    local VKW = {"vehicle", "car", "bike", "motor", "รถ", "มอเตอร์ไซค์", "pcx", "truck", "กระบะ"}
    Scanners.vehicle = {
        id = "vehicle", icon = "🛵", title = "Vehicle Scanner", thai = "สแกนรถ",
        desc = "เก็บรถและมอเตอร์ไซค์ที่โหลดอยู่: เบาะ ความเร็วสูงสุด แรงบิด มวล แอตทริบิวต์ และคนที่นั่งอยู่",
        file = "vehicles.json", roots = {Workspace = true},
        reset = reset,
        visit = function(inst)
            if not (inst:IsA("VehicleSeat") or inst:IsA("Seat")) then return end
            local model = inst:FindFirstAncestorOfClass("Model") or inst
            local mpath = string.lower(pathOf(model))
            if inst:IsA("Seat") and not has(mpath, unpack(VKW)) then return end
            local rec = {n = model.Name, path = cut(pathOf(model), 160), seat = inst.ClassName, p = posOf(inst), attrs = attrsOf(model), seatAttrs = attrsOf(inst)}
            if inst:IsA("VehicleSeat") then
                rec.vs = {maxSpeed = r1(inst.MaxSpeed), torque = r1(inst.Torque), turnSpeed = r1(inst.TurnSpeed), disabled = inst.Disabled}
            end
            local occ = inst.Occupant
            if occ and occ.Parent then
                local pl = Players:GetPlayerFromCharacter(occ.Parent)
                rec.occupant = pl and pl.Name or occ.Parent.Name
                rec.mine = (pl == LP)
            end
            local okm, mass = pcall(function() return (model.PrimaryPart or inst).AssemblyMass end)
            if okm then rec.mass = r1(mass) end
            local cc, seen = {}, 0
            for _, dsc in ipairs(model:GetDescendants()) do
                seen = seen + 1
                if seen > 400 then break end
                if dsc:IsA("Constraint") then cc[dsc.ClassName] = (cc[dsc.ClassName] or 0) + 1 end
            end
            rec.constraints = cc
            local tags = {}
            pcall(function() tags = game:GetService("CollectionService"):GetTags(model) end)
            if #tags > 0 then rec.tags = tags end
            put(d.v, d.cnt, "v", pathOf(model), rec, "vehicle")
        end,
        finish = function()
            d.containers = {}
            for _, ch in ipairs(Workspace:GetChildren()) do
                local nm = string.lower(ch.Name)
                if has(nm, "vehicle", "car", "bike", "รถ", "spawn") and (ch:IsA("Folder") or ch:IsA("Model")) then
                    d.containers[#d.containers + 1] = {n = ch.Name, class = ch.ClassName, children = #ch:GetChildren()}
                end
            end
        end,
        items = function()
            local mine, occ, vs = 0, 0, 0
            for _, r in pairs(d.v) do
                if r.mine then mine = mine + 1 end
                if r.occupant then occ = occ + 1 end
                if r.vs then vs = vs + 1 end
            end
            return {{"รถที่พบ", tableCount(d.v)}, {"มีข้อมูลควบคุม (VehicleSeat)", vs}, {"มีคนนั่งอยู่", occ}, {"รถที่คุณนั่งอยู่", mine}, {"โฟลเดอร์เก็บรถ", #d.containers}}
        end,
        export = function() return {vehicles = sortedList(d.v), containers = d.containers, note = "เรียกรถของคุณออกมาก่อนสแกน เพื่อให้ได้ข้อมูลครบ"} end,
        list = function()
            local out = {}
            for _, r in pairs(d.v) do out[#out + 1] = {n = r.n, p = r.p, path = r.path, kind = "รถ"} end
            return out
        end,
        total = function() return tableCount(d.v) end,
    }
end

-- ===== 3) NPC =====
do
    local d
    local function reset() d = {npc = {}, cnt = {}} end
    reset()
    Scanners.npc = {
        id = "npc", icon = "👤", title = "NPC Scanner", thai = "สแกน NPC",
        desc = "เก็บ NPC และตัวละครที่ไม่ใช่ผู้เล่น: ตำแหน่ง ชื่อ พลังชีวิต แอตทริบิวต์ และข้อความจุดกดที่ติดอยู่",
        file = "npcs.json", roots = {Workspace = true},
        reset = reset,
        visit = function(inst)
            if inst:IsA("Humanoid") then
                local model = inst.Parent
                if not model or Players:GetPlayerFromCharacter(model) then return end
                local pr = model:FindFirstChildWhichIsA("ProximityPrompt", true)
                local rec = {n = model.Name, path = cut(pathOf(model), 160), p = posOf(model), hp = r1(inst.Health), maxHp = r1(inst.MaxHealth),
                    walkSpeed = r1(inst.WalkSpeed), rig = inst.RigType.Name, attrs = attrsOf(model), kind = "humanoid"}
                if pr then rec.prompt = {action = cut(pr.ActionText, 60), object = cut(pr.ObjectText, 60)} end
                put(d.npc, d.cnt, "npc", pathOf(model), rec, "npc")
            elseif inst:IsA("ProximityPrompt") then
                local m = inst:FindFirstAncestorOfClass("Model")
                if m and not m:FindFirstChildOfClass("Humanoid") and has(string.lower(pathOf(m)), "/npc", ".npc", "npc") then
                    put(d.npc, d.cnt, "npc", pathOf(m), {n = m.Name, path = cut(pathOf(m), 160), p = posOf(m), kind = "prompt-npc",
                        prompt = {action = cut(inst.ActionText, 60), object = cut(inst.ObjectText, 60)}, attrs = attrsOf(m)}, "npc")
                end
            end
        end,
        finish = function() end,
        items = function()
            local h, pn, withPrompt = 0, 0, 0
            for _, r in pairs(d.npc) do
                if r.kind == "humanoid" then h = h + 1 else pn = pn + 1 end
                if r.prompt then withPrompt = withPrompt + 1 end
            end
            return {{"NPC ทั้งหมด", tableCount(d.npc)}, {"แบบมี Humanoid", h}, {"แบบจุดกดบนโมเดล", pn}, {"ที่มีจุดกดให้คุยหรือกด", withPrompt}}
        end,
        export = function() return {npcs = sortedList(d.npc)} end,
        list = function()
            local out = {}
            for _, r in pairs(d.npc) do out[#out + 1] = {n = r.n, p = r.p, path = r.path, kind = "NPC", text = r.prompt and (r.prompt.action .. " " .. r.prompt.object) or nil} end
            return out
        end,
        total = function() return tableCount(d.npc) end,
    }
end

-- ===== 4) JOB =====
do
    local d
    local function resetFlow() local f = {} for i = 1, #FLOW do f[i] = 0 end return f end
    local function reset() d = {prompts = {}, clicks = {}, stations = {}, values = {}, gui = {}, guiTexts = {}, cnt = {}, flow = resetFlow(), player = {}, cats = {}} end
    reset()
    local function tally(text)
        local l = string.lower(text)
        for i, step in ipairs(FLOW) do
            if has(l, unpack(step[2])) then d.flow[i] = d.flow[i] + 1 end
        end
    end
    Scanners.job = {
        id = "job", icon = "📦", title = "Job Scanner", thai = "สแกนงาน",
        desc = "เก็บจุดกด ตู้รับงาน จุดทำงาน หน้าจองานใน UI และเช็กว่าพบขั้นตอน รับงาน → รับของ → ส่งของ → ยืนยัน แล้วกี่ขั้น",
        file = "jobs.json", roots = {Workspace = true, PlayerGui = true, ReplicatedStorage = true},
        reset = reset,
        begin = function() d.flowPrev = d.flow d.flow = resetFlow() end,
        visit = function(inst, root)
            if root == "Workspace" then
                if inst:IsA("ProximityPrompt") then
                    local obj = inst.Parent
                    local text = (inst.ActionText or "") .. " " .. (inst.ObjectText or "") .. " " .. pathOf(inst)
                    local cat = jobCategory(text)
                    d.cats[cat] = (d.cats[cat] or 0) + 1
                    tally((inst.ActionText or "") .. " " .. (inst.ObjectText or ""))
                    put(d.prompts, d.cnt, "prompts", pathOf(inst), {action = cut(inst.ActionText, 60), object = cut(inst.ObjectText, 60), cat = cat,
                        enabled = inst.Enabled, hold = r1(inst.HoldDuration), maxDist = r1(inst.MaxActivationDistance), key = inst.KeyboardKeyCode.Name,
                        p = posOf(inst), attrs = attrsOf(inst), parentAttrs = obj and attrsOf(obj) or nil, path = cut(pathOf(inst), 180)}, "job")
                elseif inst:IsA("ClickDetector") then
                    put(d.clicks, d.cnt, "clicks", pathOf(inst), {maxDist = r1(inst.MaxActivationDistance), p = posOf(inst), path = cut(pathOf(inst), 180)}, "job")
                elseif inst:GetAttribute("Job") ~= nil or inst:GetAttribute("StationId") ~= nil then
                    put(d.stations, d.cnt, "stations", pathOf(inst), {n = inst.Name, job = inst:GetAttribute("Job"), station = inst:GetAttribute("StationId"), p = posOf(inst), attrs = attrsOf(inst), path = cut(pathOf(inst), 180)}, "job")
                end
            end
            if (root == "Workspace" or root == "ReplicatedStorage") and inst:IsA("ValueBase") then
                local nm = string.lower(inst.Name)
                if has(nm, "job", "delivery", "order", "quest", "money", "cash", "reward", "งาน") then
                    local okv, val = pcall(function() return inst.Value end)
                    put(d.values, d.cnt, "values", pathOf(inst), {n = inst.Name, value = okv and cut(tostring(val), 60) or "?", class = inst.ClassName, path = cut(pathOf(inst), 180)}, "job")
                end
            end
            if root == "PlayerGui" then
                if inst:IsA("ScreenGui") and inst.Parent == PlayerGui then
                    put(d.gui, d.cnt, "gui", inst.Name, {n = inst.Name, enabled = inst.Enabled}, "job")
                elseif inst:IsA("TextLabel") or inst:IsA("TextButton") then
                    local t = inst.Text
                    if t and t ~= "" and #t < 160 and has(string.lower(t), unpack(JOBKW)) then
                        tally(t)
                        put(d.guiTexts, d.cnt, "guiTexts", pathOf(inst), {text = cut(t, 100), visible = inst.Visible, path = cut(pathOf(inst), 180)}, "job")
                    end
                end
            end
        end,
        finish = function()
            if d.flowPrev then
                for i = 1, #FLOW do d.flow[i] = math.max(d.flow[i], d.flowPrev[i] or 0) end
                d.flowPrev = nil
            end
            d.player = {attrs = attrsOf(LP), values = {}}
            local function grab(folder)
                if not folder then return end
                for _, ch in ipairs(folder:GetChildren()) do
                    if ch:IsA("ValueBase") then
                        local ok, v = pcall(function() return ch.Value end)
                        d.player.values[folder.Name .. "/" .. ch.Name] = ok and cut(tostring(v), 60) or "?"
                    end
                end
            end
            grab(LP:FindFirstChild("leaderstats"))
            grab(LP:FindFirstChild("Data"))
        end,
        items = function()
            local out = {{"จุดกด (ProximityPrompt)", tableCount(d.prompts)}, {"จุดคลิก (ClickDetector)", tableCount(d.clicks)},
                {"จุดทำงาน (มี Job/StationId)", tableCount(d.stations)}, {"ค่าเกี่ยวกับงาน/เงิน", tableCount(d.values)},
                {"หน้าต่าง UI ของเกม", tableCount(d.gui)}, {"ข้อความงานใน UI", tableCount(d.guiTexts)}}
            for i, step in ipairs(FLOW) do out[#out + 1] = {"ขั้นตอน: " .. step[1], d.flow[i]} end
            return out
        end,
        export = function()
            local flow = {}
            for i, step in ipairs(FLOW) do flow[i] = {step = step[1], evidence = d.flow[i], found = d.flow[i] > 0} end
            return {prompts = sortedList(d.prompts), clicks = sortedList(d.clicks), stations = sortedList(d.stations), values = sortedList(d.values),
                gui = sortedList(d.gui), guiTexts = sortedList(d.guiTexts), categories = d.cats, flow = flow, player = d.player,
                note = "ขั้นตอนที่ไม่พบอาจเพราะยังไม่ได้เปิดแอปงานหรือยังไม่ได้เริ่มงานในเกม"}
        end,
        list = function()
            local out = {}
            for _, r in pairs(d.prompts) do out[#out + 1] = {n = r.object ~= "" and r.object or r.action, p = r.p, path = r.path, kind = "จุดกด/" .. r.cat, text = r.action .. " " .. r.object, enabled = r.enabled} end
            for _, r in pairs(d.stations) do out[#out + 1] = {n = r.n, p = r.p, path = r.path, kind = "จุดทำงาน", text = tostring(r.job)} end
            for _, r in pairs(d.guiTexts) do out[#out + 1] = {n = r.text, path = r.path, kind = "ข้อความ UI", text = r.text} end
            return out
        end,
        total = function() return tableCount(d.prompts) + tableCount(d.stations) + tableCount(d.guiTexts) end,
        flowFound = function() local n = 0 for i = 1, #FLOW do if d.flow[i] > 0 then n = n + 1 end end return n end,
        flowMissing = function() local out = {} for i, step in ipairs(FLOW) do if (d.flow[i] or 0) == 0 then out[#out + 1] = step[1] end end return out end,
        prompts = function() return d.prompts end,
    }
end

-- ===== 5) REMOTE (ดูโครงสร้างเท่านั้น ไม่ส่งคำสั่ง) =====
do
    local d
    local function reset() d = {r = {}, cnt = {}, frameworks = {}, byParent = {}, obf = 0, classes = {}} end
    reset()
    local RCLASS = {RemoteEvent = true, RemoteFunction = true, UnreliableRemoteEvent = true, BindableEvent = true, BindableFunction = true}
    local FRAMEWORKS = {"BridgeNet2", "BridgeNet", "Knit", "Packet", "ByteNet", "Red", "Net", "Comm", "Remotes", "Blink", "Zap", "Warp", "NetSeal", "Networker"}
    local function looksObf(name)
        if #name >= 16 and not string.find(name, "%s") then
            local alnum = string.gsub(name, "[^%w]", "")
            return #alnum / #name > 0.9 and not string.find(name, "%l%u%l") and string.find(name, "%d") ~= nil
        end
        return false
    end
    Scanners.remote = {
        id = "remote", icon = "🔍", title = "Remote Analyzer", thai = "สแกน Remote",
        desc = "ตรวจโครงสร้าง Remote/Bindable ที่มองเห็นได้ ที่อยู่ ชนิด จำนวนตัวฟัง และเฟรมเวิร์กที่เกมใช้ — ดูอย่างเดียว ไม่ยิงคำสั่ง ไม่ hook",
        file = "remotes.json", roots = {Workspace = true, ReplicatedStorage = true, ReplicatedFirst = true, PlayerGui = true},
        reset = reset,
        visit = function(inst, root)
            local cls = inst.ClassName
            if RCLASS[cls] then
                local par = inst.Parent
                local parPath = par and cut(pathOf(par), 160) or "?"
                local rec = {n = inst.Name, class = cls, path = cut(pathOf(inst), 180), parent = parPath, root = root}
                if (cls == "RemoteEvent" or cls == "UnreliableRemoteEvent") and type(getconnections) == "function" and (d.cnt.r or 0) < 400 then
                    local ok, c = pcall(function() return #getconnections(inst.OnClientEvent) end)
                    if ok then rec.listeners = c end
                end
                if looksObf(inst.Name) then rec.obf = true end
                put(d.r, d.cnt, "r", pathOf(inst), rec, "remote")
            end
        end,
        finish = function()
            d.classes, d.byParent, d.obf = {}, {}, 0
            for _, r in pairs(d.r) do
                d.classes[r.class] = (d.classes[r.class] or 0) + 1
                d.byParent[r.parent] = (d.byParent[r.parent] or 0) + 1
                if r.obf then d.obf = d.obf + 1 end
            end
            d.frameworks = {}
            local seen = {}
            for _, root in ipairs({RepStorage, RepFirst}) do
                for _, ch in ipairs(root:GetChildren()) do
                    for _, fw in ipairs(FRAMEWORKS) do
                        if string.lower(ch.Name) == string.lower(fw) and not seen[ch.Name] then
                            seen[ch.Name] = true
                            d.frameworks[#d.frameworks + 1] = {name = ch.Name, class = ch.ClassName, children = #ch:GetChildren()}
                        end
                    end
                end
            end
        end,
        items = function()
            local ev, fn, bd = 0, 0, 0
            for _, r in pairs(d.r) do
                if r.class == "RemoteEvent" or r.class == "UnreliableRemoteEvent" then ev = ev + 1
                elseif r.class == "RemoteFunction" then fn = fn + 1 else bd = bd + 1 end
            end
            return {{"Remote ทั้งหมด", tableCount(d.r)}, {"RemoteEvent", ev}, {"RemoteFunction", fn}, {"Bindable", bd},
                {"เฟรมเวิร์กที่เจอ", #d.frameworks}, {"ชื่อที่ดูสุ่ม/ถูกปิดบัง", d.obf}}
        end,
        export = function()
            local parents = {}
            for k, v in pairs(d.byParent) do parents[#parents + 1] = {parent = k, count = v} end
            table.sort(parents, function(a, b) return a.count > b.count end)
            return {remotes = sortedList(d.r), frameworks = d.frameworks, byClass = d.classes, topParents = parents,
                obfuscatedNames = d.obf, hasGetconnections = type(getconnections) == "function",
                note = "ดูโครงสร้างอย่างเดียว ไม่ได้เรียก FireServer/InvokeServer และไม่ได้ hook"}
        end,
        list = function()
            local out = {}
            for _, r in pairs(d.r) do out[#out + 1] = {n = r.n, path = r.path, kind = "Remote/" .. r.class, text = r.parent} end
            return out
        end,
        total = function() return tableCount(d.r) end,
        info = function() return d end,
    }
end

-- ===== 6) UI / จุดโต้ตอบ (ใช้ได้ทุกแมพ ไม่ผูกกับ PlaceId) =====
-- เก็บ: ปุ่ม UI ทุกปุ่ม (TextButton/ImageButton) | ProximityPrompt | ClickDetector | แผ่นสัมผัส (TouchTransmitter)
--       จุดเกิด (SpawnLocation) | ของที่วางพื้น/ในกระเป๋า (Tool) | หน้าต่าง UI (ScreenGui) | ข้อมูลแมพทั่วไป
-- อ่านอย่างเดียว: ไม่กด ไม่คลิก ไม่ยิง Remote ปุ่มซื้อ/Robux จะถูกติดธง buy ไว้เฉย ๆ
do
    local d
    local function reset()
        d = {screens = {}, buttons = {}, prompts = {}, clicks = {}, touch = {}, spawns = {}, tools = {}, worldTools = {}, cnt = {},
            touchCats = {}, buyCount = 0, game = nil, world = nil}
    end
    reset()
    local BUYKW = {"robux", "r$", "buy", "purchase", "gamepass", "game pass", "premium", "vip", "donate", "โดเนท", "ซื้อ", "เติมเงิน", "shop", "store", "ร้านค้า"}
    local TELEKW = {"teleport", "portal", "warp", "door", "gate", "elevator", "lift", "ประตู", "เทเลพอร์ต", "ลิฟต์"}
    local COLLKW = {"coin", "cash", "collect", "pickup", "orb", "gem", "เหรียญ", "เงิน", "เก็บ"}
    local DANGKW = {"kill", "lava", "damage", "trap", "spike", "hazard", "death", "อันตราย", "ลาวา"}
    local CHECKKW = {"checkpoint", "spawn", "stage", "เช็กพอยต์", "จุดเซฟ"}

    local function isOwnGui(inst)
        local sg = inst:FindFirstAncestorOfClass("ScreenGui")
        return sg ~= nil and sg.Name == "BALLKUN_SCANNER_V7"
    end
    local function guiShown(inst)
        local cur = inst
        while cur and cur ~= game do
            if cur:IsA("ScreenGui") and not cur.Enabled then return false end
            if cur:IsA("GuiObject") and not cur.Visible then return false end
            cur = cur.Parent
        end
        return true
    end
    local function labelText(inst)
        if inst:IsA("TextButton") and inst.Text ~= "" then return inst.Text end
        local n = 0
        for _, c in ipairs(inst:GetDescendants()) do
            n = n + 1
            if n > 12 then break end
            if (c:IsA("TextLabel") or c:IsA("TextButton")) and c.Text ~= "" then return c.Text end
        end
        return ""
    end
    local function touchCategory(l)
        if has(l, unpack(TELEKW)) then return "เทเลพอร์ต/ประตู", true end
        if has(l, unpack(CHECKKW)) then return "เช็กพอยต์/จุดเกิด", true end
        if has(l, unpack(DANGKW)) then return "อันตราย", false end
        if has(l, unpack(COLLKW)) then return "ของเก็บ/เหรียญ", false end
        return "อื่น ๆ", false
    end

    Scanners.ui = {
        id = "ui", icon = "🔘", title = "Interact Scanner", thai = "สแกนปุ่ม/จุดโต้ตอบ",
        desc = "เก็บปุ่ม UI ทุกปุ่ม จุดกด (ProximityPrompt) จุดคลิก แผ่นสัมผัส/เทเลพอร์ต จุดเกิด และของในกระเป๋า — ใช้ได้ทุกแมพ อ่านอย่างเดียว ไม่กดอะไร",
        file = "interact.json", roots = {Workspace = true, PlayerGui = true},
        reset = reset,
        visit = function(inst, root)
            if root == "PlayerGui" and inst.Parent == PlayerGui and inst:IsA("ScreenGui") then
                if not isOwnGui(inst) then
                    put(d.screens, d.cnt, "screens", inst.Name, {n = inst.Name, enabled = inst.Enabled, order = inst.DisplayOrder, children = #inst:GetDescendants()}, "ui")
                end
                return
            end
            if inst:IsA("TextButton") or inst:IsA("ImageButton") then
                if isOwnGui(inst) then return end
                local text = labelText(inst)
                local path = pathOf(inst)
                local l = string.lower(inst.Name .. " " .. text .. " " .. path)
                local buy = has(l, unpack(BUYKW))
                local ap, as = inst.AbsolutePosition, inst.AbsoluteSize
                local sg = inst:FindFirstAncestorOfClass("ScreenGui")
                put(d.buttons, d.cnt, "buttons", path, {n = inst.Name, class = inst.ClassName, text = cut(text, 80), visible = guiShown(inst),
                    screen = sg and sg.Name or "?", size = {r1(as.X), r1(as.Y)}, pos = {r1(ap.X), r1(ap.Y)}, buy = buy or nil,
                    world = (root == "Workspace") or nil, p = (root == "Workspace") and posOf(inst) or nil, path = cut(path, 180)}, "ui")
            elseif root == "Workspace" then
                if inst:IsA("ProximityPrompt") then
                    local path = pathOf(inst)
                    local l = string.lower((inst.ActionText or "") .. " " .. (inst.ObjectText or "") .. " " .. path)
                    local buy = has(l, unpack(BUYKW))
                    put(d.prompts, d.cnt, "prompts", path, {action = cut(inst.ActionText, 60), object = cut(inst.ObjectText, 60), key = inst.KeyboardKeyCode.Name,
                        hold = r1(inst.HoldDuration), maxDist = r1(inst.MaxActivationDistance), enabled = inst.Enabled, buy = buy or nil,
                        p = posOf(inst), attrs = attrsOf(inst), path = cut(path, 180)}, "ui")
                elseif inst:IsA("ClickDetector") then
                    local path = pathOf(inst)
                    put(d.clicks, d.cnt, "clicks", path, {n = inst.Parent and inst.Parent.Name or inst.Name, maxDist = r1(inst.MaxActivationDistance),
                        buy = has(string.lower(path), unpack(BUYKW)) or nil, p = posOf(inst), path = cut(path, 180)}, "ui")
                elseif inst:IsA("TouchTransmitter") then
                    local par = inst.Parent
                    if par then
                        local path = pathOf(par)
                        local cat, hot = touchCategory(string.lower(par.Name .. " " .. path))
                        if d.touch[path] == nil then d.touchCats[cat] = (d.touchCats[cat] or 0) + 1 end
                        put(d.touch, d.cnt, "touch", path, {n = par.Name, cat = cat, hot = hot, p = posOf(par), attrs = attrsOf(par), path = cut(path, 180)}, "ui")
                    end
                elseif inst:IsA("SpawnLocation") then
                    put(d.spawns, d.cnt, "spawns", pathOf(inst), {n = inst.Name, enabled = inst.Enabled, neutral = inst.Neutral, duration = inst.Duration,
                        team = inst.TeamColor.Name, p = posOf(inst), path = cut(pathOf(inst), 180)}, "ui")
                elseif inst:IsA("Tool") and not inst:FindFirstAncestorOfClass("Model") then
                    put(d.worldTools, d.cnt, "worldTools", pathOf(inst), {n = inst.Name, p = posOf(inst), tip = cut(inst.ToolTip, 60), canBeDropped = inst.CanBeDropped, path = cut(pathOf(inst), 180)}, "ui")
                end
            end
        end,
        finish = function()
            d.buyCount = 0
