            local okG, info = pcall(function() return game:GetService("MarketplaceService"):GetProductInfo(game.PlaceId) end)
            d.game = {placeId = game.PlaceId, gameId = game.GameId, name = okG and info and cut(info.Name, 80) or "?"}
        end,
        counts = function()
            return {buttons = tableCount(d.buttons), prompts = tableCount(d.prompts), clicks = tableCount(d.clicks), touch = tableCount(d.touch),
                spawns = tableCount(d.spawns), screens = tableCount(d.screens), buy = d.buyCount}
        end,
        items = function()
            local vis = 0
            for _, r in pairs(d.buttons) do if r.visible then vis = vis + 1 end end
            return {
                {"หน้าต่าง UI (ScreenGui)", tableCount(d.screens)}, {"ปุ่ม UI ทั้งหมด", tableCount(d.buttons)}, {"ปุ่ม UI ที่มองเห็นอยู่", vis},
                {"จุดกด (ProximityPrompt)", tableCount(d.prompts)}, {"จุดคลิก (ClickDetector)", tableCount(d.clicks)},
                {"แผ่นสัมผัส/เทเลพอร์ต", tableCount(d.touch)}, {"จุดเกิด (SpawnLocation)", tableCount(d.spawns)},
                {"ปุ่มซื้อ/Robux (ไม่กดเด็ดขาด)", d.buyCount}, {"Tool (พื้น+กระเป๋า)", tableCount(d.worldTools) + #(d.tools or {})},
            }
        end,
        export = function()
            local cats = {}
            for k, v in pairs(d.touchCats) do cats[#cats + 1] = {cat = k, count = v} end
