                clicks = sortedList(d.clicks), touchPads = sortedList(d.touch), touchCategories = cats, spawns = sortedList(d.spawns),
                worldTools = sortedList(d.worldTools), backpackTools = d.tools, buyFlagged = d.buyCount,
                note = "อ่านอย่างเดียว ไม่ได้กด/คลิก/ยิง Remote ใด ๆ ปุ่มที่มีคำซื้อ/Robux ถูกติดธง buy ไว้เพื่อให้รู้ว่าอย่ากด"}
        end,
        list = function()
            local out = {}
            for _, r in pairs(d.buttons) do out[#out + 1] = {n = r.text ~= "" and r.text or r.n, p = r.p, path = r.path, kind = "ปุ่ม UI", text = r.text, buy = r.buy} end
            for _, r in pairs(d.prompts) do out[#out + 1] = {n = r.object ~= "" and r.object or r.action, p = r.p, path = r.path, kind = "จุดกด", text = r.action .. " " .. r.object, hot = r.enabled, buy = r.buy} end
            for _, r in pairs(d.clicks) do out[#out + 1] = {n = r.n, p = r.p, path = r.path, kind = "จุดคลิก", text = r.n, hot = true, buy = r.buy} end
            for _, r in pairs(d.touch) do out[#out + 1] = {n = r.n, p = r.p, path = r.path, kind = "แผ่นสัมผัส/" .. r.cat, text = r.cat, hot = r.hot} end
            for _, r in pairs(d.spawns) do out[#out + 1] = {n = r.n, p = r.p, path = r.path, kind = "จุดเกิด", text = r.team, hot = true} end
            for _, r in pairs(d.worldTools) do out[#out + 1] = {n = r.n, p = r.p, path = r.path, kind = "Tool บนพื้น", text = r.tip} end
            return out
        end,
        total = function() return tableCount(d.buttons) + tableCount(d.prompts) + tableCount(d.clicks) + tableCount(d.touch) + tableCount(d.spawns) end,
        info = function() return d end,
    }
end

