-- ผลตรวจยืนยันของแต่ละขั้น (ใช้ในรายงานความครบถ้วน)
local Verify = {car = nil, app = nil, route = nil, files = {}}
local Auto = {active = false, cancel = false, step = 0, total = 0, label = ""}
local Run = {active = false, cancel = false, total = 0, done = 0, sel = {}, t0 = 0, label = ""}
local saveOne, saveAll, verifyFiles, coverageReport

--==================================================================
-- V8 ส่วนที่ 1: รายงานข้อผิดพลาด (ชื่อฟังก์ชัน+บรรทัด) | ตรวจระบบก่อนสแกน | ทดสอบตัวเอง | ตรวจ JSON ทุกไฟล์
--==================================================================
local ErrLog = {list = {}, index = {}, total = 0, overflow = 0}
local Diag = {skip = false, probeDone = false, probeOk = nil, probeWhy = nil, lastPre = nil, lastTest = nil, handlers = {}, watch = {}}
local ERR_CAP = 120
local PROBE = "selftest_probe.json"

-- xpcall ส่งอาร์กิวเมนต์ต่อได้ไหม (Luau ได้ / บางตัวรันอาจไม่ได้)
do
    local ok, ok2, v = pcall(xpcall, function(a) return a end, function(e) return e end, 7)
    Diag.xpArgs = (ok and ok2 == true and v == 7) and true or false
end

-- แยกบรรทัด/ชื่อฟังก์ชัน/ข้อความจากข้อความ error หรือ traceback (รูปแบบ Luau: ที่เก็บ:123: ข้อความ)
local function parseTrace(tb)
    tb = tostring(tb or "")
    local first = string.match(tb, "^[^\n]*") or ""
    local line = string.match(first, ":(%d+):")
    local fn
    local isFirst = true
    for ln in string.gmatch(tb, "[^\n]+") do
        if not fn then fn = string.match(ln, "function ([%w_%.:]+)") end
        if not line and not isFirst then line = string.match(ln, ":(%d+)") or string.match(ln, "[Ll]ine (%d+)") end
        isFirst = false
        if fn and line then break end
    end
    local clean = (string.gsub(first, "^.-:%d+:%s*", ""))
    if clean == "" then clean = first end
    return {line = tonumber(line), func = fn or "?", msg = cut(clean, 160)}
end

function ErrLog.add(scope, tb)
    local p = parseTrace(tb)
    scope = tostring(scope or "?")
    local key = scope .. "|" .. p.func .. "|" .. tostring(p.line) .. "|" .. string.sub(p.msg, 1, 60)
    ErrLog.total = ErrLog.total + 1
    local e = ErrLog.index[key]
    if e then
        e.count, e.last = e.count + 1, os.time()
        return e
    end
    if #ErrLog.list >= ERR_CAP then
        ErrLog.overflow = ErrLog.overflow + 1
        return nil
    end
    e = {scope = scope, func = p.func, line = p.line, msg = p.msg, count = 1, first = os.time(), last = os.time(), trace = cut(tostring(tb), 600)}
    ErrLog.index[key] = e
    ErrLog.list[#ErrLog.list + 1] = e
    logf(string.format("ข้อผิดพลาดใหม่ [%s] ฟังก์ชัน %s บรรทัด %s: %s", scope, p.func, tostring(p.line or "?"), p.msg), "err")
    return e
end

function ErrLog.text()
    if ErrLog.total == 0 then return "ยังไม่มีข้อผิดพลาดที่บันทึกไว้ในรอบนี้" end
    local arr = {}
    for i, e in ipairs(ErrLog.list) do arr[i] = e end
    table.sort(arr, function(a, b)
        if a.count ~= b.count then return a.count > b.count end
        return a.first < b.first
    end)
    local out = {string.format("ข้อผิดพลาดทั้งหมด %d ครั้ง (%d แบบ)%s", ErrLog.total, #arr, ErrLog.overflow > 0 and (" + เกินเพดานที่ไม่ได้แยกแบบ " .. ErrLog.overflow) or "")}
    for i = 1, math.min(#arr, 12) do
        local e = arr[i]
        out[#out + 1] = string.format("• [%s] ฟังก์ชัน %s บรรทัด %s ×%d — %s", e.scope, e.func, tostring(e.line or "?"), e.count, e.msg)
    end
    return table.concat(out, "\n")
end

function ErrLog.save()
    if ErrLog.total == 0 then return false end
    local data = {meta = {tool = "BALL KUN SCANNER", version = VERSION, placeId = game.PlaceId, time = os.date("%Y-%m-%d %H:%M:%S")},
        total = ErrLog.total, overflow = ErrLog.overflow, errors = ErrLog.list}
    local ok, js = pcall(function() return HttpService:JSONEncode(sanitize(data)) end)
    if not ok then return false end
    return (writeFile("errors.json", js))
end

-- ตัวจับ error สำหรับ xpcall (แคชตามชื่อขอบเขต ไม่สร้างฟังก์ชันใหม่ทุกครั้ง)
function Diag.handler(scope)
    local h = Diag.handlers[scope]
    if not h then
        h = function(e)
            local okT, tb = pcall(debug.traceback, tostring(e), 2)
            ErrLog.add(scope, okT and tb or tostring(e))
            return e
        end
        Diag.handlers[scope] = h
    end
    return h
end

-- แทน pcall: คืน ok, ผลลัพธ์ (เหมือน pcall) แต่ถ้าพังจะลง ErrLog พร้อมฟังก์ชัน/บรรทัด
function Diag.try(scope, fn, ...)
    if Diag.xpArgs then return xpcall(fn, Diag.handler(scope), ...) end
    local ok, res = pcall(fn, ...)
    if not ok then ErrLog.add(scope, res) end
    return ok, res
end

-- ---------- รายงานตรวจระบบ ----------
local MARK = {ok = "✅", warn = "⚠️", bad = "❌"}
local function newReport() return {items = {}, counts = {ok = 0, warn = 0, bad = 0}} end
local function addItem(rep, level, name, detail)
    rep.items[#rep.items + 1] = {level = level, name = name, detail = detail or ""}
    rep.counts[level] = rep.counts[level] + 1
end
local function finishReport(rep, title)
    local lines = {}
    for _, it in ipairs(rep.items) do
        lines[#lines + 1] = MARK[it.level] .. " " .. it.name .. (it.detail ~= "" and (" — " .. it.detail) or "")
    end
    rep.head = string.format("%s: ผ่าน %d | เตือน %d | ผิดปกติ %d", title, rep.counts.ok, rep.counts.warn, rep.counts.bad)
    rep.text = "=== " .. rep.head .. " ===\n" .. table.concat(lines, "\n")
    return rep
end
local function fnLine(f)
    local ok, _, line = pcall(debug.info, f, "sl")
    if ok and type(line) == "number" then return line end
    return nil
end

local REQUIRED_FN = {"visit", "finish", "items", "export", "total", "reset"}
local KNOWN_ROOTS = {Workspace = true, ReplicatedStorage = true, ReplicatedFirst = true, PlayerGui = true}

local function checkScanner(rep, id)
    local sc = Scanners[id]
    if type(sc) ~= "table" then addItem(rep, "bad", "ตัวสแกน " .. tostring(id), "ไม่มีตัวสแกนนี้ลงทะเบียน") return false end
    local name = (sc.icon or "") .. " " .. (sc.thai or id)
    local missing = {}
    for _, f in ipairs(REQUIRED_FN) do if type(sc[f]) ~= "function" then missing[#missing + 1] = f .. "()" end end
    if type(sc.roots) ~= "table" then missing[#missing + 1] = "roots" end
    if type(sc.file) ~= "string" or sc.file == "" then missing[#missing + 1] = "file" end
    if #missing > 0 then addItem(rep, "bad", name, "ขาด: " .. table.concat(missing, ", ")) return false end
    for r in pairs(sc.roots) do
        if not KNOWN_ROOTS[r] then addItem(rep, "warn", name, "roots มีชื่อที่สแกนไม่รู้จัก: " .. tostring(r) .. " (จะไม่ถูกสแกน)") end
    end
    local okT, n = pcall(sc.total)
    if not okT or type(n) ~= "number" then addItem(rep, "bad", name, "total() ใช้ไม่ได้: " .. cut(n, 80)) return false end
    local okI, its = pcall(sc.items)
    if not okI or type(its) ~= "table" then addItem(rep, "bad", name, "items() ใช้ไม่ได้: " .. cut(its, 80)) return false end
    addItem(rep, "ok", name, "ฟังก์ชันครบ (total=" .. n .. ")")
    return true
end

local function checkJson(rep)
    local sample = {t = "ทดสอบ ✓ ไทย", n = 1.5, list = {1, 2, 3}, b = true}
    local ok, js = pcall(function() return HttpService:JSONEncode(sample) end)
    if not ok then addItem(rep, "bad", "JSON เข้ารหัส", "JSONEncode ใช้ไม่ได้: " .. cut(js, 80)) return end
    local ok2, back = pcall(function() return HttpService:JSONDecode(js) end)
    if not ok2 or type(back) ~= "table" or back.t ~= sample.t or back.n ~= 1.5 or type(back.list) ~= "table" or #back.list ~= 3 then
        addItem(rep, "bad", "JSON ถอดรหัส", "อ่านกลับแล้วข้อมูลไม่ตรง") return
    end
    addItem(rep, "ok", "JSON เข้ารหัส/ถอดรหัส", "ภาษาไทยและตัวเลขอ่านกลับถูกต้อง")
end

local function cleanupProbe(name)
    if type(delfile) == "function" then
        for _, n in ipairs({name, "backup1_" .. name, "backup2_" .. name}) do pcall(delfile, FOLDER .. "/" .. n) end
    end
end

-- เขียนไฟล์ทดสอบแล้วอ่านกลับ (ทำครั้งเดียวต่อรอบ เก็บผลไว้)
local function fileProbe(force)
    if Diag.probeDone and not force then return Diag.probeOk, Diag.probeWhy end
    Diag.probeDone = true
    if type(writefile) ~= "function" then Diag.probeOk, Diag.probeWhy = false, "ตัวรันไม่มี writefile" return false, Diag.probeWhy end
    local okP, res, why = pcall(function()
        local payload = HttpService:JSONEncode({probe = true, t = os.time(), text = "ทดสอบ"})
        local w, info = writeFile(PROBE, payload)
        if not w then return false, tostring(info) end
        if type(readfile) ~= "function" then return true, "เขียนได้ แต่ตัวรันไม่มี readfile อ่านกลับตรวจไม่ได้" end
        if readFile(PROBE) ~= payload then return false, "อ่านกลับมาไม่ตรงกับที่เขียน" end
        return true, "เขียนแล้วอ่านกลับตรงกัน"
    end)
    if not okP then Diag.probeOk, Diag.probeWhy = false, "ตรวจไฟล์ล้มเหลว: " .. cut(res, 80)
    else Diag.probeOk, Diag.probeWhy = res, why end
    return Diag.probeOk, Diag.probeWhy
end
local function quickInto(rep, ids)
    checkJson(rep)
    local list = ids or ORDER
    for _, id in ipairs(list) do checkScanner(rep, id) end
    local okP, why = fileProbe(false)
    if okP then addItem(rep, "ok", "เขียน/อ่านไฟล์", tostring(why))
    else addItem(rep, "warn", "เขียน/อ่านไฟล์", tostring(why) .. " (สแกนได้ แต่บันทึกไฟล์อาจไม่สำเร็จ)") end
    if not Diag.xpArgs then addItem(rep, "warn", "xpcall ส่งอาร์กิวเมนต์", "ไม่รองรับ จะใช้ pcall แทน (ยังบอกบรรทัดได้จากข้อความ error แต่ไม่มีชื่อฟังก์ชัน)") end
    -- ข้อมูลที่ถือไว้ต้องแปลงเป็น JSON ได้ ไม่งั้นสแกนนานแล้วบันทึกไม่ได้
    for _, id in ipairs(list) do
        local sc = Scanners[id]
        if type(sc) == "table" and type(sc.export) == "function" then
            local okE, data = pcall(sc.export)
            if not okE or type(data) ~= "table" then
                addItem(rep, "warn", (sc.thai or id) .. ": ข้อมูลที่จะบันทึก", "ดึงไม่ได้: " .. cut(data, 80))
            elseif not pcall(function() return HttpService:JSONEncode(sanitize(data)) end) then
                addItem(rep, "warn", (sc.thai or id) .. ": ข้อมูลที่จะบันทึก", "แปลงเป็น JSON ไม่ได้ (บันทึกจะล้มเหลว)")
            end
        end
    end
end

-- ตรวจเร็วก่อนเริ่มสแกน: bad = ไม่เริ่มสแกน
function Diag.quick(ids)
    local rep = newReport()
    quickInto(rep, ids)
    return finishReport(rep, "ตรวจระบบก่อนสแกน")
end

function Diag.full()
    local rep = newReport()
    quickInto(rep, nil)
    -- ฟังก์ชันหลักของโปรแกรม
    local okN, badNames, lines = 0, {}, {}
    for _, w in ipairs(Diag.watch) do
        local okG, f = pcall(w[2])
        if okG and type(f) == "function" then
            okN = okN + 1
            local ln = fnLine(f)
            if ln then lines[#lines + 1] = w[1] .. "@" .. ln end
        else
            badNames[#badNames + 1] = w[1]
        end
    end
    if #badNames > 0 then addItem(rep, "bad", "ฟังก์ชันหลักที่หายไป", table.concat(badNames, ", "))
    else addItem(rep, "ok", "ฟังก์ชันหลัก", okN .. " ตัวพร้อมใช้งาน" .. (#lines > 0 and (" (ชื่อ@บรรทัดที่ประกาศ: " .. table.concat(lines, " ") .. ")") or "")) end
    -- ความสามารถของตัวรัน
    local caps = {
        {"writefile", type(writefile) == "function"}, {"readfile", type(readfile) == "function"},
        {"isfile", type(isfile) == "function"}, {"makefolder", type(makefolder) == "function"},
        {"isfolder", type(isfolder) == "function"}, {"listfiles", type(listfiles) == "function"},
        {"delfile", type(delfile) == "function"},
        {"getcustomasset", (type(getcustomasset) == "function") or (type(getsynasset) == "function")},
    }
    local have, miss = {}, {}
    for _, c in ipairs(caps) do if c[2] then have[#have + 1] = c[1] else miss[#miss + 1] = c[1] end end
    local critical = not (type(readfile) == "function" and type(isfile) == "function" and type(makefolder) == "function")
    addItem(rep, critical and "warn" or "ok", "ฟังก์ชันของตัวรัน", "มี: " .. table.concat(have, ", ") .. (#miss > 0 and (" | ไม่มี: " .. table.concat(miss, ", ")) or ""))
    local okV = pcall(function() return game:GetService("VirtualInputManager") end)
    if okV then addItem(rep, "ok", "VirtualInputManager", "พร้อมสำหรับปุ่ม ⚡ (กด G / คลิก UI โทรศัพท์)")
    else addItem(rep, "warn", "VirtualInputManager", "ใช้ไม่ได้: ปุ่ม ⚡ เรียกรถ/เปิดแอปอัตโนมัติจะทำไม่ได้ (สแกนยังใช้ได้)") end
    local ch = LP.Character
    local hum = ch and ch:FindFirstChildOfClass("Humanoid")
    local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
    if hum and hrp then addItem(rep, "ok", "ตัวละคร", "พร้อม (Humanoid + HumanoidRootPart)")
    else addItem(rep, "warn", "ตัวละคร", "ยังไม่พร้อม: โหมดเดินสำรวจต้องมีตัวละครก่อน") end
    local parts = {}
    for _, r in ipairs({{"Workspace", Workspace}, {"ReplicatedStorage", RepStorage}, {"ReplicatedFirst", RepFirst}, {"PlayerGui", PlayerGui}}) do
        local okC, kids = pcall(function() return r[2]:GetChildren() end)
        if okC then parts[#parts + 1] = r[1] .. " " .. #kids else addItem(rep, "warn", "อ่าน " .. r[1], "GetChildren ล้มเหลว") end
    end
    if #parts > 0 then addItem(rep, "ok", "พื้นที่ที่สแกนได้", table.concat(parts, " · ")) end
    local stream = Workspace.StreamingEnabled
    addItem(rep, stream and "warn" or "ok", "แมพ", "PlaceId " .. tostring(game.PlaceId) .. (stream and " · StreamingEnabled เปิดอยู่: ควรสแกนซ้ำหลายจุดเพื่อให้ข้อมูลครบ" or ""))
    finishReport(rep, "ตรวจระบบทั้งหมด")
    Diag.lastPre = rep
    return rep
end

-- ---------- ทดสอบตัวเอง ----------
local function exportLen(sc)
    return #HttpService:JSONEncode(sanitize(sc.export()))
end

function Diag.selfTest()
    local tests = {}
    local function T_(name, fn, level) tests[#tests + 1] = {name = name, fn = fn, level = level or "bad"} end

    T_("แยกชื่อฟังก์ชัน/บรรทัดจาก error", function()
        local p = parseTrace("Script:42: boom happened\nScript:42 function visit\nScript:10 function runScan")
        if p.line ~= 42 then return false, "line=" .. tostring(p.line) end
        if p.func ~= "visit" then return false, "func=" .. tostring(p.func) end
        if p.msg ~= "boom happened" then return false, "msg=" .. tostring(p.msg) end
        return true, "ได้บรรทัด 42 ฟังก์ชัน visit"
    end)
    T_("ล้างข้อมูลก่อนแปลง JSON (sanitize)", function()
        local s = sanitize({a = 0 / 0, b = math.huge, c = "ok", d = {1, 2}, e = "\xff\xfe"})
        if s.a ~= 0 or s.b ~= 0 then return false, "NaN/inf ไม่ถูกแทนที่" end
        if s.c ~= "ok" or type(s.d) ~= "table" or #s.d ~= 2 then return false, "ข้อมูลปกติเสียหาย" end
        if not pcall(function() return HttpService:JSONEncode(s) end) then return false, "ล้างแล้วยังแปลง JSON ไม่ได้" end
        return true, "NaN/inf/ไบต์เสีย ถูกจัดการแล้ว"
    end)
    T_("JSON ภาษาไทยอ่านกลับตรง", function()
        local src = {t = "ถนน อาคาร ✓", n = 12.5, l = {1, 2, 3}}
        local back = HttpService:JSONDecode(HttpService:JSONEncode(src))
        if back.t ~= src.t or back.n ~= 12.5 or #back.l ~= 3 then return false, "อ่านกลับไม่ตรง" end
        return true, "ตรง"
    end)
    T_("ตัวตรวจ JSON (jsonOk)", function()
        if jsonOk("a.json", "{bad") then return false, "ยอมรับ JSON เสีย" end
        if not jsonOk("a.json", '{"a":1}') then return false, "ปฏิเสธ JSON ดี" end
        if not jsonOk("a.txt", "ไม่ใช่ json") then return false, "ไฟล์ไม่ใช่ .json ต้องผ่านเสมอ" end
        return true, "แยก JSON ดี/เสียได้"
    end)
    T_("เรียงรายการให้คงที่ (sortedList)", function()
        local l = sortedList({b = 2, a = 1, c = 3})
        if #l ~= 3 or l[1] ~= 1 or l[2] ~= 2 or l[3] ~= 3 then return false, "ลำดับไม่คงที่" end
        return true, "เรียงตามคีย์"
    end)
    T_("คีย์ซ้ำถูกเขียนทับ และเพดาน " .. CAP .. " ทำงาน (put)", function()
        local store, cnt = {}, {}
        put(store, cnt, "t", "k1", {1}, "map")
        put(store, cnt, "t", "k1", {2}, "map")
        if tableCount(store) ~= 1 or store.k1[1] ~= 2 then return false, "คีย์ซ้ำสร้างรายการเพิ่ม" end
        local was = St.map.truncated
        for i = 1, CAP + 5 do put(store, cnt, "t", "x" .. i, {i}, "map") end
        local n, flagged = tableCount(store), St.map.truncated
        St.map.truncated = was
        if n ~= CAP then return false, "เพดานไม่ทำงาน (ได้ " .. n .. ")" end
        if not flagged then return false, "ไม่ติดธง truncated" end
        return true, "ไม่เบิ้ล และตัดที่เพดานถูกต้อง"
    end)
    T_("เขียนไฟล์ + สำรองรุ่นก่อน + อ่านกลับ", function()
        if type(writefile) ~= "function" then return false, "ตัวรันไม่มี writefile" end
        local name = "selftest_rw.json"
        local w1 = writeFile(name, '{"v":1}')
        local w2 = writeFile(name, '{"v":2}')
        if not (w1 and w2) then cleanupProbe(name) return false, "เขียนไฟล์ไม่สำเร็จ" end
        if type(readfile) ~= "function" then cleanupProbe(name) return false, "ไม่มี readfile อ่านกลับตรวจไม่ได้" end
        local cur, b1 = readFile(name), rawRead(FOLDER .. "/backup1_" .. name)
        cleanupProbe(name)
        if cur ~= '{"v":2}' then return false, "อ่านกลับไม่ตรง" end
        if b1 ~= '{"v":1}' then return false, "ไฟล์สำรองรุ่นก่อนไม่ถูกต้อง" end
        return true, "เขียน อ่านกลับ และสำรองรุ่นก่อนได้ถูกต้อง"
    end)
    for _, id in ipairs(ORDER) do
        T_("ส่งออกข้อมูล " .. id, function()
            local sc = Scanners[id]
            local data = sc.export()
            if type(data) ~= "table" then return false, "export ไม่คืนตาราง" end
            local js = HttpService:JSONEncode(sanitize(data))
            if type(HttpService:JSONDecode(js)) ~= "table" then return false, "อ่าน JSON กลับไม่ได้" end
            return true, math.max(1, math.floor(#js / 1024)) .. " KB"
        end, "warn")
    end
    for _, id in ipairs(ORDER) do
        T_("เซฟระหว่างทางซ้ำไม่เบิ้ล " .. id, function()
            if Run.active then return true, "ข้าม: กำลังสแกนอยู่" end
            if St[id].scans == 0 then return true, "ข้าม: ยังไม่เคยสแกนตัวนี้" end
            local sc = Scanners[id]
            local a, t1 = exportLen(sc), sc.total()
            local b, t2 = exportLen(sc), sc.total()
            if t1 ~= t2 or a ~= b then return false, string.format("export สองครั้งได้ผลต่างกัน (total %d→%d, ขนาด %d→%d)", t1, t2, a, b) end
            return true, "export ซ้ำได้ข้อมูลเดิม ไม่แก้ข้อมูลสด (total=" .. t2 .. ")"
        end, "warn")
    end
    T_("ตรวจระบบก่อนสแกนผ่าน", function()
        local rep = Diag.quick(nil)
        if rep.counts.bad > 0 then return false, rep.counts.bad .. " ข้อผิดปกติ (พิมพ์ ตรวจระบบ)" end
        return true, "ไม่มีข้อผิดปกติร้ายแรง"
    end)

    cleanupProbe(PROBE) -- ลบไฟล์ทดสอบที่ตัวตรวจสร้างไว้ (ไม่ให้ค้างในโฟลเดอร์)
    local rep = newReport()
    for _, t in ipairs(tests) do
        local ok, a, b = xpcall(t.fn, Diag.handler("selftest:" .. t.name))
        if not ok then
            addItem(rep, "bad", t.name, "โค้ดทดสอบพังเอง: " .. cut(a, 100) .. " (ดูรายละเอียดด้วยคำสั่ง ข้อผิดพลาด)")
        elseif a == true then
            addItem(rep, "ok", t.name, tostring(b or ""))
        else
            addItem(rep, t.level, t.name, tostring(b or "ไม่ผ่าน"))
        end
    end
    finishReport(rep, "ทดสอบตัวเอง")
    Diag.lastTest = rep
    return rep
end

-- ---------- ตรวจไฟล์ JSON ทุกไฟล์ในโฟลเดอร์ ----------
function Diag.jsonAll()
    local rep = newReport()
    local title = "ตรวจไฟล์ JSON ทั้งหมด"
    if type(readfile) ~= "function" then
        addItem(rep, "bad", "ตรวจไฟล์", "ตัวรันไม่มี readfile")
        return finishReport(rep, title)
    end
    local names, seen = {}, {}
    local function add(n) if n and not seen[n] and string.sub(n, -5) == ".json" then seen[n] = true names[#names + 1] = n end end
    local viaList = false
    if type(listfiles) == "function" then
        local ok, files = pcall(listfiles, FOLDER)
        if ok and type(files) == "table" then
            viaList = true
            for _, p in ipairs(files) do add(string.match(tostring(p), "([^/\\]+)$")) end
        end
    end
    if not viaList then
        local base = {"phone_ui.json", "settings.json", "coverage.json", "errors.json", "diagnostics.json"}
        for _, id in ipairs(ORDER) do base[#base + 1] = Scanners[id].file end
        for _, n in ipairs(base) do add(n) add("partial_" .. n) add("backup1_" .. n) add("backup2_" .. n) end
        addItem(rep, "warn", "รายชื่อไฟล์", "ตัวรันไม่มี listfiles ตรวจเฉพาะชื่อไฟล์ที่โปรแกรมรู้จัก")
    end
    table.sort(names)
    local byFile = {}
    for _, id in ipairs(ORDER) do byFile[Scanners[id].file] = id end
    local found = 0
    for _, n in ipairs(names) do
        local content = rawRead(FOLDER .. "/" .. n)
        if content then
            found = found + 1
            local kb = math.max(1, math.floor(#content / 1024))
            if #content < 2 then
                addItem(rep, "bad", n, "ไฟล์ว่าง")
            else
                local okD, data = pcall(function() return HttpService:JSONDecode(content) end)
                if not okD then
                    addItem(rep, "bad", n, "JSON เสีย อ่านไม่ได้ (" .. kb .. " KB)")
                else
                    local baseName = string.gsub(string.gsub(string.gsub(n, "^partial_", ""), "^backup1_", ""), "^backup2_", "")
                    local id = byFile[baseName]
                    local meta = type(data) == "table" and type(data.meta) == "table" and data.meta or nil
                    if id and (not meta or meta.scanner ~= id) then
                        addItem(rep, "warn", n, "JSON อ่านได้ แต่ meta ไม่ตรงกับตัวสแกน " .. id)
                    else
                        local extra = {}
                        if meta and meta.total then extra[#extra + 1] = meta.total .. " รายการ" end
                        if meta and meta.partial then extra[#extra + 1] = "partial: " .. tostring(meta.partialReason) end
                        if meta and meta.version then extra[#extra + 1] = "v" .. tostring(meta.version) end
                        addItem(rep, "ok", n, kb .. " KB อ่านได้" .. (#extra > 0 and (" · " .. table.concat(extra, " · ")) or ""))
                    end
                end
            end
        end
    end
    if found == 0 then addItem(rep, "warn", "โฟลเดอร์ " .. FOLDER, "ยังไม่มีไฟล์ JSON (สแกนและบันทึกก่อน)") end
    return finishReport(rep, title)
end

-- เก็บผลตรวจ/ทดสอบ/ข้อผิดพลาดล่าสุดเป็นไฟล์ (เขียนแล้วอ่านกลับตรวจโดย writeFile)
function Diag.save()
    local function strip(rep) return rep and {head = rep.head, counts = rep.counts, items = rep.items} or nil end
    local data = {meta = {tool = "BALL KUN SCANNER", version = VERSION, placeId = game.PlaceId, time = os.date("%Y-%m-%d %H:%M:%S")},
        preflight = strip(Diag.lastPre), selfTest = strip(Diag.lastTest), errorTotal = ErrLog.total, errors = ErrLog.list}
    local ok, js = pcall(function() return HttpService:JSONEncode(sanitize(data)) end)
    if not ok then return false end
    return (writeFile("diagnostics.json", js))
end

-- ฟังก์ชันที่ประกาศก่อนจุดนี้ (ที่เหลือลงทะเบียนตอนท้ายไฟล์)
for _, w in ipairs({
    {"writeFile", function() return writeFile end}, {"readFile", function() return readFile end},
    {"saveOne", function() return saveOne end}, {"saveAll", function() return saveAll end},
    {"verifyFiles", function() return verifyFiles end}, {"coverageReport", function() return coverageReport end},
}) do Diag.watch[#Diag.watch + 1] = w end


local REC = {stall = 25, hardKill = 40, checkpoint = 45} -- วินาที: ค้างเกินนี้สั่งหยุด / บังคับปลดล็อก / เซฟระหว่างทาง
local function savePartial(sc, why)
    Diag.try(sc.id .. ":finish", sc.finish)
    return saveOne(sc.id, true, why)
end

-- อยู่ในขอบเขตรัศมีหรือไม่ (ใช้เฉพาะเมื่อกำหนด radius และรู้ตำแหน่งตัวละคร) ดูพาเรนต์ขึ้นไปหาชิ้นส่วนที่มีตำแหน่ง
local function inScanBounds(inst)
    local r, c = ScanMgr.radius, ScanMgr.center
    if not r or not c then return true end
    local ok, res = pcall(function()
        local node = inst
        for _ = 1, 4 do
            if not node then return true end
            if node:IsA("BasePart") then
                local p = node.Position
                return math.sqrt((p.X - c.X) ^ 2 + (p.Z - c.Z) ^ 2) <= r
            elseif node:IsA("Model") then
                local p = node:GetPivot().Position
                return math.sqrt((p.X - c.X) ^ 2 + (p.Z - c.Z) ^ 2) <= r
            end
            node = node.Parent
        end
        return true
    end)
    if ok then return res end
    return true
end

local function runScan(ids)
    if Run.active then logf("กำลังสแกนอยู่ รอให้เสร็จหรือสั่ง หยุด ก่อน", "warn") return end
    if #ids == 0 then return end
    -- กรองหมวดที่ปิดไว้ (ScanMgr.enabled)
    local keep, skipped = {}, {}
    for _, id in ipairs(ids) do
        if ScanMgr.enabled[id] == false then skipped[#skipped + 1] = Scanners[id].thai else keep[#keep + 1] = id end
    end
    if #skipped > 0 then logf("ปิดการสแกนไว้ ข้าม: " .. table.concat(skipped, ", ")) end
    ids = keep
    if #ids == 0 then return end
    ScanMgr.center = ScanMgr.radius and myPos() or nil
    if ScanMgr.radius and not ScanMgr.center then logf("ไม่มีตัวละคร จึงสแกนแบบไม่จำกัดรัศมี", "warn") end
    if not Diag.skip then
        local okPre, pre = pcall(Diag.quick, ids)
        if not okPre then
            logf("ตัวตรวจระบบก่อนสแกนทำงานผิดพลาด (ข้ามการตรวจ): " .. cut(pre, 120), "warn")
        else
            Diag.lastPre = pre
            if pre.counts.bad > 0 then
                logf("ไม่เริ่มสแกน: ตรวจระบบพบปัญหาร้ายแรง " .. pre.counts.bad .. " ข้อ (พิมพ์ ตรวจระบบ ดูรายละเอียด หรือ ตรวจระบบ ข้าม เพื่อสแกนต่อทั้งที่มีปัญหา)", "err")
                for _, it in ipairs(pre.items) do
                    if it.level == "bad" then logf("  ✖ " .. it.name .. " — " .. it.detail, "err") end
                end
                return
            end
            if pre.counts.warn > 0 then logf("ตรวจระบบก่อนสแกน: เตือน " .. pre.counts.warn .. " ข้อ (พิมพ์ ตรวจระบบ ดูรายละเอียด)", "warn") end
        end
    end
    Run.token = (Run.token or 0) + 1
    local token = Run.token
    Run.active, Run.cancel, Run.done, Run.total, Run.t0 = true, false, 0, 0, os.clock()
    Run.lastTick, Run.cancelAt, Run.stalled = os.clock(), nil, false
    Run.sel = {}
    local names, before = {}, {}
    for _, id in ipairs(ids) do
        Run.sel[#Run.sel + 1] = Scanners[id]
        St[id].status = "running"
        names[#names + 1] = Scanners[id].thai
        local okT, n = pcall(Scanners[id].total)
        before[id] = okT and n or 0
    end
    Run.label = table.concat(names, " + ")
    logf("เริ่ม: " .. Run.label)

    -- ตัวเฝ้า: ค้าง → สั่งหยุด + เซฟ | ไม่ตอบสนอง → ปลดล็อก | ทุก 45 วินาที เซฟระหว่างทาง (partial_*.json)
    task.spawn(function()
        local lastCp = os.clock()
        while Run.active and Run.token == token do
            task.wait(1)
            if not (Run.active and Run.token == token) then break end
            local now = os.clock()
            if not Run.cancel and now - Run.lastTick > REC.stall then
                Run.cancel, Run.stalled, Run.cancelAt = true, true, now
                logf(string.format("สแกนค้าง: ไม่มีความคืบหน้าเกิน %d วินาที สั่งหยุดและเก็บข้อมูลที่ได้ไว้", REC.stall), "err")
            end
            if Run.cancel then
                Run.cancelAt = Run.cancelAt or now
                if now - Run.cancelAt > REC.hardKill then
                    logf("ตัวสแกนไม่ตอบสนองหลังสั่งหยุด บังคับปลดล็อก (ข้อมูลที่เก็บไว้ยังอยู่ และมีไฟล์ partial_)", "err")
                    for _, sc in ipairs(Run.sel) do
                        pcall(savePartial, sc, "forced-release")
                        St[sc.id].status = "stopped"
                    end
                    Run.active = false
                    break
                end
            elseif now - lastCp >= REC.checkpoint then
                lastCp = now
                for _, sc in ipairs(Run.sel) do pcall(savePartial, sc, "checkpoint") end
                Run.lastTick = os.clock() -- เวลาเขียนไฟล์ไม่นับเป็นค้าง
            end
        end
    end)

    task.spawn(function()
        local errCount = 0
        local ok, err = xpcall(function()
            local lists = {}
            local need = {}
            for _, sc in ipairs(Run.sel) do for r in pairs(sc.roots) do need[r] = true end end
            local rootObjs = {{"Workspace", Workspace}, {"ReplicatedStorage", RepStorage}, {"ReplicatedFirst", RepFirst}, {"PlayerGui", PlayerGui}}
            for _, ro in ipairs(rootObjs) do
                if need[ro[1]] then
                    local okd, dsc = pcall(function() return ro[2]:GetDescendants() end)
                    if okd then
                        lists[#lists + 1] = {ro[1], dsc}
                        Run.total = Run.total + #dsc
                    end
                end
            end
            logf("พบวัตถุที่ต้องตรวจ " .. Run.total .. " ชิ้น กำลังสแกน...")
            Run.lastTick = os.clock()
            for _, sc in ipairs(Run.sel) do if sc.begin then Diag.try(sc.id .. ":begin", sc.begin) end end
            local tick = 0
            for _, L in ipairs(lists) do
                local rootName, dsc = L[1], L[2]
                for i = 1, #dsc do
                    if Run.cancel or Run.token ~= token then return end
                    local inst = dsc[i]
                    for _, sc in ipairs(Run.sel) do
                        if sc.roots[rootName] and inScanBounds(inst) then
                            local okv
                            if Diag.xpArgs then
                                okv = xpcall(sc.visit, Diag.handler(sc.id), inst, rootName)
                            else
                                local o, e = pcall(sc.visit, inst, rootName)
                                okv = o
                                if not o then ErrLog.add(sc.id, e) end
                            end
                            if not okv then errCount = errCount + 1 end
                        end
                    end
                    Run.done = Run.done + 1
                    tick = tick + 1
                    if tick >= 200 or os.clock() - Run.lastTick > 0.5 then tick = 0 Run.lastTick = os.clock() task.wait() end
                end
            end
        end, debug.traceback)
        if Run.token ~= token then return end -- ถูกปลดล็อกไปแล้ว มีรอบใหม่แทน
        local cancelled = Run.cancel
        -- finish ทุกครั้ง (แม้หยุดกลางคัน) เพื่อรวมข้อมูลรอบก่อนกับรอบนี้ ไม่ให้ของเดิมหาย
        for _, sc in ipairs(Run.sel) do
            Diag.try(sc.id .. ":finish", sc.finish)
            local s = St[sc.id]
            if ok and not cancelled then
                s.status, s.scans, s.last = "done", s.scans + 1, os.time()
                local okT, now = pcall(sc.total)
                now = okT and now or 0
                local extra = ""
                if s.scans > 1 then extra = string.format(" (สแกนซ้ำ: เดิม %d → ตอนนี้ %d รายการ ข้อมูลเดิมไม่หาย)", before[sc.id] or 0, now) end
                logf(sc.thai .. " เสร็จ พบ " .. now .. " รายการ" .. extra, "ok")
            else
                s.status = cancelled and "stopped" or "error"
            end
        end
        if not ok then logf("สแกนผิดพลาด: " .. cut(err, 200), "err") ErrLog.add("scan", err) end
        if cancelled then
            logf(Run.stalled and "หยุดสแกนเพราะค้าง (เก็บข้อมูลที่ได้ไว้แล้ว)" or "หยุดสแกนตามคำสั่ง (เก็บข้อมูลที่ได้ไว้แล้ว)", "warn")
        end
        if errCount > 0 then
            logf("มี " .. errCount .. " วัตถุที่อ่านไม่ได้ (ข้ามไป) ดูฟังก์ชัน/บรรทัดที่พัง: พิมพ์ ข้อผิดพลาด ในแท็บ AI", "warn")
        end
        if ErrLog.total > 0 then pcall(ErrLog.save) end
        if ok and not cancelled and Workspace.StreamingEnabled then
            logf("แมพนี้เปิด StreamingEnabled: เดินไปหลายจุดแล้วสแกนซ้ำ ข้อมูลจะรวมกันให้", "warn")
        end
        local selCopy = Run.sel
        local saveAfter = ok and not cancelled and Set.autosave
        Run.active = false
        if not ok or cancelled then
            for _, sc in ipairs(selCopy) do pcall(savePartial, sc, Run.stalled and "stalled" or (cancelled and "stopped" or "error")) end
            logf("เซฟข้อมูลส่วนที่ได้ไว้เป็นไฟล์ partial_ แล้ว (กู้ได้จากโฟลเดอร์ " .. FOLDER .. ")", "ok")
        elseif saveAfter then
            for _, sc in ipairs(selCopy) do saveOne(sc.id, true) end
        end
    end)
end

local function stopScan()
    if Auto.active then Auto.cancel = true end
    if Run.active then Run.cancel = true end
    if Auto.active or Run.active then logf("กำลังหยุด...", "warn") else logf("ไม่มีงานที่กำลังทำอยู่") end
end

--==================================================================
-- บันทึกไฟล์
--==================================================================
local function metaTable(sc)
    return {tool = "BALL KUN SCANNER", version = VERSION, scanner = sc.id, placeId = game.PlaceId, gameId = game.GameId, jobId = game.JobId,
        time = os.date("%Y-%m-%d %H:%M:%S"), player = LP.Name, streamingEnabled = Workspace.StreamingEnabled,
        truncated = St[sc.id].truncated, total = sc.total(), scans = St[sc.id].scans}
end
function saveOne(id, quiet, partial)
    local sc, s = Scanners[id], St[id]
    if not partial and s.scans == 0 and s.status ~= "done" and s.status ~= "stopped" then
        if not quiet then logf(sc.thai .. ": ยังไม่มีข้อมูล สแกนก่อน", "warn") end
        return false
    end
    local okE, data = Diag.try(sc.id .. ":export", sc.export)
    if not okE or type(data) ~= "table" then
        logf(sc.thai .. ": ดึงข้อมูลเพื่อบันทึกไม่ได้ " .. cut(data, 100), "err")
        return false
    end
    local okM, meta = pcall(metaTable, sc)
    data.meta = okM and meta or {scanner = id}
    if partial then data.meta.partial, data.meta.partialReason = true, tostring(partial) end
    local ok, js = pcall(function() return HttpService:JSONEncode(data) end)
    if not ok then
        local ok2, js2 = pcall(function() return HttpService:JSONEncode(sanitize(data)) end)
        if ok2 then js, ok = js2, true logf(sc.thai .. ": มีอักขระเสียในข้อมูล ล้างแล้วแปลง JSON ใหม่ได้", "warn") end
    end
    if not ok then logf(sc.thai .. ": แปลงเป็น JSON ไม่ได้ " .. cut(js, 100), "err") return false end
    if not jsonOk(".json", js) then logf(sc.thai .. ": JSON ที่สร้างอ่านกลับไม่ได้ ไม่บันทึกเพื่อกันไฟล์เสีย", "err") return false end
    local fname = partial and ("partial_" .. sc.file) or sc.file
    local w, info = writeFile(fname, js, partial and true or nil)
    Verify.files[fname] = {ok = w, bytes = #js, at = os.time(), items = data.meta.total, partial = partial and true or nil, err = (not w) and tostring(info) or nil}
    if w then
        if not partial then s.saved = info end
        if not quiet or not partial then
            logf("บันทึก " .. sc.thai .. (partial and (" (partial: " .. tostring(partial) .. ")") or "") .. " → " .. info .. " (" .. math.floor(#js / 1024) .. " KB)", "ok")
        end
        return true
    end
    logf("บันทึก " .. sc.thai .. " ไม่สำเร็จ: " .. tostring(info), "err")
    return false
end

-- ดึงค่าจากฟังก์ชันของหมวดแบบปลอดภัย: ถ้าพังคืนค่าสำรองแทน (ไม่ให้คำสั่งสรุป/สถานะพังทั้งหมด)
local function sget(fn, fb)
    local ok, v = pcall(fn)
    if ok and v ~= nil then return v end
    return fb
end

local function statusText()
    local lines = {}
    for _, id in ipairs(ORDER) do
        local sc, s = Scanners[id], St[id]
        local mark = (s.status == "done" and "✅") or (s.status == "running" and "⏳") or (s.status == "stopped" and "⏹️") or (s.status == "error" and "❌") or "⬜"
        local word = (s.status == "done" and "ดัมป์แล้ว") or (s.status == "running" and "กำลังสแกน") or (s.status == "stopped" and "หยุดกลางคัน") or (s.status == "error" and "ผิดพลาด") or "ยังไม่ได้ดัมป์"
        local detail = ""
        if s.status == "done" or s.status == "stopped" then
            local parts = {}
            for i, it in ipairs(sget(sc.items, {})) do
                if i <= 4 then parts[#parts + 1] = it[1] .. " " .. it[2] end
            end
            detail = "  ·  " .. table.concat(parts, " · ")
        end
        lines[#lines + 1] = mark .. " " .. sc.icon .. " " .. sc.thai .. " — " .. word .. detail .. (s.saved and "  💾" or "")
    end
    return table.concat(lines, "\n")
end


