-- โหมดอัตโนมัติ: ปุ่มเดียว สแกน → เดินไปหลายจุด → สแกนซ้ำ → บันทึก → AI สรุป
--==================================================================
local PathfindingService = game:GetService("PathfindingService")
local KNOWN_STOPS = { -- จุดที่พบจากไฟล์สำรวจของแมพ MAHANAKHON RACING
    {115, 4, -77}, {93, 5, -184}, {93, 5, -133}, {181, 3, -84}, {-154, 4, 63}, {-112, 6, 36},
    {104, 4, 375}, {811, 4, 88}, {-70, 3, -600},
}
-- จุดเดินทางที่บันทึกไว้ล่วงหน้า แยกตาม PlaceId (ใช้เฉพาะแมพที่บันทึกไว้เท่านั้น แมพอื่นไม่ใช้จุดพวกนี้)
local KNOWN_STOPS_BY_PLACE = {
    [104549080643413] = KNOWN_STOPS,
}

local function getHum() local ch = LP.Character return ch and ch:FindFirstChildOfClass("Humanoid") end
local function getHRP() local ch = LP.Character return ch and ch:FindFirstChild("HumanoidRootPart") end
local function flat(a, b) return math.sqrt((a.X - b.X) ^ 2 + (a.Z - b.Z) ^ 2) end

local function walkTo(target)
    local hum, hrp = getHum(), getHRP()
    if not hum or not hrp then return false end
    if hum.SeatPart then hum.Sit = false task.wait(0.6) end
    local t0, best, stuck = os.clock(), math.huge, 0
    while os.clock() - t0 < 100 and not Auto.cancel do
        hrp = getHRP()
        hum = getHum()
        if not hrp or not hum then return false end
        local d = flat(hrp.Position, target)
        if d <= 10 then return true end
        if d < best - 3 then best, stuck = d, 0 else stuck = stuck + 1 end
        if stuck >= 6 then return false end
        local path = PathfindingService:CreatePath({AgentRadius = 2, AgentHeight = 5, AgentCanJump = true})
        local ok = pcall(function() path:ComputeAsync(hrp.Position, target) end)
        local pts
        if ok and path.Status == Enum.PathStatus.Success then pts = path:GetWaypoints()
        else pts = {{Position = target, Action = Enum.PathWaypointAction.Walk}} end
        for _, wp in ipairs(pts) do
            if Auto.cancel then return false end
            if wp.Action == Enum.PathWaypointAction.Jump then hum.Jump = true end
            hum:MoveTo(wp.Position)
            local t1 = os.clock()
            while os.clock() - t1 < 3.5 do
                local r = getHRP()
                if not r or Auto.cancel then return false end
                Auto.lastTick = os.clock()
                if flat(r.Position, wp.Position) < 4 or flat(r.Position, target) <= 10 then break end
                task.wait(0.1)
            end
            local r = getHRP()
            if r and flat(r.Position, target) <= 10 then return true end
        end
    end
    return false
end

local function waitScan() while Run.active do Auto.lastTick = os.clock() task.wait(0.25) end end

--==================================================================
-- ขั้นเตรียมของโหมด ⚡ ก่อนเริ่มสแกน: (1) เรียกรถ (กด G)  (2) เปิดแอปงานบนโทรศัพท์
-- ใช้เฉพาะ VirtualInputManager ส่งปุ่ม/คลิก UI ปกติ — ไม่เรียก FireServer/InvokeServer ไม่ hook
-- ไม่กดรับงาน/ยืนยัน/รับเงิน/จุดซื้อ Robux | ทุกขั้นมี timeout | หยุดได้ด้วย RightShift (Auto.cancel)
--==================================================================
local PreSteps = {}
do
    local GuiService = game:GetService("GuiService")
    local PRE = {
        carTries = 3,        -- ลองเรียกรถไม่เกินกี่ครั้ง
        carWait = 3,         -- รอกี่วินาทีหลังกด G ก่อนเช็กที่นั่งใหม่
        appWait = 2,         -- รอกี่วินาทีหลังกดไอคอนแอปงาน ก่อนสแกนข้อความ
        phoneTimeout = 30,   -- เวลารวมสูงสุดของขั้นเปิดแอปงาน (วินาที)
        openPoll = 6,        -- รอให้โทรศัพท์เปิดหลังคลิกปุ่มเปิด (วินาที)
        uiTextMax = 400,     -- เก็บข้อความ UI ได้สูงสุดกี่รายการ
        phoneKeys = {"phone", "โทรศัพท์", "มือถือ", "mobile"},
        appKeys = {"job", "deliver", "courier", "gig", "งาน", "ส่งของ", "ส่งอาหาร", "ส่งพัสดุ"},
        closeNames = {"close", "closebutton", "closebtn", "back", "backbutton", "backbtn", "home", "homebutton", "exit", "x", "×", "✕", "✖", "ปิด", "กลับ"},
        -- คำต้องห้าม: ปุ่มที่มีคำเหล่านี้ (ในชื่อ/ข้อความ/พาธ) จะไม่ถูกกดเด็ดขาด
        bad = {"accept", "รับงาน", "confirm", "ยืนยัน", "claim", "collect", "รับเงิน", "รับรางวัล", "รับของ", "cashout", "cash out",
            "withdraw", "ถอน", "robux", "r$", "buy", "purchase", "gamepass", "game pass", "shop", "store", "ซื้อ", "เติม", "premium", "vip", "donate", "โดเนท"},
    }
    local PHONE_FILE = "phone_ui.json"

    local function getVIM()
        local ok, v = pcall(function() return game:GetService("VirtualInputManager") end)
        if ok and v then return v end
        return nil
    end

    -- รอแบบหยุดได้ทันทีเมื่อกด RightShift
    local function sleepC(sec)
        local t0 = os.clock()
        while os.clock() - t0 < sec do
            Auto.lastTick = os.clock()
            if Auto.cancel then return false end
            task.wait(0.1)
        end
        return not Auto.cancel
    end

    local function anyWord(s, list)
        for _, w in ipairs(list) do
            if string.find(s, w, 1, true) then return true end
        end
        return false
    end

    local function isShown(obj)
        local cur = obj
        while cur and cur ~= PlayerGui do
            if cur:IsA("ScreenGui") and not cur.Enabled then return false end
            if cur:IsA("GuiObject") and not cur.Visible then return false end
            cur = cur.Parent
        end
        if obj:IsA("GuiObject") then return obj.AbsoluteSize.X > 0 and obj.AbsoluteSize.Y > 0 end
        return true
    end

    local function onScreen(obj)
        if not isShown(obj) then return false end
        local cam = Workspace.CurrentCamera
        local vs = cam and cam.ViewportSize or Vector2.new(1920, 1080)
        local p, s = obj.AbsolutePosition, obj.AbsoluteSize
        return p.X < vs.X and p.Y < vs.Y and p.X + s.X > 0 and p.Y + s.Y > 0
    end

    local function isOwnGui(obj)
        local sg = obj:FindFirstAncestorOfClass("ScreenGui")
        return sg ~= nil and sg.Name == "BALLKUN_SCANNER_V7"
    end

    -- ชื่อ + ข้อความของปุ่ม + ชื่อ/ข้อความลูก ๆ (ตัวพิมพ์เล็ก)
    local function guiBlob(obj)
        local parts = {obj.Name}
        if obj:IsA("TextButton") then parts[#parts + 1] = obj.Text end
        local n = 0
        for _, d in ipairs(obj:GetDescendants()) do
            n = n + 1
            if n > 40 then break end
            parts[#parts + 1] = d.Name
            if d:IsA("TextLabel") or d:IsA("TextButton") then parts[#parts + 1] = d.Text end
        end
        return string.lower(table.concat(parts, " "))
    end

    local function isForbidden(obj)
        return anyWord(guiBlob(obj) .. " " .. string.lower(pathOf(obj)), PRE.bad)
    end

    local function isButton(d) return d:IsA("TextButton") or d:IsA("ImageButton") end

    -- คลิกกลางปุ่มด้วยเมาส์จำลอง (เหมือนผู้เล่นคลิกจริง)
    local function clickGui(vim, obj)
        if not obj:IsA("GuiObject") then return false end
        local sg = obj:FindFirstAncestorOfClass("ScreenGui")
        local inset = Vector2.new(0, 0)
        if sg and not sg.IgnoreGuiInset then
            local ok, v = pcall(function() return GuiService:GetGuiInset() end)
            if ok and v then inset = v end
        end
        local c = obj.AbsolutePosition + obj.AbsoluteSize / 2 + inset
        local ok, err = pcall(function()
            vim:SendMouseMoveEvent(c.X, c.Y, game)
            task.wait(0.05)
            vim:SendMouseButtonEvent(c.X, c.Y, 0, true, game, 0)
            task.wait(0.06)
            vim:SendMouseButtonEvent(c.X, c.Y, 0, false, game, 0)
        end)
        if not ok then logf("คลิก UI ไม่สำเร็จ: " .. cut(err, 120), "err") end
        return ok
    end

    local function findAppButton(phone)
        for _, d in ipairs(phone:GetDescendants()) do
            if isButton(d) and onScreen(d) and anyWord(guiBlob(d), PRE.appKeys) and not isForbidden(d) then return d end
        end
        return nil
    end

    local function findOpener(phone)
        for _, d in ipairs(PlayerGui:GetDescendants()) do
            if isButton(d) and not isOwnGui(d) and onScreen(d) then
                -- ปุ่มในโทรศัพท์ที่เป็นไอคอนแอปงานไม่นับเป็นปุ่มเปิดโทรศัพท์
                local isApp = d:IsDescendantOf(phone) and anyWord(guiBlob(d), PRE.appKeys)
                if not isApp and anyWord(guiBlob(d), PRE.phoneKeys) and not isForbidden(d) then return d end
            end
        end
        return nil
    end

    local function matchesClose(s)
        s = string.lower((string.gsub(s or "", "%s+", "")))
        for _, w in ipairs(PRE.closeNames) do
            if s == w then return true end
        end
        return false
    end

    local function findCloseButton(phone)
        for _, d in ipairs(phone:GetDescendants()) do
            if isButton(d) and onScreen(d) then
                local hit = matchesClose(d.Name) or (d:IsA("TextButton") and matchesClose(d.Text))
                if not hit then
                    for _, ch in ipairs(d:GetChildren()) do
                        if ch:IsA("TextLabel") and matchesClose(ch.Text) then hit = true break end
                    end
                end
                if hit and not isForbidden(d) then return d end
            end
        end
        return nil
    end

    local function scanPhoneTexts(phone)
        local out, visibleN = {}, 0
        for _, d in ipairs(phone:GetDescendants()) do
            if (d:IsA("TextLabel") or d:IsA("TextButton")) and d.Text ~= "" and #out < PRE.uiTextMax then
                local vis = isShown(d)
                if vis then visibleN = visibleN + 1 end
                out[#out + 1] = {text = cut(d.Text, 100), class = d.ClassName, visible = vis, path = cut(pathOf(d), 160)}
            end
        end
        return out, visibleN
    end

    local function collectSeats()
        local set = {}
        for _, d in ipairs(Workspace:GetDescendants()) do
            if d:IsA("VehicleSeat") or d:IsA("Seat") then set[d] = true end
        end
        return set
    end

    local function visibleTextSet(phone)
        local set, n = {}, 0
        for _, d in ipairs(phone:GetDescendants()) do
            if (d:IsA("TextLabel") or d:IsA("TextButton")) and d.Text ~= "" and isShown(d) then
                set[d.Text] = true
                n = n + 1
            end
        end
        return set, n
    end
    local function newTextsOf(before, after)
        local list = {}
        for t in pairs(after) do if not before[t] then list[#list + 1] = t end end
        return list
    end

    ------------------------------------------------------------------
    -- ขั้นที่ 1: เรียกรถ (ส่งปุ่ม G แล้วรอ 3 วินาที เช็กที่นั่งใหม่ ลองไม่เกิน 3 ครั้ง)
    -- ตรวจยืนยัน: ที่นั่งต้องอยู่ใน Workspace / ไม่ถูกปิดใช้งาน / ยังอยู่หลังรออีก 1 วินาที / อยู่ใกล้ตัว (<= 300 studs)
    -- ผลเก็บใน Verify.car (ใช้ในรายงานความครบถ้วน)
    ------------------------------------------------------------------
    function PreSteps.summonCar()
        Auto.label = "เรียกรถ (กด G)"
        local R = {ok = false, level = "fail", attempts = 0, reason = "ยังไม่ได้ทำ"}
        Verify.car = R
        local vim = getVIM()
        if not vim then
            R.reason = "ตัวรันนี้ใช้ VirtualInputManager ไม่ได้"
            logf("ขั้นที่ 1 เรียกรถ: " .. R.reason .. " ข้ามขั้นนี้", "err")
            return false
        end
        logf("ขั้นที่ 1 เรียกรถ: เริ่ม (กด G ไม่เกิน " .. PRE.carTries .. " ครั้ง ครั้งละรอ " .. PRE.carWait .. " วินาที)")
        local before = collectSeats()
        local lastUncertain = false
        for attempt = 1, PRE.carTries do
            if Auto.cancel then R.reason = "ถูกสั่งหยุด" return false end
            R.attempts = attempt
            R.level, R.reason = "fail", "ยังไม่พบที่นั่งใหม่"
            if UIS:GetFocusedTextBox() then
                R.reason = "กำลังพิมพ์ในช่องข้อความ จึงข้ามการกด G"
                logf(string.format("เรียกรถ: ครั้งที่ %d/%d กำลังพิมพ์ในช่องข้อความอยู่ ข้ามการกด G ครั้งนี้", attempt, PRE.carTries), "warn")
                if not sleepC(1) then return false end
            else
                if lastUncertain then
                    logf(string.format("เรียกรถ: ครั้งที่ %d/%d มีที่นั่งเดิมที่ยืนยันไม่ผ่าน จะรอแล้วเช็กซ้ำโดยไม่กด G อีก", attempt, PRE.carTries))
                    if not sleepC(PRE.carWait) then R.reason = "ถูกสั่งหยุด" return false end
                else
                    logf(string.format("เรียกรถ: ครั้งที่ %d/%d กดปุ่ม G แล้วรอ %d วินาที", attempt, PRE.carTries, PRE.carWait))
                    local ok, err = pcall(function()
                        vim:SendKeyEvent(true, Enum.KeyCode.G, false, game)
                        task.wait(0.1)
                        vim:SendKeyEvent(false, Enum.KeyCode.G, false, game)
                    end)
                    if not ok then
                        R.reason = "ส่งปุ่ม G ไม่สำเร็จ: " .. cut(err, 100)
                        logf("เรียกรถ: " .. R.reason, "err")
                        return false
                    end
                    if not sleepC(PRE.carWait) then R.reason = "ถูกสั่งหยุด" return false end
                end
                local after = collectSeats()
                local hrp = getHRP()
                local best, bestD, newCount = nil, nil, 0
                for s in pairs(after) do
                    if not before[s] then
                        newCount = newCount + 1
                        local d = hrp and (hrp.Position - s.Position).Magnitude or 0
                        if not best or d < bestD then best, bestD = s, d end
                    end
                end
                if best then
                    if not sleepC(1) then R.reason = "ถูกสั่งหยุด" return false end
                    local alive = best.Parent ~= nil and best:IsDescendantOf(Workspace)
                    local disabled = false
                    pcall(function() disabled = best.Disabled end)
                    local hrp2 = getHRP()
                    local dist = (hrp2 and alive) and (hrp2.Position - best.Position).Magnitude or bestD
                    R.seat, R.class, R.dist, R.newSeats = cut(pathOf(best), 160), best.ClassName, r1(dist), newCount
                    if alive and not disabled and dist <= 300 then
                        R.ok, R.level = true, "ok"
                        R.reason = string.format("พบ %s ใหม่ ห่าง %.0f studs และยังอยู่หลังรอเพิ่ม 1 วินาที", best.ClassName, dist)
                        logf(string.format("เรียกรถสำเร็จและยืนยันแล้ว: %s \"%s\" ห่างตัว %.0f studs (ลองครั้งที่ %d, ที่นั่งใหม่ทั้งหมด %d)", best.ClassName, best.Name, dist, attempt, newCount), "ok")
                        return true
                    end
                    R.level = "uncertain"
                    lastUncertain = true
                    R.reason = string.format("พบที่นั่งใหม่แต่ยืนยันไม่ผ่าน (%s)", (not alive) and "หายไปแล้ว" or (disabled and "ถูกปิดใช้งาน" or string.format("ไกลเกินไป %.0f studs", dist)))
                    logf("เรียกรถ: " .. R.reason .. " ลองต่อ", "warn")
                else
                    lastUncertain = false
                    logf(string.format("เรียกรถ: ครั้งที่ %d ยังไม่พบ VehicleSeat/Seat ใหม่ใน Workspace", attempt), "warn")
                end
            end
        end
        if R.level ~= "uncertain" then
            R.level, R.reason = "fail", "ลองครบ " .. PRE.carTries .. " ครั้งแล้วยังไม่พบที่นั่งใหม่"
        end
        logf("เรียกรถ: ไม่สำเร็จ (" .. R.reason .. ") ข้ามไปขั้นถัดไป", "warn")
        return false
    end

    ------------------------------------------------------------------
    -- ขั้นที่ 2: เปิดแอปงานบนโทรศัพท์ (คลิก UI) รอ 2 วินาที สแกนข้อความ UI แล้วปิดแอป
    -- ตรวจยืนยัน: เทียบข้อความที่มองเห็นก่อน/หลังคลิก (มีข้อความใหม่ + มีคำเกี่ยวกับงาน) และตรวจว่าปิดสำเร็จ
    -- ผลเก็บใน Verify.app
    ------------------------------------------------------------------
    function PreSteps.openJobApp()
        Auto.label = "เปิดแอปงานบนโทรศัพท์"
        local R = {opened = false, closed = false, level = "fail", reason = "ยังไม่ได้ทำ", newTexts = 0, jobWords = false}
        Verify.app = R
        local function fail(msg, lv)
            R.reason, R.level = msg, lv or "fail"
            logf("ขั้นที่ 2 เปิดแอปงาน: " .. msg, "warn")
            return false
        end
        local vim = getVIM()
        if not vim then return fail("ตัวรันนี้ใช้ VirtualInputManager ไม่ได้") end
        local phone = PlayerGui:FindFirstChild("Phone")
        if not phone then return fail("ไม่พบ PlayerGui.Phone (ชื่อ UI โทรศัพท์อาจต่างจากเกมนี้)") end
        logf("ขั้นที่ 2 เปิดแอปงาน: เริ่ม (เวลารวมไม่เกิน " .. PRE.phoneTimeout .. " วินาที)")
        local deadline = os.clock() + PRE.phoneTimeout
        local function alive() return os.clock() < deadline and not Auto.cancel end

        local app = findAppButton(phone)
        if not app then
            logf("เปิดแอปงาน: ยังไม่เห็นไอคอนแอปงาน กำลังหาปุ่มเปิดโทรศัพท์")
            local opener = findOpener(phone)
            if not opener then return fail("ไม่พบปุ่มเปิดโทรศัพท์บนหน้าจอ (ปรับ PRE.phoneKeys ให้ตรงชื่อปุ่มในเกม)") end
            logf("เปิดแอปงาน: คลิกปุ่มเปิดโทรศัพท์ \"" .. cut(opener.Name, 40) .. "\"")
            clickGui(vim, opener)
            local pollEnd = math.min(deadline, os.clock() + PRE.openPoll)
            while not app and os.clock() < pollEnd and not Auto.cancel do
                if not sleepC(0.5) then break end
                app = findAppButton(phone)
            end
        end
        if Auto.cancel then R.reason = "ถูกสั่งหยุด" return false end
        if not app then return fail("ไม่พบไอคอนแอปงาน/ส่งของ (หมดเวลาหรือชื่อไม่ตรงกับ PRE.appKeys)") end
        if not alive() then return fail("หมดเวลา") end

        local before = visibleTextSet(phone)
        logf("เปิดแอปงาน: คลิกไอคอนแอป \"" .. cut(app.Name, 40) .. "\" แล้วรอ " .. PRE.appWait .. " วินาที")
        clickGui(vim, app)
        if not sleepC(PRE.appWait) then R.reason = "ถูกสั่งหยุด" return false end
        local mid = visibleTextSet(phone)
        local fresh = newTextsOf(before, mid)
        local iconStill = app.Parent ~= nil and onScreen(app)
        if #fresh == 0 and iconStill and alive() then
            logf("ยืนยันแอปงาน: หน้าจอยังไม่เปลี่ยนหลังคลิก ลองคลิกซ้ำอีก 1 ครั้ง", "warn")
            clickGui(vim, app)
            if not sleepC(PRE.appWait) then R.reason = "ถูกสั่งหยุด" return false end
            mid = visibleTextSet(phone)
            fresh = newTextsOf(before, mid)
            iconStill = app.Parent ~= nil and onScreen(app)
        end
        R.newTexts = #fresh
        for _, t in ipairs(fresh) do
            if has(string.lower(t), unpack(JOBKW)) then R.jobWords = true break end
        end
        R.opened = (#fresh > 0) -- เปิดแอปได้ต่อเมื่อข้อความบนโทรศัพท์เปลี่ยนจริง (ไอคอนหายอย่างเดียวไม่นับ)
        if R.opened and R.jobWords then
            R.level, R.reason = "ok", string.format("แอปงานเปิดแล้ว (ข้อความใหม่ %d รายการ และพบคำเกี่ยวกับงาน)", #fresh)
            logf("ยืนยันแอปงาน: " .. R.reason, "ok")
        elseif R.opened then
            R.level, R.reason = "uncertain", string.format("หน้าจอเปลี่ยน (ข้อความใหม่ %d รายการ) แต่ไม่พบคำเกี่ยวกับงาน อาจเปิดผิดแอป", #fresh)
            logf("ยืนยันแอปงาน: " .. R.reason, "warn")
        else
            R.level, R.reason = "fail", "คลิกแล้วหน้าจอไม่เปลี่ยน แอปงานน่าจะไม่เปิด"
            logf("ยืนยันแอปงาน: " .. R.reason, "warn")
        end

        local texts, visibleN = scanPhoneTexts(phone)
        local okJ, json = pcall(function() return HttpService:JSONEncode({scannedAt = os.date("%Y-%m-%d %H:%M:%S"), app = app.Name, verify = R, total = #texts, visible = visibleN, texts = texts}) end)
        logf(string.format("สแกนข้อความ UI ของโทรศัพท์: พบ %d รายการ (มองเห็นอยู่ %d)", #texts, visibleN), "ok")
        local shown = 0
        for _, t in ipairs(texts) do
            if t.visible and shown < 6 then shown = shown + 1 logf("  ข้อความ: " .. cut(t.text, 60)) end
        end
        if okJ then
            local okW, why = writeFile(PHONE_FILE, json)
            if okW then logf("บันทึกข้อความ UI ลงไฟล์ " .. FOLDER .. "/" .. PHONE_FILE, "ok")
            else logf("บันทึกไฟล์ข้อความ UI ไม่ได้: " .. tostring(why) .. " (ข้อมูลยังอยู่ในหน่วยความจำรอบนี้)", "warn") end
        end
        PreSteps.phoneTexts = texts

        if Auto.cancel then R.reason = R.reason .. " (ถูกสั่งหยุดก่อนปิดแอป)" return false end
        local closeBtn = findCloseButton(phone)
        if closeBtn then
            logf("ปิดแอป: คลิกปุ่ม \"" .. cut(closeBtn.Name, 40) .. "\"")
            clickGui(vim, closeBtn)
            if not sleepC(1) then return false end
            local after2 = visibleTextSet(phone)
            local remain = 0
            for _, t in ipairs(fresh) do if after2[t] then remain = remain + 1 end end
            R.closed = (#fresh == 0) or (remain <= math.floor(#fresh * 0.2))
            if R.closed then logf("ยืนยันการปิดแอป: ข้อความของแอปหายไปแล้ว (ไม่ได้กดรับงาน/ยืนยัน/รับเงินใด ๆ)", "ok")
            else logf(string.format("ยืนยันการปิดแอป: ข้อความของแอปยังเหลือ %d/%d รายการ อาจยังไม่ปิด", remain, #fresh), "warn") end
        else
            R.closed = false
            logf("ปิดแอป: ไม่พบปุ่มปิด/กลับที่ปลอดภัย จึงไม่ได้ปิดให้ (ไม่ใช้วิธีอื่นบังคับปิด)", "warn")
        end
        return R.opened
    end
end

local function autoDump()
    if Auto.active or Run.active then logf("มีงานกำลังทำอยู่ รอให้เสร็จหรือสั่ง หยุด ก่อน", "warn") return end
    Auto.active, Auto.cancel, Auto.step, Auto.total, Auto.label = true, false, 0, 1, "สแกนที่จุดเริ่มต้น"
    -- ตัวเฝ้าค้าง: ถ้าไม่มีความคืบหน้าเกิน AUTO_STALL วินาที สั่งหยุดและเก็บข้อมูลที่ได้ไว้
    local AUTO_STALL = 60
    Auto.lastTick = os.clock()
    Auto.run = (Auto.run or 0) + 1
    local myRun = Auto.run
    task.spawn(function()
        while Auto.active and Auto.run == myRun do
            task.wait(1)
            if Auto.active and Auto.run == myRun and not Auto.cancel and os.clock() - Auto.lastTick > AUTO_STALL then
                Auto.cancel = true
                logf("โหมดอัตโนมัติค้างเกิน " .. AUTO_STALL .. " วินาที สั่งหยุดและเก็บข้อมูลที่ได้ไว้", "err")
            end
        end
    end)
    task.spawn(function()
        local ok, err = xpcall(function()
            local h0 = getHRP()
            local startPos = h0 and h0.Position
            logf("⚡ โหมดอัตโนมัติเริ่มแล้ว: ทำขั้นเตรียม (เรียกรถ + เปิดแอปงาน) แล้วจึงสแกน", "ok")
            local okP, eP = pcall(PreSteps.summonCar)
            if not okP then logf("ขั้นเรียกรถผิดพลาด: " .. cut(eP, 150), "err") end
            if Auto.cancel then return end
            okP, eP = pcall(PreSteps.openJobApp)
            if not okP then logf("ขั้นเปิดแอปงานผิดพลาด: " .. cut(eP, 150), "err") end
            if Auto.cancel then return end
            Auto.label = "สแกนที่จุดเริ่มต้น"
            logf("ขั้นเตรียมเสร็จ เริ่มสแกนที่จุดเริ่มต้น")
            runScan(ORDER) waitScan()
            if Auto.cancel then return end
            -- สร้างเส้นทาง: จุดที่รู้จัก + จุดสำคัญ + จุดงานที่เจอ (ไม่ซ้ำกันในรัศมี 120 studs)
            local pts = {}
            local function add(p)
                if startPos and flat(startPos, p) < 60 then return end
                for _, q in ipairs(pts) do if flat(q, p) < 120 then return end end
                pts[#pts + 1] = p
            end
            local knownStops = KNOWN_STOPS_BY_PLACE[game.PlaceId]
            if knownStops then
                for _, k in ipairs(knownStops) do add(Vector3.new(k[1], k[2], k[3])) end
            end
            for _, r in ipairs(Scanners.map.list()) do
                if r.kind == "จุดสำคัญ" and r.p then add(Vector3.new(r.p[1], r.p[2], r.p[3])) end
            end
            for _, r in ipairs(Scanners.job.list()) do
                if r.p and r.kind ~= "ข้อความ UI" and r.enabled ~= false then add(Vector3.new(r.p[1], r.p[2], r.p[3])) end
            end
            -- ทุกแมพ: เพิ่มจุดโต้ตอบที่สแกนเจอ (จุดกด/คลิก/เทเลพอร์ต/จุดเกิด) ยกเว้นที่ติดธงซื้อ/Robux
            for _, r in ipairs(Scanners.ui.list()) do
                if r.p and r.hot and not r.buy then add(Vector3.new(r.p[1], r.p[2], r.p[3])) end
            end
            -- แมพที่แทบไม่มีจุดอะไรเลย: ใช้ตำแหน่งอาคาร/ถนนที่สแกนเจอเป็นจุดสำรวจแทน
            if #pts < 4 then
                for _, r in ipairs(Scanners.map.list()) do
                    if r.p and (r.kind == "อาคาร" or r.kind == "ถนน") then add(Vector3.new(r.p[1], r.p[2], r.p[3])) end
                end
            end
            while #pts > 18 do table.remove(pts) end
            -- เรียงแบบใกล้สุดก่อน
            local route, cur = {}, startPos or Vector3.new(0, 0, 0)
            while #pts > 0 do
                local bi, bd = 1, math.huge
                for i, p in ipairs(pts) do
                    local dd = flat(cur, p)
                    if dd < bd then bi, bd = i, dd end
                end
                cur = table.remove(pts, bi)
                route[#route + 1] = cur
            end
            Auto.total = #route + 1
            logf("วางเส้นทางสำรวจ " .. #route .. " จุด", "ok")
            Verify.route = {planned = #route, arrived = 0, failed = {}}
            for i, p in ipairs(route) do
                if Auto.cancel then break end
                Auto.step = i
                Auto.label = string.format("เดินไปจุดที่ %d/%d", i, #route)
                logf(string.format("เดินไปจุดที่ %d/%d (%.0f, %.0f)", i, #route, p.X, p.Z))
                local arrived = walkTo(p)
                if Auto.cancel then break end
                if arrived then Verify.route.arrived = Verify.route.arrived + 1
                else
                    Verify.route.failed[#Verify.route.failed + 1] = {math.floor(p.X), math.floor(p.Z)}
                    logf("ไปไม่ถึงจุดที่ " .. i .. " (ข้ามไป)", "warn")
                end
                Auto.label = string.format("สแกนที่จุดที่ %d/%d", i, #route)
                task.wait(2.5) -- รอให้แมพโหลดส่วนใกล้ตัว
                runScan({"map", "vehicle", "npc", "job", "ui"}) waitScan()
            end
            if not Auto.cancel and Set.returnStart and startPos then
                Auto.label = "กลับจุดเริ่มต้น"
                walkTo(startPos)
            end
            if not Auto.cancel then
                Auto.label = "บันทึกไฟล์และสรุป"
                saveAll()
                local fOk, fBad, fLines = verifyFiles()
                logf(string.format("ตรวจไฟล์ที่บันทึก: ผ่าน %d | มีปัญหา %d", fOk, fBad), fBad > 0 and "warn" or "ok")
                for _, ln in ipairs(fLines) do if string.sub(ln, 1, 3) ~= "✅" then logf("  " .. ln, "warn") end end
                local cov = coverageReport()
                logf("ความครบถ้วนของข้อมูล: " .. cov.head, cov.counts.ok == #cov.items and "ok" or "warn")
                for _, it in ipairs(cov.items) do
                    if it.level ~= "ok" then logf(it.icon .. " " .. it.thai .. " ไม่ครบ: " .. table.concat(it.issues, " | "), "warn") end
                end
                logf("⚡ โหมดอัตโนมัติเสร็จสมบูรณ์ ดูรายงานเต็มพิมพ์ รายงาน หรือ สรุป", "ok")
            end
        end, debug.traceback)
        if not ok then logf("โหมดอัตโนมัติผิดพลาด: " .. cut(err, 200), "err") end
        if Auto.cancel then
            logf("หยุดโหมดอัตโนมัติแล้ว (ข้อมูลที่เก็บไว้ยังอยู่)", "warn")
            for _, id in ipairs(ORDER) do
                if St[id].scans > 0 or St[id].status == "stopped" then pcall(saveOne, id, true, "auto-stopped") end
            end
            logf("เซฟข้อมูลที่ได้ไว้เป็นไฟล์ partial_ แล้ว", "ok")
        end
        local h = getHum()
        local r = getHRP()
        if Auto.cancel and h and r then pcall(function() h:MoveTo(r.Position) end) end
        Auto.active, Auto.step, Auto.label = false, 0, ""
    end)
end

--==================================================================
-- AI ในเครื่อง (ระบบกฎ ไม่ส่งข้อมูลออกเน็ต)
--==================================================================
local function aiSummary()
    local L = {}
    L[#L + 1] = "=== สรุปโดย AI ในเครื่อง (ระบบกฎ ไม่ใช่โมเดลออนไลน์) ==="
    L[#L + 1] = "เวลา: " .. os.date("%Y-%m-%d %H:%M:%S") .. " | PlaceId " .. game.PlaceId .. " | ผู้เล่น " .. LP.Name
    L[#L + 1] = ""
    L[#L + 1] = "[ดัมป์อะไรแล้วบ้าง]"
    L[#L + 1] = sget(statusText, "(อ่านสถานะไม่ได้)")
    L[#L + 1] = ""
    L[#L + 1] = "[ข้อสังเกต]"
    local notes, todo = {}, {}
    local doneAny = false
    for _, id in ipairs(ORDER) do if St[id].status == "done" then doneAny = true end end
    if not doneAny then notes[#notes + 1] = "ยังไม่มีข้อมูล เริ่มด้วยคำสั่ง สแกนทั้งหมด" end
    if Workspace.StreamingEnabled then notes[#notes + 1] = "แมพเปิด StreamingEnabled จึงเห็นเฉพาะวัตถุใกล้ตัว ควรเดินไปหลายจุดแล้วสแกนซ้ำ" end
    for _, id in ipairs(ORDER) do
        local s = St[id]
        if s.truncated then notes[#notes + 1] = Scanners[id].thai .. ": ข้อมูลเกินเพดาน " .. CAP .. " รายการต่อชนิด จึงตัดส่วนที่เกินทิ้ง" end
        if s.status ~= "done" then todo[#todo + 1] = "สแกน" .. (Scanners[id].thai:gsub("^สแกน", "")) end
    end
    if St.map.status == "done" and tableCount(sget(Scanners.map.list, {})) > 0 then
        local roads, blds = 0, 0
        for _, r in ipairs(sget(Scanners.map.list, {})) do
            if r.kind == "ถนน" then roads = roads + 1 elseif r.kind == "อาคาร" then blds = blds + 1 end
        end
        if roads == 0 then notes[#notes + 1] = "ไม่พบถนนที่คาดว่าใช่ ถนนอาจเป็น MeshPart/Terrain หรือชื่อไม่ตรงคำที่ค้น" end
        notes[#notes + 1] = "แมพ: ถนน " .. roads .. " อาคาร " .. blds
    end
    if St.vehicle.status == "done" and sget(Scanners.vehicle.total, 0) == 0 then
        todo[#todo + 1] = "ยังไม่พบรถ เรียกรถของคุณออกมาแล้วสแกนรถซ้ำ"
    end
    if St.job.status == "done" then
        local n = sget(Scanners.job.flowFound, 0)
        notes[#notes + 1] = "งาน: พบหลักฐานขั้นตอน " .. n .. "/" .. #FLOW .. " ขั้น"
        local d = Scanners.job
        if n < #FLOW then todo[#todo + 1] = "เปิดแอปงานในเกมหรือเริ่มงานจริง 1 รอบ แล้วสแกนงานซ้ำเพื่อเก็บข้อความขั้นตอนที่ขาด" end
    end
    if St.ui.status == "done" then
        local c = sget(Scanners.ui.counts, {buttons = 0, prompts = 0, clicks = 0, touch = 0, spawns = 0, screens = 0, buy = 0})
        notes[#notes + 1] = string.format("ปุ่ม/จุดโต้ตอบ: ปุ่ม UI %d | จุดกด %d | จุดคลิก %d | แผ่นสัมผัส %d | จุดเกิด %d | หน้าต่าง UI %d", c.buttons, c.prompts, c.clicks, c.touch, c.spawns, c.screens)
        if c.buy > 0 then notes[#notes + 1] = "พบปุ่ม/จุดที่เกี่ยวกับซื้อหรือ Robux " .. c.buy .. " รายการ (ติดธง buy ไว้ในไฟล์ ไม่ได้กดเลย)" end
    end
    if St.remote.status == "done" then
        local d = sget(Scanners.remote.info, {frameworks = {}, obf = 0})
        local total = sget(Scanners.remote.total, 0)
        if total <= 3 then notes[#notes + 1] = "Remote มีน้อยมาก (" .. total .. ") เกมน่าจะใช้ช่องทางรวมศูนย์ ข้อมูลจริงอยู่ในแพ็กเก็ตที่ดูจากชื่อไม่ได้" end
        if #d.frameworks > 0 then
            local names = {}
            for _, f in ipairs(d.frameworks) do names[#names + 1] = f.name end
            notes[#notes + 1] = "เฟรมเวิร์กที่เจอ: " .. table.concat(names, ", ")
        end
        if d.obf > 0 then notes[#notes + 1] = "มี Remote ชื่อดูสุ่ม " .. d.obf .. " ตัว ซึ่งมักเป็นการปิดบังชื่อ" end
    end
    if #notes == 0 then notes[1] = "ไม่มีข้อสังเกตเพิ่มเติม" end
    for _, n in ipairs(notes) do L[#L + 1] = "- " .. n end
    L[#L + 1] = ""
    L[#L + 1] = "[ความครบถ้วนของข้อมูล]"
    local covOk, cov = pcall(coverageReport)
    if covOk then
        L[#L + 1] = cov.head
        for _, ln in ipairs(cov.lines) do L[#L + 1] = ln end
    end
    L[#L + 1] = ""
    L[#L + 1] = "[สิ่งที่ควรทำต่อ]"
    if #todo == 0 then todo[1] = "ครบทุกส่วนแล้ว กดบันทึกทั้งหมดเพื่อเก็บไฟล์" end
    for _, t in ipairs(todo) do L[#L + 1] = "- " .. t end
    L[#L + 1] = ""
    L[#L + 1] = "ไฟล์อยู่ในโฟลเดอร์ workspace ของตัวรัน: " .. FOLDER
    return table.concat(L, "\n")
end

function saveAll()
    local n = 0
    for _, id in ipairs(ORDER) do if saveOne(id, true) then n = n + 1 end end
    local w, info = writeFile("ai_summary_th.txt", aiSummary())
    if w then logf("บันทึกสรุป AI → " .. info, "ok") end
    local okCov, cov = pcall(coverageReport)
    if okCov then
        writeFile("coverage_report.txt", cov.text)
        local okJ, js = pcall(function() return HttpService:JSONEncode(cov.data) end)
        if okJ then writeFile("coverage.json", js) end
    end
    if n == 0 then logf("ยังไม่มีข้อมูลให้บันทึก สแกนก่อน", "warn") end
end

--==================================================================
-- ตรวจไฟล์ / รายงานความครบถ้วน / ไฟล์กู้คืน
--==================================================================
function verifyFiles()
    local okN, badN, lines = 0, 0, {}
    if type(readfile) ~= "function" then return 0, 0, {"ตัวรันนี้ไม่มี readfile ตรวจไฟล์ไม่ได้"} end
    local function chk(name, id)
        local content = readFile(name)
        if not content or #content < 2 then
            lines[#lines + 1] = "❌ " .. name .. " — ไม่พบไฟล์หรือไฟล์ว่าง" badN = badN + 1 return
        end
        local kb = math.max(1, math.floor(#content / 1024))
        if string.sub(name, -5) == ".json" then
            local okd, data = pcall(function() return HttpService:JSONDecode(content) end)
            if not okd then lines[#lines + 1] = "❌ " .. name .. " — JSON เสีย อ่านไม่ได้" badN = badN + 1 return end
            local meta = type(data) == "table" and type(data.meta) == "table" and data.meta or nil
            if id and (not meta or meta.scanner ~= id) then
                lines[#lines + 1] = "⚠️ " .. name .. " — JSON ถูกต้อง แต่ meta ไม่ตรงกับตัวสแกน" badN = badN + 1 return
            end
            lines[#lines + 1] = "✅ " .. name .. " — " .. kb .. " KB JSON ถูกต้อง" .. ((meta and meta.total) and (" · " .. meta.total .. " รายการ") or "") .. ((meta and meta.partial) and " (partial)" or "")
        else
            lines[#lines + 1] = "✅ " .. name .. " — " .. kb .. " KB"
        end
        okN = okN + 1
    end
    for _, id in ipairs(ORDER) do
        local sc, s = Scanners[id], St[id]
        if s.saved then chk(sc.file, id)
        elseif s.status == "done" or s.status == "stopped" then lines[#lines + 1] = "⚠️ " .. sc.file .. " — สแกนแล้วแต่ยังไม่ได้บันทึก (พิมพ์ บันทึก)" badN = badN + 1 end
    end
    if PreSteps.phoneTexts then chk("phone_ui.json") end
    for _, n in ipairs({"coverage.json", "coverage_report.txt", "ai_summary_th.txt"}) do
        if readFile(n) then chk(n) end
    end
    if #lines == 0 then lines[1] = "ยังไม่มีไฟล์ให้ตรวจ (สแกนและบันทึกก่อน)" end
    return okN, badN, lines
end

local function recoveryInfo()
    local found, names = {}, {"phone_ui.json"}
    for _, id in ipairs(ORDER) do names[#names + 1] = Scanners[id].file end
    for _, n in ipairs(names) do
        for _, pre in ipairs({"partial_", "backup1_", "backup2_"}) do
            local c = readFile(pre .. n)
            if c then found[#found + 1] = pre .. n .. " (" .. math.max(1, math.floor(#c / 1024)) .. " KB)" end
        end
    end
    local text
    if #found == 0 then text = "ยังไม่มีไฟล์สำรอง/กู้คืน (จะเกิดเมื่อสแกนค้าง/ถูกหยุด หรือเมื่อบันทึกทับไฟล์เดิม)"
    else
        text = "ไฟล์สำรอง/กู้คืนที่พบใน " .. FOLDER .. ":\n• " .. table.concat(found, "\n• ") ..
            "\npartial_ = ข้อมูลช่วงสแกนค้าง/หยุดกลางคัน/เซฟระหว่างทาง | backup1_/backup2_ = ไฟล์รุ่นก่อนหน้าที่ถูกเขียนทับ (เปิดอ่านเป็น JSON ได้เลย)"
    end
    return {count = #found, text = text}
end

function coverageReport()
    local items, counts, glob = {}, {ok = 0, warn = 0, bad = 0}, {}
    local stream = Workspace.StreamingEnabled
    local function iv(sc, key)
        local okI, its = pcall(sc.items)
        if okI then for _, it in ipairs(its) do if string.find(it[1], key, 1, true) then return it[2] end end end
        return 0
    end
    local maxScans = 0
    for _, id in ipairs(ORDER) do
        local sc, s = Scanners[id], St[id]
        maxScans = math.max(maxScans, s.scans)
        local issues, tips, level = {}, {}, "ok"
        local function issue(msg, tip, lv)
            issues[#issues + 1] = msg
            if tip then tips[#tips + 1] = tip end
            level = (lv == "bad" or level == "bad") and "bad" or "warn"
        end
        if s.scans == 0 and s.status ~= "stopped" then
            issue("ยังไม่ได้สแกน", "สแกนในแท็บ " .. sc.thai .. " หรือพิมพ์ สแกนทั้งหมด", "bad")
        else
            if s.status == "stopped" then issue("หยุดกลางคัน ข้อมูลอาจไม่ครบ", "สแกนซ้ำให้จบ (ข้อมูลเดิมจะรวมให้ ไม่หาย)") end
            if s.status == "error" then issue("สแกนผิดพลาด", "ดูแท็บบันทึก แล้วสแกนซ้ำ") end
            if s.truncated then issue("ข้อมูลเกินเพดาน " .. CAP .. " รายการ ถูกตัดส่วนที่เกิน", "สแกนแยกเป็นช่วง/ย้ายพื้นที่แล้วสแกนซ้ำ") end
            if id == "map" then
                if iv(sc, "ชิ้นส่วน") == 0 then issue("ไม่พบชิ้นส่วนแมพที่โหลดอยู่เลย", "รอแมพโหลดแล้วสแกนซ้ำ", "bad") end
                if iv(sc, "ถนน") == 0 then issue("ไม่พบถนนที่คาดว่าใช่ (อาจเป็น Mesh/Terrain หรือชื่อไม่ตรงคำที่ค้น)") end
                if iv(sc, "อาคาร") == 0 then issue("ไม่พบอาคารที่คาดว่าใช่") end
                if iv(sc, "จุดสำคัญ") == 0 then issue("ไม่พบจุดสำคัญ (Landmarks)") end
            elseif id == "vehicle" then
                if sc.total() == 0 then issue("ยังไม่พบรถที่โหลดอยู่", "เรียกรถออกมาแล้วสแกนรถซ้ำ") end
                if Verify.car and Verify.car.level ~= "ok" then issue("เรียกรถอัตโนมัติ: " .. tostring(Verify.car.reason), "เช็กปุ่มเรียกรถของเกมนี้ (ไม่ใช่ G?) หรือเรียกรถด้วยมือก่อนสแกน") end
            elseif id == "npc" then
                if sc.total() == 0 then issue("ไม่พบ NPC/จุดทำงาน", "เดินไปใกล้ NPC แล้วสแกนซ้ำ (แมพที่โหลดทีละส่วนจะไม่เห็น NPC ไกลตัว)") end
            elseif id == "job" then
                local missing = Scanners.job.flowMissing()
                if #missing > 0 then issue("ขั้นตอนงานที่ยังไม่พบหลักฐาน: " .. table.concat(missing, " / "), "ขั้นที่ขาดมักต้องเริ่มงานจริงด้วยมือ (โหมด Auto ไม่รับงาน/ส่งงาน/รับเงินให้) แล้วสแกนงานซ้ำ") end
                if iv(sc, "ข้อความงานใน UI") == 0 then issue("ไม่พบข้อความเกี่ยวกับงานใน UI", "เปิดแอปงานค้างไว้แล้วสแกนงานซ้ำ") end
                if Verify.app and Verify.app.level ~= "ok" then issue("เปิดแอปงานอัตโนมัติ: " .. tostring(Verify.app.reason), "ปรับ PRE.phoneKeys / PRE.appKeys ให้ตรงชื่อ UI จริงของเกม") end
            elseif id == "ui" then
                local c = sget(Scanners.ui.counts, {buttons = 0, prompts = 0, clicks = 0, touch = 0, spawns = 0, screens = 0, buy = 0})
                if c.buttons == 0 then issue("ไม่พบปุ่ม UI เลย", nil, "bad")
                elseif iv(sc, "มองเห็นอยู่") == 0 then issue("ไม่มีปุ่มที่มองเห็นอยู่ (หน้าต่างอาจยังไม่เปิด)", "เปิดเมนู/หน้าต่างที่ต้องการแล้วสแกนปุ่มซ้ำ") end
                if c.prompts + c.clicks + c.touch == 0 then issue("ไม่พบจุดโต้ตอบในโลก (ProximityPrompt/ClickDetector/แผ่นสัมผัส)", "เดินไปใกล้จุดต่าง ๆ แล้วสแกนซ้ำ (Streaming อาจยังไม่โหลดจุดไกลตัว)") end
            elseif id == "remote" then
                if sc.total() <= 3 then issue("Remote น้อยมาก (" .. sc.total() .. ")", "เกมอาจใช้ช่องทางรวมศูนย์/เฟรมเวิร์ก ดูแท็บ Remote") end
            end
        end
        items[#items + 1] = {id = id, thai = sc.thai, icon = sc.icon, level = level, issues = issues, tips = tips, scans = s.scans, total = (s.scans > 0 or s.status == "stopped") and sc.total() or 0}
        counts[level] = counts[level] + 1
    end
    if stream and maxScans < 2 then glob[#glob + 1] = "แมพเปิด StreamingEnabled แต่สแกนมาไม่ถึง 2 รอบ ข้อมูลน่าจะเห็นแค่ใกล้ตัว → ใช้ ⚡ เดินสำรวจหรือเดินไปหลายจุดแล้วสแกนซ้ำ" end
    if Verify.route then
        local r = Verify.route
        glob[#glob + 1] = string.format("เดินสำรวจ: ถึง %d/%d จุด", r.arrived, r.planned)
        if #r.failed > 0 then
            local pts = {}
            for i, f in ipairs(r.failed) do if i <= 5 then pts[#pts + 1] = string.format("(%d,%d)", f[1], f[2]) end end
            glob[#glob + 1] = "ไปไม่ถึง " .. #r.failed .. " จุด (ติดสิ่งกีดขวาง/จุดเข้าไม่ถึง): " .. table.concat(pts, " ") .. (#r.failed > 5 and " ..." or "")
        end
    end
    local mark = {ok = "✅", warn = "⚠️", bad = "❌"}
    local lines = {}
    for _, it in ipairs(items) do
        lines[#lines + 1] = string.format("%s %s %s — %s", mark[it.level], it.icon, it.thai, it.level == "ok" and "ข้อมูลครบตามที่ตรวจได้" or ("ไม่ครบ " .. #it.issues .. " จุด"))
        for _, m in ipairs(it.issues) do lines[#lines + 1] = "    • " .. m end
        for _, t in ipairs(it.tips) do lines[#lines + 1] = "    → " .. t end
    end
    for _, g in ipairs(glob) do lines[#lines + 1] = "ℹ️ " .. g end
    local head = string.format("ครบ %d | ไม่ครบ %d | ไม่มีข้อมูล %d (จาก %d หมวด)", counts.ok, counts.warn, counts.bad, #items)
    return {items = items, counts = counts, lines = lines, glob = glob, head = head,
        text = "=== รายงานความครบถ้วนของข้อมูล ===\n" .. head .. "\n" .. table.concat(lines, "\n"),
        data = {time = os.date("%Y-%m-%d %H:%M:%S"), placeId = game.PlaceId, streamingEnabled = stream, summary = counts, categories = items, notes = glob,
            carVerify = Verify.car, appVerify = Verify.app, route = Verify.route}}
end

