local gui, root, bgImg, overlay, scaleObj, body, pageTitle, pageDesc, subtitle, fab
local applyScale = function() end
local Themed, Live, PageConns, Conns = {}, {}, {}, {}
local currentTab = "dash"
-- hubVisible [ไม่ได้ใช้งาน] เก็บไว้ตามข้อกำหนดห้ามลบโค้ด
local showTab, saveSettings, hubVisible, applyFonts

local function connect(sig, fn) local c = sig:Connect(fn) Conns[#Conns + 1] = c return c end
local function pconnect(sig, fn) local c = sig:Connect(fn) PageConns[#PageConns + 1] = c return c end

local function mk(class, props, parent)
    local o = Instance.new(class)
    for k, v in pairs(props or {}) do
        if type(v) == "string" and string.sub(v, 1, 1) == "@" and T[string.sub(v, 2)] then
            Themed[#Themed + 1] = {o, k, string.sub(v, 2)}
            o[k] = T[string.sub(v, 2)]
        else
            o[k] = v
        end
    end
    o.Parent = parent
    return o
end
local function applyTheme()
    local alive = {}
    for _, e in ipairs(Themed) do
        if e[1].Parent ~= nil then
            pcall(function() e[1][e[2]] = T[e[3]] end)
            alive[#alive + 1] = e
        end
    end
    Themed = alive
end
local function corner(o, r) return mk("UICorner", {CornerRadius = UDim.new(0, r or 10)}, o) end
local function stroke(o, tr) return mk("UIStroke", {Color = "@line", Thickness = 1, Transparency = tr or 0.5}, o) end

local function guiParent()
    local ok, h = pcall(function() return gethui and gethui() end)
    if ok and h then return h end
    local ok2, cg = pcall(function() return game:GetService("CoreGui") end)
    if ok2 and cg then
        local t = pcall(function() local _ = cg.Name end)
        if t then return cg end
    end
    return PlayerGui
end

local function clearBody()
    for _, c in ipairs(PageConns) do pcall(function() c:Disconnect() end) end
    PageConns, Live = {}, {}
    for _, ch in ipairs(body:GetChildren()) do
        if not ch:IsA("UIListLayout") then ch:Destroy() end
    end
end

-- ----- ชิ้นส่วน UI -----
local function card(title, desc)
    local f = mk("Frame", {Size = UDim2.new(1, -6, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundColor3 = "@panel", BackgroundTransparency = 0.18, BorderSizePixel = 0}, body)
    corner(f, 12) stroke(f, 0.45)
    mk("UIPadding", {PaddingTop = UDim.new(0, 12), PaddingBottom = UDim.new(0, 12), PaddingLeft = UDim.new(0, 14), PaddingRight = UDim.new(0, 14)}, f)
    mk("UIListLayout", {Padding = UDim.new(0, 7), SortOrder = Enum.SortOrder.LayoutOrder}, f)
    if title then
        mk("TextLabel", {Size = UDim2.new(1, 0, 0, 22), BackgroundTransparency = 1, Text = title, TextColor3 = "@text", Font = Enum.Font.GothamBold, TextSize = 16, TextXAlignment = Enum.TextXAlignment.Left}, f)
    end
    if desc and desc ~= "" then
        mk("TextLabel", {Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1, Text = desc, TextColor3 = "@muted", Font = Enum.Font.Gotham, TextSize = 13, TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Left, TextYAlignment = Enum.TextYAlignment.Top}, f)
    end
    return f
end
local function liveLabel(parent, fn, color)
    local l = mk("TextLabel", {Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1, Text = "", TextColor3 = color or "@text", Font = Enum.Font.Gotham, TextSize = 14, TextWrapped = true, RichText = false, TextXAlignment = Enum.TextXAlignment.Left, TextYAlignment = Enum.TextYAlignment.Top}, parent)
    local function upd() local ok, t = pcall(fn) if ok then l.Text = t end end
    Live[#Live + 1] = upd
    upd()
    return l
end
local function row(parent)
    local r = mk("Frame", {Size = UDim2.new(1, 0, 0, 38), BackgroundTransparency = 1}, parent)
    mk("UIListLayout", {FillDirection = Enum.FillDirection.Horizontal, Padding = UDim.new(0, 8), SortOrder = Enum.SortOrder.LayoutOrder, Wraps = true}, r)
    return r
end
local function btn(parent, text, cb, w, primary)
    local b = mk("TextButton", {Size = UDim2.fromOffset(w or 130, 36), BackgroundColor3 = primary and "@accent" or "@panel2", Text = text, TextColor3 = primary and "@bg" or "@text", Font = Enum.Font.GothamBold, TextSize = 13, AutoButtonColor = true, BorderSizePixel = 0}, parent)
    corner(b, 9)
    if not primary then stroke(b, 0.35) end
    pconnect(b.Activated, function()
        local okC, errC = xpcall(cb, debug.traceback)
        if not okC then
            pcall(ErrLog.add, "ปุ่ม " .. tostring(text), errC)
            logf('ปุ่ม "' .. tostring(text) .. '" ทำงานไม่สำเร็จ: ' .. cut(errC, 160), "err")
        end
    end)
    return b
end
local function bar(parent, getPct)
    local track = mk("Frame", {Size = UDim2.new(1, 0, 0, 12), BackgroundColor3 = "@panel2", BorderSizePixel = 0}, parent)
    corner(track, 6)
    local fill = mk("Frame", {Size = UDim2.fromScale(0, 1), BackgroundColor3 = "@accent", BorderSizePixel = 0}, track)
    corner(fill, 6)
    Live[#Live + 1] = function()
        local p = math.clamp(getPct(), 0, 1)
        fill.Size = UDim2.fromScale(p, 1)
    end
    return track
end
local function switch(parent, title, desc, init, cb)
    local f = mk("Frame", {Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1}, parent)
    local lbl = mk("TextLabel", {Size = UDim2.new(1, -90, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1, Text = title .. (desc and ("\n" .. desc) or ""), TextColor3 = "@text", Font = Enum.Font.GothamMedium, TextSize = 13, TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Left}, f)
    local on = init
    local sw = mk("TextButton", {AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, 0, 0, 0), Size = UDim2.fromOffset(76, 32), Text = "", AutoButtonColor = false, BorderSizePixel = 0, BackgroundColor3 = "@panel2"}, f)
    corner(sw, 16)
    local t = mk("TextLabel", {Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, Font = Enum.Font.GothamBold, TextSize = 13, Text = ""}, sw)
    local function render()
        sw.BackgroundColor3 = on and T.accent or Color3.fromRGB(70, 78, 90)
        t.Text = on and "เปิด" or "ปิด"
        t.TextColor3 = on and T.bg or T.text
    end
    render()
    pconnect(sw.Activated, function() on = not on render() cb(on) end)
    return f
end
local function slider(parent, title, min, max, val, fmt, cb)
    local wrap = mk("Frame", {Size = UDim2.new(1, 0, 0, 48), BackgroundTransparency = 1}, parent)
    local lbl = mk("TextLabel", {Size = UDim2.new(1, 0, 0, 18), BackgroundTransparency = 1, Text = "", TextColor3 = "@text", Font = Enum.Font.GothamMedium, TextSize = 13, TextXAlignment = Enum.TextXAlignment.Left}, wrap)
    local track = mk("Frame", {Position = UDim2.fromOffset(0, 30), Size = UDim2.new(1, 0, 0, 8), BackgroundColor3 = "@panel2", BorderSizePixel = 0}, wrap)
    corner(track, 4)
    local fill = mk("Frame", {Size = UDim2.fromScale(0, 1), BackgroundColor3 = "@accent", BorderSizePixel = 0}, track)
    corner(fill, 4)
    local knob = mk("Frame", {AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromOffset(18, 18), BackgroundColor3 = "@text", BorderSizePixel = 0}, track)
    corner(knob, 9)
    local function setVal(v, fire)
        v = math.clamp(v, min, max)
        local p = (v - min) / (max - min)
        fill.Size = UDim2.fromScale(p, 1)
        knob.Position = UDim2.fromScale(p, 0.5)
        lbl.Text = title .. ": " .. string.format(fmt, v)
        if fire then cb(v) end
    end
    setVal(val, false)
    local hit = mk("TextButton", {Position = UDim2.fromOffset(0, 22), Size = UDim2.new(1, 0, 0, 26), BackgroundTransparency = 1, Text = ""}, wrap)
    local dragging = false
    local function fromX(x)
        local w = track.AbsoluteSize.X
        if w <= 0 then return end
        local p = math.clamp((x - track.AbsolutePosition.X) / w, 0, 1)
        setVal(min + (max - min) * p, true)
    end
    pconnect(hit.InputBegan, function(i)
        if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then dragging = true fromX(i.Position.X) end
    end)
    pconnect(UIS.InputChanged, function(i)
        if dragging and (i.UserInputType == Enum.UserInputType.MouseMovement or i.UserInputType == Enum.UserInputType.Touch) then fromX(i.Position.X) end
    end)
    pconnect(UIS.InputEnded, function(i)
        if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
            if dragging then dragging = false saveSettings() end
        end
    end)
    return wrap
end

