local function overallPct() return Run.total > 0 and (Run.done / Run.total) or (Run.active and 0 or 0) end
local function runLine()
    if Auto.active then
        return string.format("⚡ โหมดอัตโนมัติ: %s — ขั้นที่ %d/%d | %s", Auto.label, Auto.step, Auto.total, Run.active and ("กำลังสแกน " .. math.floor(overallPct() * 100) .. "%") or "รอ/เดิน")
    end
    if Run.active then
        return string.format("⏳ กำลังสแกน: %s — %d%% (%d/%d) ใช้เวลา %d วิ", Run.label, math.floor(overallPct() * 100), Run.done, Run.total, math.floor(os.clock() - Run.t0))
