end

--==================================================================
-- SMART DUMP (งาน 8): บันทึกลง BALL_KUN_AI_Dump/<PlaceId>/ แยกตามแมพ
-- รักษาข้อมูลเก่า: รวมรายการตามคีย์ (ไม่ลบรายการเก่าที่หายไปจากการสแกนรอบนี้) | ไฟล์เดิมสำรอง 2 รุ่นผ่าน writeFile
-- ตรวจ JSON ก่อนเขียน และอ่านกลับหลังเขียน | บันทึกบางส่วนได้ (มี partial) | สแกนซ้ำแล้วรวมได้ (Resume)
-- ไฟล์ที่ยังไม่มีตัวสแกน/ตัววิเคราะห์รองรับ จะไม่เขียนทับไฟล์เดิม
--==================================================================
local AI_FOLDER = "BALL_KUN_AI_Dump"
local SD_NOT_BUILT = "ยังไม่มีตัวสแกน/ตัววิเคราะห์นี้ในรุ่นปัจจุบัน"
local SD_FILES = {"game_info.json", "shops.json", "important_points.json", "jobs.json", "vehicles.json",
    "interactions.json", "game_systems.json", "farm_analysis.json", "farm_routes.json", "farm_plan.json",
    "ai_recommendations.json", "missing_data.json", "errors.json", "report_th.txt"}

local function sdSafe(fn, fb)
    local ok, v = pcall(fn)
    if ok and v ~= nil then return v end
    return fb
end

local function sdRead(path)
    local c = rawRead(path)
    if not c then return nil end
    local ok, d = pcall(function() return HttpService:JSONDecode(c) end)
    if ok and type(d) == "table" then return d end
    return nil
end

-- รวมรายการตามคีย์: รายการใหม่ทับรายการเดิมที่คีย์ตรงกัน รายการเดิมที่ไม่อยู่ในรอบนี้ยังคงอยู่
local function sdMerge(oldList, newList, keyField)
    local out, idx = {}, {}
    local stats = {old = 0, new = 0, added = 0, updated = 0}
    for _, r in ipairs(type(oldList) == "table" and oldList or {}) do
        stats.old = stats.old + 1
        local k = type(r) == "table" and r[keyField] or nil
        if k ~= nil and idx[k] == nil then out[#out + 1] = r; idx[k] = #out end
    end
    for _, r in ipairs(newList or {}) do
        local k = type(r) == "table" and r[keyField] or nil
        if k ~= nil then
            stats.new = stats.new + 1
            if idx[k] then out[idx[k]] = r; stats.updated = stats.updated + 1
            else out[#out + 1] = r; idx[k] = #out; stats.added = stats.added + 1 end
        end
    end
    return out, stats
end

local function smartDump()
    local res = {ok = false, written = 0, total = #SD_FILES, text = ""}
    if type(writefile) ~= "function" then
        res.text = "SMART DUMP ทำไม่ได้: ตัวรันนี้ไม่มี writefile (ข้อจำกัดของตัวรัน)"
        logf(res.text, "err")
        return res
    end
    local pid = tostring(game.PlaceId)
    local dir = AI_FOLDER .. "/" .. pid
    local now = os.date("%Y-%m-%d %H:%M:%S")
    local partial = (Run.active or Auto.active) and true or false
    for _, id in ipairs(ORDER) do if St[id].status ~= "done" then partial = true end end
    local written, failed, skipped, merges = {}, {}, {}, {}

    local function meta(file)
        return {tool = "BALL KUN AI FARM SCANNER", version = VERSION, file = file, placeId = game.PlaceId,
            gameId = game.GameId, time = now, partial = partial or nil}
    end

    -- บันทึกไฟล์หนึ่งไฟล์: ready=false และมีไฟล์เดิม → คงไฟล์เดิมไว้ไม่เขียนทับ
    local function save(name, obj, listField, keyField, ready)
        local path = dir .. "/" .. name
        if not ready and rawRead(path) then
            skipped[#skipped + 1] = name .. " (ยังไม่มีข้อมูลรอบนี้ คงไฟล์เดิมไว้)"
            return false
        end
        if listField and keyField and type(obj[listField]) == "table" then
            local old = sdRead(path)
            local m, st = sdMerge(old and old[listField] or nil, obj[listField], keyField)
            obj[listField] = m
            merges[#merges + 1] = name .. " [" .. listField .. "]: เดิม " .. st.old .. " | สแกนรอบนี้ " .. st.new
                .. " | เพิ่ม " .. st.added .. " | อัปเดต " .. st.updated
        end
        local okE, js = pcall(function() return HttpService:JSONEncode(sanitize(obj)) end)
        if not okE then failed[#failed + 1] = name .. " (แปลงเป็น JSON ไม่ได้)" return false end
        if not jsonOk(".json", js) then failed[#failed + 1] = name .. " (JSON ที่สร้างอ่านกลับไม่ได้)" return false end
        local w, info = writeFile(name, js, false, dir)
        if w then written[#written + 1] = name return true end
        failed[#failed + 1] = name .. " (" .. tostring(info) .. ")"
        return false
    end

    -- 1) ข้อมูลเกม
    local ui = sdSafe(function() return Scanners.ui.info() end, {})
    save("game_info.json", {meta = meta("game_info.json"), player = LP.Name,
        status = St.ui.status == "done" and "พบจริง" or "ยังไม่ได้สแกนปุ่ม/จุดโต้ตอบ",
        game = ui.game, world = ui.world}, nil, nil, St.ui.status == "done")

    -- 2) ร้านค้า: ยังไม่มีตัวสแกน
    save("shops.json", {meta = meta("shops.json"), status = SD_NOT_BUILT, shops = {}}, nil, nil, false)

    -- 3) จุดสำคัญ: รวมจากแผนที่ งาน ปุ่ม และ NPC ทุกรายการมีแหล่งที่มาและสถานะ
    local pts = {}
    local function addPt(r, src)
        if type(r) == "table" and r.p then
            pts[#pts + 1] = {key = tostring(r.path or r.n), name = tostring(r.n or "?"), kind = r.kind or "?",
                pos = r.p, source = src, status = "พบจริง"}
        end
    end
    if St.map.status == "done" then for _, r in ipairs(sdSafe(Scanners.map.list, {})) do addPt(r, "map") end end
    if St.job.status == "done" then for _, r in ipairs(sdSafe(Scanners.job.list, {})) do addPt(r, "job") end end
    if St.ui.status == "done" then
        for _, r in ipairs(sdSafe(Scanners.ui.list, {})) do if r.hot then addPt(r, "ui") end end
    end
    if St.npc.status == "done" then for _, r in ipairs(sdSafe(Scanners.npc.list, {})) do addPt(r, "npc") end end
    local readyPts = St.map.status == "done" or St.job.status == "done" or St.ui.status == "done" or St.npc.status == "done"
    save("important_points.json", {meta = meta("important_points.json"), points = pts}, "points", "key", readyPts)

    -- 4) งาน: รวมเฉพาะรายการจุดกด (รายการอื่นเขียนใหม่ รุ่นก่อนอยู่ใน backup1/backup2)
    local job = sdSafe(Scanners.job.export, nil)
    if job then job.meta = meta("jobs.json") end
    save("jobs.json", job or {meta = meta("jobs.json"), status = "ยังไม่ได้สแกนงาน"}, "prompts", "path", St.job.status == "done")

    -- 5) รถ: รวมตามเส้นทางของรถ
    local veh = sdSafe(Scanners.vehicle.export, nil)
    if veh then veh.meta = meta("vehicles.json") end
    save("vehicles.json", veh or {meta = meta("vehicles.json"), status = "ยังไม่ได้สแกนรถ"}, "vehicles", "path", St.vehicle.status == "done")

    -- 6) ปุ่มและจุดโต้ตอบ: รวมตามเส้นทางของปุ่ม
    local inter = sdSafe(Scanners.ui.export, nil)
    if inter then inter.meta = meta("interactions.json") end
    save("interactions.json", inter or {meta = meta("interactions.json"), status = "ยังไม่ได้สแกนปุ่ม/จุดโต้ตอบ"}, "buttons", "path", St.ui.status == "done")

    -- 7) ระบบเกม: Remote และ NPC (เขียนทับ รุ่นก่อนอยู่ใน backup)
    local sys = {meta = meta("game_systems.json"),
        remote = sdSafe(Scanners.remote.export, nil), npc = sdSafe(Scanners.npc.export, nil)}
    save("game_systems.json", sys, nil, nil, St.remote.status == "done" or St.npc.status == "done")

    -- 8-11) ฟาร์มและ AI: ยังไม่มีตัววิเคราะห์ ไม่เขียนทับไฟล์เดิม
    save("farm_analysis.json", {meta = meta("farm_analysis.json"), status = SD_NOT_BUILT}, nil, nil, false)
    save("farm_routes.json", {meta = meta("farm_routes.json"), status = SD_NOT_BUILT}, nil, nil, false)
    save("farm_plan.json", {meta = meta("farm_plan.json"), status = SD_NOT_BUILT}, nil, nil, false)
    save("ai_recommendations.json", {meta = meta("ai_recommendations.json"), status = SD_NOT_BUILT}, nil, nil, false)

    -- 12) ข้อมูลที่ยังขาด
    local miss = {}
    local function addMiss(key, item, reason) miss[#miss + 1] = {key = key, item = item, reason = reason} end
    for _, id in ipairs(ORDER) do
        if St[id].status ~= "done" then
            addMiss("scan:" .. id, Scanners[id].thai, "ยังไม่ได้สแกนหรือสแกนไม่สำเร็จ (สถานะ: " .. tostring(St[id].status) .. ")")
        end
    end
    if St.job.status == "done" then
        for _, n in ipairs(sdSafe(Scanners.job.flowMissing, {})) do addMiss("flow:" .. n, "ขั้นตอนงาน: " .. n, "ไม่พบหลักฐานในข้อมูลที่สแกน") end
    end
    if St.vehicle.status == "done" and sdSafe(Scanners.vehicle.total, 0) == 0 then
        addMiss("vehicle:none", "รถ", "ไม่พบรถ (ควรเรียกรถออกมาก่อนสแกน)")
    end
    if Verify.car and Verify.car.ok ~= true then addMiss("car", "การเรียกรถ", tostring(Verify.car.reason)) end
    if Verify.app and Verify.app.level ~= "ok" then addMiss("app", "แอปงาน", tostring(Verify.app.reason)) end
    addMiss("shops", "ร้านค้า", "ยังไม่มีตัวสแกนร้านค้า")
    addMiss("ai", "วิเคราะห์ AI และแผนฟาร์ม", "ยังไม่มีตัววิเคราะห์ (ยังไม่ได้สร้าง)")
    save("missing_data.json", {meta = meta("missing_data.json"), items = miss}, nil, nil, true)

    -- 13) ข้อผิดพลาด
    save("errors.json", {meta = meta("errors.json"), total = ErrLog.total, overflow = ErrLog.overflow, errors = ErrLog.list}, nil, nil, true)

    -- ตรวจว่าไฟล์ที่เขียนสำเร็จอ่านกลับได้จริง
    local verified = 0
    for _, name in ipairs(written) do
        local c = rawRead(dir .. "/" .. name)
        if c and #c > 0 and (string.sub(name, -5) ~= ".json" or jsonOk(name, c)) then verified = verified + 1 end
    end

    -- 14) รายงานภาษาไทย
    local L = {}
    L[#L + 1] = "=== SMART DUMP รายงาน (" .. now .. ") ==="
    L[#L + 1] = "PlaceId " .. pid .. " | โฟลเดอร์ " .. AI_FOLDER .. "/" .. pid
    L[#L + 1] = "เขียนสำเร็จ " .. #written .. " / " .. #SD_FILES .. " ไฟล์ | อ่านกลับผ่าน " .. verified .. " | ผิดพลาด " .. #failed .. " | คงไฟล์เดิม " .. #skipped
    if partial then L[#L + 1] = "สถานะ: บันทึกบางส่วน (ยังสแกนไม่ครบหรือกำลังสแกนอยู่)" end
    if #merges > 0 then L[#L + 1] = "" L[#L + 1] = "[รวมข้อมูลกับรอบก่อน]" for _, m in ipairs(merges) do L[#L + 1] = "- " .. m end end
    if #failed > 0 then L[#L + 1] = "" L[#L + 1] = "[ผิดพลาด]" for _, m in ipairs(failed) do L[#L + 1] = "- " .. m end end
    if #skipped > 0 then L[#L + 1] = "" L[#L + 1] = "[คงไฟล์เดิมไว้]" for _, m in ipairs(skipped) do L[#L + 1] = "- " .. m end end
    L[#L + 1] = ""
    L[#L + 1] = "[ข้อจำกัดของตัวรัน]"
    if type(readfile) ~= "function" then L[#L + 1] = "- ไม่มี readfile: รวมกับข้อมูลเดิมไม่ได้ ไฟล์จะถูกเขียนทับ" end
    if type(isfile) ~= "function" then L[#L + 1] = "- ไม่มี isfile: ตรวจว่ามีไฟล์เดิมหรือไม่ไม่ได้" end
    if type(readfile) == "function" and type(isfile) == "function" then L[#L + 1] = "- ไม่มีข้อจำกัดที่ตรวจพบ" end
    L[#L + 1] = "- ร้านค้า ฟาร์ม และ AI ยังไม่มีตัวสแกน/ตัววิเคราะห์ในรุ่นนี้ ไฟล์เหล่านั้นไม่มีข้อมูลจริง"
    local reportText = table.concat(L, "\n")
    local okR, wR = writeFile("report_th.txt", reportText, false, dir)
    if okR then written[#written + 1] = "report_th.txt" else failed[#failed + 1] = "report_th.txt (" .. tostring(wR) .. ")" end

    res.written = #written
    res.ok = #failed == 0
    res.text = reportText .. (okR and "" or "\n(เขียน report_th.txt ไม่สำเร็จ)")
    logf(string.format("SMART DUMP: เขียนสำเร็จ %d/%d ไฟล์ ที่ %s", #written, #SD_FILES, dir), res.ok and "ok" or "warn")
    return res
end

--==================================================================
-- GAME PROFILE (Universal ส่วนที่ 1): สร้างโปรไฟล์เกมจากข้อมูลที่สแกนจริงเท่านั้น
-- ไม่กำหนดชื่อ Object มาตรฐาน ไม่เดาระบบที่ไม่พบ ทุกความสามารถมีระดับความมั่นใจ
-- เก็บแยกตาม PlaceId: BALL_KUN_AI_Dump/<PlaceId>/profile.json (โหลดข้ามแมพไม่ได้)
--==================================================================
local PROF_STATE = {
    found = "พบจริง",
    keyword = "ยังไม่ยืนยัน (พบจากคำในข้อความ ไม่พบวัตถุจริง)",
    none = "ไม่พบ (สแกนแล้ว อาจไม่มีระบบนี้ หรือยังไม่ได้เข้าใช้ระบบ)",
    notScanned = "ยังไม่สแกน",
    notBuilt = "ยังไม่มีตัวตรวจ",
}
local PROF_LABEL = {job = "งาน", shop = "ร้านค้า", vehicle = "ยานพาหนะ", npc = "NPC",
    points = "จุดโต้ตอบ", remote = "Remote", map = "จุดสำคัญแมพ"}

local function countKinds(list, prefix)
    local n = 0
    for _, r in ipairs(list or {}) do
        if type(r.kind) == "string" and string.sub(r.kind, 1, #prefix) == prefix then n = n + 1 end
    end
    return n
end

local function buildProfile()
    local ui = sdSafe(function() return Scanners.ui.info() end, {})
    local caps, unknown = {}, {}
    local function cap(key, state, count, note)
        caps[key] = {label = PROF_LABEL[key] or key, state = state, count = count or 0, note = note or ""}
    end
    local function scanned(id) return St[id].status == "done" end

    -- งาน: จุดกดหรือจุดทำงานที่มี Job/StationId คือหลักฐานจริง ส่วนคำในข้อความเป็นหลักฐานรอง
    if not scanned("job") then cap("job", PROF_STATE.notScanned)
    else
        local jl = sdSafe(Scanners.job.list, {})
        local real = countKinds(jl, "จุดกด") + countKinds(jl, "จุดทำงาน")
        local flow = sdSafe(Scanners.job.flowFound, 0)
        if real > 0 then cap("job", PROF_STATE.found, real, "จุดกดและจุดทำงานที่พบจริง " .. real .. " รายการ")
        elseif flow > 0 then cap("job", PROF_STATE.keyword, flow, "พบคำเกี่ยวกับงานในข้อความ " .. flow .. " ขั้น แต่ไม่พบจุดงานจริง")
        else cap("job", PROF_STATE.none) end
    end

    -- ร้านค้า: ยังไม่มีตัวสแกนร้าน แสดงเฉพาะจำนวนปุ่มที่ติดธงซื้อ/Robux (ไม่ใช่ข้อมูลร้าน)
    local buyFlags = scanned("ui") and sdSafe(Scanners.ui.counts, {buy = 0}).buy or 0
    cap("shop", PROF_STATE.notBuilt, 0, "ยังไม่มีตัวสแกนร้านค้า | ปุ่มที่ติดธงซื้อ/Robux " .. buyFlags .. " รายการ (ไม่กดเด็ดขาด)")

    -- ยานพาหนะ / NPC / จุดโต้ตอบ / Remote / จุดสำคัญแมพ
    if not scanned("vehicle") then cap("vehicle", PROF_STATE.notScanned)
    else
        local n = sdSafe(Scanners.vehicle.total, 0)
        cap("vehicle", n > 0 and PROF_STATE.found or PROF_STATE.none, n, n > 0 and "" or "ลองเรียกรถออกมาก่อนสแกน")
    end
    if not scanned("npc") then cap("npc", PROF_STATE.notScanned)
    else
        local n = sdSafe(Scanners.npc.total, 0)
        cap("npc", n > 0 and PROF_STATE.found or PROF_STATE.none, n)
    end
    if not scanned("ui") then cap("points", PROF_STATE.notScanned)
    else
        local hot = 0
        for _, r in ipairs(sdSafe(Scanners.ui.list, {})) do if r.hot then hot = hot + 1 end end
        cap("points", hot > 0 and PROF_STATE.found or PROF_STATE.none, hot)
    end
    if not scanned("remote") then cap("remote", PROF_STATE.notScanned)
    else
        local n = sdSafe(Scanners.remote.total, 0)
        cap("remote", n > 0 and PROF_STATE.found or PROF_STATE.none, n, "ดูโครงสร้างอย่างเดียว ไม่ได้ยิงคำสั่งใด")
        local info = sdSafe(Scanners.remote.info, {obf = 0})
        if (info.obf or 0) > 0 then
            unknown[#unknown + 1] = {kind = "remote", count = info.obf,
                note = "Remote ชื่อดูสุ่มหรือถูกปิดบัง ระบบที่ใช้จริงยังไม่รู้จัก ต้องทดสอบ"}
        end
        if #(info.frameworks or {}) > 0 then
            local names = {}
            for _, f in ipairs(info.frameworks) do names[#names + 1] = tostring(f.name) end
            cap("remote", caps.remote.state, caps.remote.count, "เฟรมเวิร์กที่พบ: " .. table.concat(names, ", "))
        end
    end
    if not scanned("map") then cap("map", PROF_STATE.notScanned)
    else
        local n = #sdSafe(Scanners.map.list, {})
        cap("map", n > 0 and PROF_STATE.found or PROF_STATE.none, n, "เฉพาะจุดสำคัญในโฟลเดอร์ Map")
    end

    local stats = {found = 0, keyword = 0, none = 0, notScanned = 0, notBuilt = 0}
    for _, c in pairs(caps) do
        if c.state == PROF_STATE.found then stats.found = stats.found + 1
        elseif c.state == PROF_STATE.keyword then stats.keyword = stats.keyword + 1
        elseif c.state == PROF_STATE.none then stats.none = stats.none + 1
        elseif c.state == PROF_STATE.notScanned then stats.notScanned = stats.notScanned + 1
        else stats.notBuilt = stats.notBuilt + 1 end
    end
    return {
        placeId = game.PlaceId, gameId = game.GameId,
        name = (ui.game and ui.game.name) or "?",
        time = os.date("%Y-%m-%d %H:%M:%S"), version = VERSION,
        capabilities = caps, unknown = unknown, stats = stats,
        note = "ทุกค่ามาจากการสแกนในเครื่อง ไม่มีการเดาชื่อหรือข้อมูลปลอม",
    }
end

-- บันทึกโปรไฟล์: ถ้ารอบนี้ยังไม่ได้สแกนหมวดใด จะคงค่าของรอบก่อนไว้ (ไม่ทับด้วยค่า "ยังไม่สแกน")
local function saveProfile(profile)
    local dir = AI_FOLDER .. "/" .. tostring(profile.placeId)
    local old = sdRead(dir .. "/profile.json")
    if old and old.placeId == profile.placeId and type(old.capabilities) == "table" then
        for key, oc in pairs(old.capabilities) do
            local nc = profile.capabilities[key]
            if nc and nc.state == PROF_STATE.notScanned and oc.state ~= PROF_STATE.notScanned then
                profile.capabilities[key] = oc
                profile.capabilities[key].note = "(จากรอบก่อน) " .. tostring(oc.note or "")
            end
        end
    end
    local okE, js = pcall(function() return HttpService:JSONEncode(sanitize(profile)) end)
    if not okE then return false, "แปลง JSON ไม่ได้" end
    if not jsonOk(".json", js) then return false, "JSON อ่านกลับไม่ได้" end
    return writeFile("profile.json", js, false, dir)
end

-- โหลดโปรไฟล์: ปฏิเสธถ้า PlaceId ไม่ตรงกับแมพปัจจุบัน
local function loadProfile()
    local data = sdRead(AI_FOLDER .. "/" .. tostring(game.PlaceId) .. "/profile.json")
    if not data then return nil, "ยังไม่มีโปรไฟล์ของแมพนี้ (พิมพ์ โปรไฟล์ เพื่อสร้าง)" end
    if data.placeId ~= game.PlaceId then return nil, "โปรไฟล์ไม่ตรงกับแมพนี้ ไม่นำมาใช้" end
    return data
end

local function profileText(p)
    local L = {}
    L[#L + 1] = "=== โปรไฟล์เกม " .. tostring(p.name) .. " (PlaceId " .. tostring(p.placeId) .. ") ==="
    L[#L + 1] = "สร้างเมื่อ " .. tostring(p.time) .. " | " .. tostring(p.note)
    local order = {"job", "shop", "vehicle", "npc", "points", "remote", "map"}
    for _, k in ipairs(order) do
        local c = p.capabilities and p.capabilities[k]
        if c then
            L[#L + 1] = string.format("- %s: %s%s%s", c.label or k, c.state or "?",
                (c.count and c.count > 0) and (" (" .. c.count .. ")") or "",
                (c.note and c.note ~= "") and (" — " .. c.note) or "")
        end
    end
    if p.unknown and #p.unknown > 0 then
        L[#L + 1] = "[ระบบที่ยังไม่รู้จัก]"
        for _, u in ipairs(p.unknown) do L[#L + 1] = "- " .. tostring(u.kind) .. " " .. tostring(u.count) .. " รายการ: " .. tostring(u.note) end
    end
    return table.concat(L, "\n")
end

local function profileCommand()
    local p = buildProfile()
    local ok, why = saveProfile(p)
    local head = ok and "บันทึกโปรไฟล์แล้ว " or ("บันทึกโปรไฟล์ไม่สำเร็จ: " .. tostring(why) .. " ")
    logf(head .. "(" .. (p.name or "?") .. ")", ok and "ok" or "warn")
    return head .. "\n" .. profileText(p)
end

local function saveGuarded()
    if Run.active or Auto.active then logf("มีงานกำลังทำอยู่ รอให้เสร็จก่อนค่อยบันทึก", "warn") return false end
    saveAll()
    return true
end

