local function pageScanner(id)
    local sc, s = Scanners[id], St[id]
    local c = card(sc.icon .. " " .. sc.title, sc.desc)
    liveLabel(c, function()
        if s.status == "running" then return string.format("⏳ กำลังสแกน %d%% (%d/%d)", math.floor(overallPct() * 100), Run.done, Run.total) end
        if s.status == "done" then return "✅ สแกนเสร็จ พบ " .. sc.total() .. " รายการ (สแกนมาแล้ว " .. s.scans .. " ครั้ง)" .. (s.truncated and " ⚠️ ถูกตัดตามเพดาน" or "") end
        if s.status == "stopped" then return "⏹️ หยุดกลางคัน" end
        if s.status == "error" then return "❌ เกิดข้อผิดพลาด ดูแท็บบันทึก" end
        return "⬜ ยังไม่ได้สแกน"
    end, "@accent")
    bar(c, function() return s.status == "running" and overallPct() or (s.status == "done" and 1 or 0) end)
    local r = row(c)
    btn(r, "▶ " .. sc.thai, function() runScan({id}) end, 150, true)
    btn(r, "■ หยุด", stopScan, 90)
    btn(r, "💾 บันทึกไฟล์", function() saveOne(id) end, 130)
    local c2 = card("📋 ดัมป์อะไรแล้วบ้าง")
    liveLabel(c2, function()
        local lines = {}
        for _, it in ipairs(sc.items()) do
            lines[#lines + 1] = (it[2] > 0 and "✅ " or "⬜ ") .. it[1] .. ": " .. it[2]
        end
        return table.concat(lines, "\n")
    end)
    local c3 = card("💾 ไฟล์")
    liveLabel(c3, function() return s.saved and ("บันทึกแล้ว: " .. s.saved) or ("ยังไม่ได้บันทึก (จะบันทึกเป็น " .. FOLDER .. "/" .. sc.file .. ")") end, "@muted")
    if id == "job" then
        local c4 = card("🧭 ขั้นตอนงานที่พบ")
        liveLabel(c4, function()
            local d = Scanners.job
            local lines = {}
            for i, it in ipairs(d.items()) do
                if i > 6 then lines[#lines + 1] = (it[2] > 0 and "✅ " or "⬜ ") .. string.sub(it[1], #"ขั้นตอน: " + 1) .. " (" .. it[2] .. ")" end
            end
            return table.concat(lines, "\n")
        end)
    end
end

