• หยุด  • บันทึก  • สถานะ  • สรุป  • แนะนำ
• ตรวจไฟล์ (เช็ก JSON ทุกไฟล์)  • รายงาน (หมวดไหนข้อมูลไม่ครบ)  • กู้คืน (ดูไฟล์ partial_/backup)
• ค้นหา <คำ>  • ใกล้ฉัน
• ธีม <ชื่อ>  • สี #RRGGBB  • พื้นหลัง เปิด/ปิด  • สเกล 1.2  • ความโปร่ง 0.5
• ซ่อน  • ล้างข้อมูล  • ช่วยเหลือ
• ตรวจระบบ (ก่อนสแกน)  • ทดสอบตัวเอง  • ตรวจ json ทั้งหมด  • ข้อผิดพลาด (ฟังก์ชัน/บรรทัดที่พัง)
สั่งผ่านโค้ดได้: BK("สแกนทั้งหมด")]]

local function recommend()
    local out = {}
    for _, id in ipairs(ORDER) do
        if St[id].status ~= "done" then out[#out + 1] = "• " .. Scanners[id].thai .. " ยังไม่ได้ดัมป์" end
    end
    if St.vehicle.status == "done" and Scanners.vehicle.total() == 0 then out[#out + 1] = "• เรียกรถออกมาแล้วสแกนรถซ้ำ" end
    if St.job.status == "done" and Scanners.job.flowFound() < #FLOW then out[#out + 1] = "• เปิดแอปงาน/เริ่มงาน 1 รอบ แล้วสแกนงานซ้ำ เพื่อเก็บขั้นตอนที่ขาด" end
    if Workspace.StreamingEnabled then out[#out + 1] = "• แมพโหลดทีละส่วน: เดินไปหลายจุดแล้วสแกนซ้ำ ข้อมูลจะรวมกัน" end
    if #out == 0 then out[1] = "• ครบแล้ว พิมพ์ บันทึก เพื่อเก็บไฟล์ทั้งหมด" end
    return table.concat(out, "\n")
end

local runCommand
local function searchData(term)
    term = string.lower(term)
    local hits = {}
    for _, id in ipairs(ORDER) do
        for _, r in ipairs(Scanners[id].list()) do
            local hay = string.lower((r.n or "") .. " " .. (r.path or "") .. " " .. (r.text or ""))
            if string.find(hay, term, 1, true) then hits[#hits + 1] = {id = id, r = r} end
        end
    end
    if #hits == 0 then return "ไม่พบ \"" .. term .. "\" ในข้อมูลที่เก็บไว้ (ลองสแกนก่อน)" end
    local out = {"พบ " .. #hits .. " รายการ (แสดง 12 แรก):"}
    for i = 1, math.min(12, #hits) do
        local h = hits[i]
        local p = h.r.p and string.format(" @ %.0f,%.0f,%.0f", h.r.p[1], h.r.p[2], h.r.p[3]) or ""
        out[#out + 1] = Scanners[h.id].icon .. " " .. (h.r.kind or "") .. ": " .. cut(h.r.n or "", 40) .. p
    end
    return table.concat(out, "\n")
end
local function nearby()
    local me = myPos()
    if not me then return "ยังไม่พบตัวละครของคุณ" end
    local list = {}
    for _, r in ipairs(Scanners.job.list()) do
        if r.p then list[#list + 1] = {r = r, d = dist3(r.p, me)} end
    end
    if #list == 0 then return "ยังไม่มีจุดงานในข้อมูล สั่ง สแกนงาน ก่อน" end
    table.sort(list, function(a, b) return a.d < b.d end)
    local out = {"จุดงานใกล้คุณ 8 อันดับ:"}
    for i = 1, math.min(8, #list) do
        out[#out + 1] = string.format("%d) %s — %s ห่าง %.0f studs", i, cut(list[i].r.n or "", 36), list[i].r.kind or "", list[i].d)
    end
    return table.concat(out, "\n")
end

function runCommand(raw)
    local c = string.match(tostring(raw or ""), "^%s*(.-)%s*$")
    local l = string.lower(c)
    aiSay("▶ " .. c)
    local function say(t) aiSay(t) end
    if l == "" or has(l, "ช่วย", "help", "คำสั่ง", "?") then say(HELP) return end
    if has(l, "ตรวจระบบ", "preflight") then
        if has(l, "ข้าม", "ปิด", "skip", "off") then Diag.skip = true say("ปิดการตรวจระบบก่อนสแกนแล้ว (พิมพ์ ตรวจระบบ เปิด เพื่อเปิดกลับ)") return end
        if has(l, "เปิด") then Diag.skip = false say("เปิดการตรวจระบบก่อนสแกนแล้ว") return end
        local rep = Diag.full() pcall(Diag.save) say(rep.text) return
    end
    if has(l, "ทดสอบตัวเอง", "selftest", "self-test", "self test") then
        local rep = Diag.selfTest() pcall(Diag.save) say(rep.text) return
    end
    if has(l, "ตรวจ json", "json ทั้งหมด", "jsonall") then say(Diag.jsonAll().text) return end
    if has(l, "ข้อผิดพลาด", "errors", "error log") then say(ErrLog.text()) return end
    if has(l, "อัตโนมัติ", "auto", "ทำเอง", "ทั้งหมดให้") and not has(l, "บันทึกอัตโนมัติ") and not has(l, "หยุด", "stop", "cancel", "ยกเลิก") then say("เริ่มโหมดอัตโนมัติ: สแกน → เดินสำรวจ → สแกนซ้ำ → บันทึก → สรุป") autoDump() return end
    if has(l, "หยุด", "stop", "cancel", "ยกเลิก") then stopScan() say("สั่งหยุดแล้ว") return end
    if has(l, "ตรวจไฟล์", "ตรวจสอบไฟล์", "verify") then
        local okN, badN, lines = verifyFiles()
        say("ตรวจไฟล์: ผ่าน " .. okN .. " | มีปัญหา " .. badN .. "\n" .. table.concat(lines, "\n")) return
    end
    if has(l, "รายงาน", "ครบไหม", "ขาดอะไร", "coverage") then say(coverageReport().text) return end
    if has(l, "กู้คืน", "กู้ข้อมูล", "recover") then say(recoveryInfo().text) return end
    if has(l, "ล้างข้อมูล", "clear") then
        if Run.active or Auto.active then say("มีงานกำลังทำอยู่ สั่ง หยุด ก่อนแล้วค่อยล้างข้อมูล") return end
        local anyData = false
        for _, id in ipairs(ORDER) do if St[id].scans > 0 or St[id].status == "stopped" then anyData = true end end
        if anyData then pcall(saveAll) say("สำรองข้อมูลลงไฟล์ก่อนล้างแล้ว") end
        Verify.car, Verify.app, Verify.route = nil, nil, nil
        for _, id in ipairs(ORDER) do Scanners[id].reset() St[id] = {status = "idle", scans = 0, saved = nil, truncated = false} end
        say("ล้างข้อมูลที่เก็บไว้ในหน่วยความจำแล้ว (ไฟล์ที่บันทึกแล้วยังอยู่)") logf("ล้างข้อมูลแล้ว") return
    end
    if has(l, "ค้นหา", "search", "find") or (string.sub(l, 1, #"หา ") == "หา ") then
        local term = string.match(c, "^%S+%s+(.+)$")
        if not term then say("พิมพ์ เช่น: ค้นหา ตู้เก็บของ") return end
        say(searchData(term)) return
    end
    if has(l, "ใกล้", "nearby") then say(nearby()) return end
    if has(l, "ธีม", "theme") then
        for i, p in ipairs(PALETTES) do
            if has(l, string.lower(p[1])) then Set.accentHex = "" applyPalette(i) applyTheme() saveSettings() say("เปลี่ยนธีมเป็น " .. p[1]) return end
        end
        local names = {}
        for _, p in ipairs(PALETTES) do names[#names + 1] = p[1] end
        say("ธีมที่มี: " .. table.concat(names, ", ")) return
    end
    local hex = string.match(c, "#(%x%x%x%x%x%x)")
    if hex and has(l, "สี", "color", "accent") then Set.accentHex = "#" .. hex applyPalette(Set.palette) applyTheme() saveSettings() say("ตั้งสีหลัก #" .. hex) return end
    if has(l, "พื้นหลัง", "bg", "background") then
        local on = not has(l, "ปิด", "off")
        Set.bgOn = on if bgImg then bgImg.Visible = on end saveSettings() say("พื้นหลัง" .. (on and "เปิด" or "ปิด")) return
    end
    local num = tonumber(string.match(l, "(%d+%.?%d*)"))
    if has(l, "สเกล", "scale") and num then Set.scale = math.clamp(num, 0.6, 1.6) applyScale() saveSettings() say("สเกล UI = " .. Set.scale) return end
    if has(l, "โปร่ง", "opacity", "transparency") and num then Set.bgT = math.clamp(num, 0, 1) if bgImg then bgImg.ImageTransparency = Set.bgT end saveSettings() say("ความโปร่งรูปพื้นหลัง = " .. Set.bgT) return end
    if has(l, "ซ่อน", "hide") then if root then root.Visible = false end say("ซ่อน UI แล้ว กด RightControl หรือปุ่ม BK เพื่อเปิด") return end
    if has(l, "แสดง", "show") then if root then root.Visible = true end say("แสดง UI แล้ว") return end
    if has(l, "สรุป", "summary", "ai") then say(aiSummary()) return end
    if has(l, "แนะนำ", "next", "ต่อไป") then say(recommend()) return end
    if has(l, "สถานะ", "status", "แล้วบ้าง", "ดัมป์อะไร") then say(statusText()) return end
    if has(l, "โหลดโปรไฟล์", "load profile") then
        local data, why = loadProfile()
        say(data and profileText(data) or tostring(why)) return
    end
    if has(l, "โปรไฟล์", "profile") then say(profileCommand()) return end
    if has(l, "smart dump", "smartdump", "สมาร์ทดัมป์", "สมาร์ท") then
        if Run.active or Auto.active then say("มีงานกำลังทำอยู่ รอให้เสร็จก่อนค่อยบันทึก") return end
        local r = smartDump()
        say(r.text)
        return
    end
    if has(l, "บันทึก", "save", "export", "ส่งออก") then if Run.active or Auto.active then say("มีงานกำลังทำอยู่ รอให้เสร็จก่อนค่อยบันทึก") return end saveAll() say("สั่งบันทึกแล้ว ดูผลในแท็บบันทึก") return end
    if has(l, "สแกน", "scan", "ดัมป์", "dump") then
        local ids = {}
        local function add(id) for _, x in ipairs(ids) do if x == id then return end end ids[#ids + 1] = id end
        if has(l, "ทั้งหมด", "all") then for _, id in ipairs(ORDER) do add(id) end
        else
            if has(l, "แมพ", "map", "ถนน", "อาคาร") then add("map") end
            if has(l, "รถ", "vehicle", "car", "bike") then add("vehicle") end
            if has(l, "npc", "เอ็นพีซี", "ตัวละคร") then add("npc") end
            if has(l, "งาน", "job", "ส่ง") then add("job") end
            if has(l, "ปุ่ม", "button", "ui", "โต้ตอบ", "interact", "จุดกด", "prompt") then add("ui") end
            if has(l, "remote", "รีโมท") then add("remote") end
            if #ids == 0 then for _, id in ipairs(ORDER) do add(id) end end
        end
        local names = {}
        for _, id in ipairs(ids) do names[#names + 1] = Scanners[id].thai end
        say("กำลังเริ่ม: " .. table.concat(names, ", "))
        runScan(ids) return
    end
    say("ไม่เข้าใจคำสั่งนี้ พิมพ์ ช่วยเหลือ เพื่อดูรายการ")
end

local function pageAI()
    local c = card("🤖 ผู้ช่วย AI ในเครื่อง", "พิมพ์คำสั่งภาษาไทยหรืออังกฤษ ระบบนี้ทำงานแบบกฎในเครื่อง ไม่ส่งข้อมูลออกอินเทอร์เน็ต พิมพ์ \"ช่วยเหลือ\" เพื่อดูคำสั่งทั้งหมด")
    local box = mk("TextBox", {Size = UDim2.new(1, 0, 0, 38), BackgroundColor3 = "@panel2", Text = "", PlaceholderText = "พิมพ์คำสั่ง เช่น สแกนทั้งหมด / สรุป / ค้นหา ตู้เก็บของ", TextColor3 = "@text", PlaceholderColor3 = "@muted", Font = Enum.Font.Gotham, TextSize = 14, ClearTextOnFocus = false, TextXAlignment = Enum.TextXAlignment.Left, BorderSizePixel = 0}, c)
    corner(box, 9) stroke(box, 0.3)
    mk("UIPadding", {PaddingLeft = UDim.new(0, 10)}, box)
    local function send()
        local t = box.Text
        box.Text = ""
        runCommand(t)
    end
    pconnect(box.FocusLost, function(enter) if enter then send() end end)
    local r = row(c)
    btn(r, "➤ ส่งคำสั่ง", send, 120, true)
    for _, q in ipairs({"อัตโนมัติ", "สแกนทั้งหมด", "สถานะ", "สรุป", "รายงาน", "ตรวจไฟล์", "แนะนำ", "ช่วยเหลือ"}) do
        btn(r, q, function() runCommand(q) end, 100)
    end
    local out = card("💬 ผลลัพธ์")
    liveLabel(out, function()
        local lines, n = {}, #AIOut
        for i = math.max(1, n - 24), n do lines[#lines + 1] = AIOut[i] end
        return #lines > 0 and table.concat(lines, "\n") or "ยังไม่มีคำสั่ง"
    end)
end

