local function pageStyle()
    local c = card("🎨 ปรับแต่งหน้าตา", "เปลี่ยนสี รูปพื้นหลัง ความโปร่ง และขนาด UI ได้ทันที ค่าจะถูกจำไว้ในไฟล์ settings.json")
    local r = row(c)
    for i, p in ipairs(PALETTES) do
        local b = btn(r, p[1], function() Set.accentHex = "" applyPalette(i) applyTheme() saveSettings() showTab(currentTab) end, 104)
        b.BackgroundColor3 = p[2].accent
        b.TextColor3 = Color3.fromRGB(8, 10, 8)
    end
    local hexRow = row(c)
    local hb = mk("TextBox", {Size = UDim2.fromOffset(150, 36), BackgroundColor3 = "@panel2", Text = Set.accentHex, PlaceholderText = "#22FF55", TextColor3 = "@text", PlaceholderColor3 = "@muted", Font = Enum.Font.Gotham, TextSize = 14, ClearTextOnFocus = false, BorderSizePixel = 0}, hexRow)
    corner(hb, 9) stroke(hb, 0.3)
    btn(hexRow, "ใช้สีหลังนี้", function()
        local h = hb.Text:gsub("%s", "")
        if string.match(h, "^#?%x%x%x%x%x%x$") then
            if string.sub(h, 1, 1) ~= "#" then h = "#" .. h end
            Set.accentHex = h applyPalette(Set.palette) applyTheme() saveSettings() showTab(currentTab)
        else logf("รูปแบบสีต้องเป็น #RRGGBB", "warn") end
    end, 120)
    btn(hexRow, "ล้างสีกำหนดเอง", function() Set.accentHex = "" applyPalette(Set.palette) applyTheme() saveSettings() showTab(currentTab) end, 140)
    local c2 = card("🖼️ รูปพื้นหลัง")
    switch(c2, "แสดงรูปพื้นหลัง", "รูปโปรเจกต์เด็กมหานคร เรซซิ่ง", Set.bgOn, function(v) Set.bgOn = v if bgImg then bgImg.Visible = v end saveSettings() end)
    slider(c2, "ความโปร่งของรูป (0 = ชัด, 1 = จาง)", 0, 1, Set.bgT, "%.2f", function(v) Set.bgT = v if bgImg then bgImg.ImageTransparency = v end end)
    slider(c2, "ความมืดของฉากทับ (ช่วยให้อ่านตัวหนังสือง่าย)", 0, 0.95, Set.overlay, "%.2f", function(v) Set.overlay = v if overlay then overlay.BackgroundTransparency = v end end)
    local c3 = card("📐 ขนาดและพฤติกรรม")
    slider(c3, "ขนาด UI", 0.6, 1.5, Set.scale, "%.2f", function(v) Set.scale = v applyScale() end)
    switch(c3, "บันทึกไฟล์อัตโนมัติหลังสแกน", "เขียนไฟล์ลงโฟลเดอร์ทันทีเมื่อสแกนเสร็จ", Set.autosave, function(v) Set.autosave = v saveSettings() end)
    switch(c3, "กลับจุดเริ่มต้นเมื่อโหมดอัตโนมัติเสร็จ", "เดินกลับตำแหน่งที่กดเริ่ม", Set.returnStart, function(v) Set.returnStart = v saveSettings() end)
    switch(c3, "ปุ่มลอย BK", "ปุ่มกลมที่ขอบจอสำหรับเปิด/ปิด UI (มือถือใช้ปุ่มนี้)", Set.fab, function(v) Set.fab = v if fab then fab.Visible = v end saveSettings() end)
    local r2 = row(c3)
    btn(r2, "↺ รีเซ็ตค่าตั้ง", function()
        Set = {palette = 1, accentHex = "", bgOn = true, bgT = 0.45, overlay = 0.42, scale = 1, autosave = true, fab = true, returnStart = true}
        applyPalette(1) applyTheme()
        if bgImg then bgImg.Visible = true bgImg.ImageTransparency = Set.bgT end
        if overlay then overlay.BackgroundTransparency = Set.overlay end
        applyScale()
        if fab then fab.Visible = true end
        saveSettings() showTab(currentTab)
    end, 140)
    btn(r2, "⏻ ปิดโปรแกรมถาวร", function() if ENV.BALLKUN_SCANNER then ENV.BALLKUN_SCANNER.Destroy() end end, 170)

    local c4 = card("🔤 ตัวอักษร", "เลือกฟอนต์ ขนาด ระยะห่างบรรทัด และสีข้อความ (ค่าเริ่มต้นคือรูปแบบเดิม)")
    local FONTS = {"", "GothamBold", "Gotham", "SourceSansBold", "SourceSans", "Code", "Arial"}
    local fr = row(c4)
    btn(fr, "ฟอนต์: " .. ((Set.fontName or "") ~= "" and Set.fontName or "ค่าเดิม"), function()
        local idx = 1
        for i, f in ipairs(FONTS) do if f == (Set.fontName or "") then idx = i end end
        Set.fontName = FONTS[idx % #FONTS + 1]
        saveSettings() applyFonts() showTab(currentTab)
    end, 200)
    slider(c4, "ขนาดตัวอักษร", 0.8, 1.6, Set.fontScale or 1, "%.2f", function(v) Set.fontScale = v applyFonts() saveSettings() end)
    slider(c4, "ระยะห่างบรรทัด", 1, 1.6, Set.lineSpacing or 1, "%.2f", function(v) Set.lineSpacing = v applyFonts() saveSettings() end)
    local hr = row(c4)
    local tb = mk("TextBox", {Size = UDim2.fromOffset(150, 36), BackgroundColor3 = "@panel2", Text = Set.textHex or "", PlaceholderText = "#RRGGBB", TextColor3 = "@text", Font = Enum.Font.Gotham, TextSize = 14, ClearTextOnFocus = false}, hr)
    corner(tb, 9) stroke(tb, 0.3)
    btn(hr, "ใช้สีข้อความนี้", function()
        local h = string.gsub(tb.Text, "%s", "")
        if string.match(h, "^#?%x%x%x%x%x%x$") then
            if string.sub(h, 1, 1) ~= "#" then h = "#" .. h end
            Set.textHex = h applyFonts() saveSettings() showTab(currentTab)
        else logf("รูปแบบสีต้องเป็น #RRGGBB", "warn") end
    end, 130)
    btn(hr, "ค่าเดิม", function() Set.textHex = "" applyFonts() saveSettings() showTab(currentTab) end, 100)
end

