local LIST_CAP, LOAD_CAP = 60, 40
local SCHEMA = 2
local OPTION_NAMES = {"movement", "vehicle", "interaction", "job", "route", "result", "aiLearning", "aiAnalyzer", "aiReplay",
    "ixPrompt", "ixClick", "ixTool", "ixGui", "npc"}
