--------------------------------------------------------------------
-- เครื่องมือไฟล์/JSON (ชื่อเฉพาะของ V10.2 ไม่ชนกับ V9)
--------------------------------------------------------------------
local function sg(fn, fb)
    local ok, v = pcall(fn)
    if ok and v ~= nil then return v end
    return fb
end
local function canW() return type(writefile) == "function" end
local function canR() return type(readfile) == "function" end
local function canL() return type(listfiles) == "function" end

local function fexists(path)
    if type(isfile) ~= "function" then return canR() and pcall(readfile, path) end
    local ok, ex = pcall(isfile, path)
    return ok and ex == true
end

local function mkdirs(dir)
    if type(makefolder) ~= "function" then return false end
    local acc
    for part in string.gmatch(dir, "[^/]+") do
        acc = acc and (acc .. "/" .. part) or part
        local exists = false
        if type(isfolder) == "function" then
            local ok, v = pcall(isfolder, acc)
            exists = ok and v == true
        end
        if not exists then pcall(makefolder, acc) end
    end
    return true
end

-- เขียน JSON แล้วอ่านกลับตรวจ คืน ok, path|เหตุผล, ขนาดไบต์
local function wjson(path, data)
    if not canW() then return false, "ตัวรันไม่มี writefile", 0 end
    local ok, js = pcall(function() return HttpService:JSONEncode(data) end)
    if not ok then return false, "แปลง JSON ไม่ได้", 0 end
    mkdirs(string.match(path, "^(.*)/[^/]+$") or ROOT)
    if not pcall(writefile, path, js) then return false, "เขียนไฟล์ไม่สำเร็จ", 0 end
    if canR() then
        local okR, back = pcall(readfile, path)
        if not okR or back ~= js then return false, "อ่านกลับแล้วไม่ตรง", 0 end
    end
    return true, path, #js
end

local function rjson(path)
    if not canR() then return nil, "ตัวรันไม่มี readfile" end
    if not fexists(path) then return nil, "ไม่พบไฟล์" end
    local ok, c = pcall(readfile, path)
    if not ok or type(c) ~= "string" then return nil, "อ่านไฟล์ไม่ได้" end
    local okD, d = pcall(function() return HttpService:JSONDecode(c) end)
    if not okD or type(d) ~= "table" then return nil, "JSON เสีย" end
    return d
end
M.io = {write = wjson, read = rjson}

-- รหัส session ต้องเป็นตัวอักษร/ตัวเลข/_/- เท่านั้น กันเขียนหลุดโฟลเดอร์
local function safeId(id)
    id = tostring(id or "")
    if id ~= "" and string.match(id, "^[%w_%-]+$") then return id end
    return nil
end

local function mapDir(pid) return ROOT .. "/" .. tostring(pid) end
local function sessionDir(pid) return mapDir(pid) .. "/sessions" end
local function sessionPath(pid, id) return sessionDir(pid) .. "/" .. tostring(id) .. ".json" end
local function now() return os.date("%Y-%m-%d %H:%M:%S") end

local function say(msg, level)
    M.lastMsg = tostring(msg)
    logf(msg, level)
end

