-- MULTI MAP: ตรวจ PlaceId โหลด DB ตามแมพ แยกข้อมูล รองรับแมพใหม่ กันข้อมูลข้ามแมพ
--------------------------------------------------------------------
local MM = {placeId = game.PlaceId, db = nil, isNew = false, stops = nil}
M.MultiMap = MM

function MM.indexPath() return ROOT .. "/maps_index.json" end
function MM.dbPath(pid) return mapDir(pid or game.PlaceId) .. "/map_db.json" end

-- ลงทะเบียนแมพปัจจุบัน: แมพใหม่จะสร้าง DB ของตัวเองอัตโนมัติ แมพเดิมโหลดของเดิม
function MM.register()
    local pid = game.PlaceId
    local idx = rjson(MM.indexPath()) or {maps = {}}
    if type(idx.maps) ~= "table" then idx.maps = {} end
    local known = false
    for _, p in ipairs(idx.maps) do if p == pid then known = true break end end
    local db = rjson(MM.dbPath(pid))
    MM.isNew = db == nil
    if not db then
        db = {schema = SCHEMA, placeId = pid, gameId = game.GameId, name = tostring(game.Name),
            firstSeen = now(), visits = 0}
    end
    db.visits = (tonumber(db.visits) or 0) + 1
    db.lastSeen = now()
    db.builtinStops = KNOWN_STOPS_BY_PLACE[pid] ~= nil
    MM.stops = KNOWN_STOPS_BY_PLACE[pid]
    MM.db = db
    if canW() then
        if not known then
            idx.maps[#idx.maps + 1] = pid
            wjson(MM.indexPath(), idx)
        end
        wjson(MM.dbPath(pid), db)
    end
    return db
end

function MM.listMaps()
    local idx = rjson(MM.indexPath())
    return idx and idx.maps or {}
end

