-- JOB RECORDER v2 (ส่วนที่ 5): ประกาศตารางไว้ก่อน validateSession/addEvent เพื่อให้อ้างถึงได้ ฟังก์ชันเติมภายหลัง (บล็อก JB)
-- ใช้ตารางเดียว ไม่เพิ่ม local ระดับบนของโมดูล (กันชนเพดาน local ของ Lua)
local JB = {MARK_CAP = 200, NOTE_CAP = 100, NOTE_LEN = 120,
    MARK_KINDS = {vehicle = true, result = true, error = true, npc = true, interaction_abort = true}}
M.JB = JB

--------------------------------------------------------------------
-- ตรวจความถูกต้องของ session
--------------------------------------------------------------------
local function validateSession(d, expectPid)
    local problems = {}
    if type(d) ~= "table" then return false, {"ไม่ใช่ข้อมูล session"} end
    if type(d.id) ~= "string" or not safeId(d.id) then problems[#problems + 1] = "รหัส session ไม่ถูกต้อง" end
    if expectPid and d.placeId ~= expectPid then problems[#problems + 1] = "PlaceId ไม่ตรงกับแมพนี้ ไม่นำมาใช้" end
    if type(d.path) ~= "table" then problems[#problems + 1] = "ไม่มีเส้นทาง" end
    if type(d.events) ~= "table" then problems[#problems + 1] = "ไม่มีรายการเหตุการณ์" end
    local last = -1
    for _, p in ipairs(type(d.path) == "table" and d.path or {}) do
        if type(p.x) ~= "number" or type(p.z) ~= "number" or p.x ~= p.x or p.z ~= p.z then
            problems[#problems + 1] = "มีพิกัดไม่ถูกต้อง"
            break
        end
        if type(p.t) == "number" and p.t < last then
            problems[#problems + 1] = "เวลาในเส้นทางไม่เรียงลำดับ"
            break
        end
        last = type(p.t) == "number" and p.t or last
    end
    for i, e in ipairs(type(d.events) == "table" and d.events or {}) do
        if type(e) ~= "table" or type(e.kind) ~= "string" then
            problems[#problems + 1] = "เหตุการณ์ลำดับที่ " .. i .. " ข้อมูลเสียหาย"
            break
        end
        if (e.kind == "interaction" or e.kind == "interaction_abort" or e.kind == "npc") and (type(e.t) ~= "number" or e.t ~= e.t) then
            problems[#problems + 1] = "เหตุการณ์โต้ตอบลำดับที่ " .. i .. " ไม่มีเวลาที่ถูกต้อง"
            break
        end
        if (e.kind == "interaction" or e.kind == "npc") and e.pos ~= nil and (type(e.pos) ~= "table" or type(e.pos[1]) ~= "number" or type(e.pos[3]) ~= "number"
            or e.pos[1] ~= e.pos[1] or e.pos[3] ~= e.pos[3]) then
            problems[#problems + 1] = "เหตุการณ์โต้ตอบลำดับที่ " .. i .. " พิกัดไม่ถูกต้อง"
            break
        end
    end
    for i, m in ipairs(type(d.missions) == "table" and d.missions or {}) do
        if type(m) ~= "table" then
            problems[#problems + 1] = "ภารกิจลำดับที่ " .. i .. " ข้อมูลเสียหาย"
            break
        end
        if m.result ~= "success" and m.result ~= "fail" and m.result ~= "unknown" then
            problems[#problems + 1] = "ผลภารกิจไม่ถูกต้อง: " .. tostring(m.result)
            break
        end
        local badM = JB.validateMission(m, i)
        if badM then
            problems[#problems + 1] = badM
            break
        end
    end
    return #problems == 0, problems
end
M.validateSession = validateSession

--------------------------------------------------------------------
-- SESSION MANAGER (แยกตามแมพ: BALL_KUN_AI_Dump/<PlaceId>/sessions)
--------------------------------------------------------------------
function Session.load(id)
    id = safeId(id)
    if not id then return nil, "รหัส session ไม่ถูกต้อง" end
    local d, why = rjson(sessionPath(game.PlaceId, id))
    if not d then return nil, why end
    local ok, problems = validateSession(d, game.PlaceId)
    if not ok then return nil, table.concat(problems, " | ") end
    return d
end

function Session.list()
    local out = {}
    if not canL() then return out, "ตัวรันไม่มี listfiles" end
    local ok, files = pcall(listfiles, sessionDir(game.PlaceId))
    if not ok or type(files) ~= "table" then return out end
    local ids = {}
    for _, f in ipairs(files) do
        local id = string.match(tostring(f), "([^/\\]+)%.json$")
        if id and safeId(id) and string.sub(id, 1, 6) ~= "_test_" then ids[#ids + 1] = id end
    end
    table.sort(ids, function(a, b) return a > b end)
    for i, id in ipairs(ids) do
        if i > LIST_CAP then break end
        local d = rjson(sessionPath(game.PlaceId, id))
        if d and d.placeId == game.PlaceId then
            out[#out + 1] = {id = id, name = d.name or id, profession = d.profession or "",
                startedAt = d.startedAt, duration = d.duration or 0, recording = d.recording == true,
                events = #(d.events or {}), points = #(d.path or {}), sizeBytes = d.sizeBytes or 0,
                learn = d.learn ~= false, placeId = d.placeId}
        end
    end
    return out, #ids > LIST_CAP and ("แสดง " .. LIST_CAP .. " รายการล่าสุดจากทั้งหมด " .. #ids) or nil
end

function Session.groupByProfession(list)
    local g = {}
    for _, s in ipairs(list) do
        local key = s.profession ~= "" and s.profession or "(ไม่ระบุอาชีพ)"
        g[key] = g[key] or {}
        table.insert(g[key], s)
    end
    return g
end

function Session.rename(id, name)
    local d, why = Session.load(id)
    if not d then return false, why end
    d.name = tostring(name or ""):sub(1, 80)
    return wjson(sessionPath(game.PlaceId, d.id), d)
end

function Session.delete(id)
    id = safeId(id)
    if not id then return false, "รหัส session ไม่ถูกต้อง" end
    if type(delfile) ~= "function" then return false, "ตัวรันไม่มี delfile ลบไม่ได้" end
    if Rec.active and Rec.session and id == Rec.session.id then return false, "ห้ามลบ session ที่กำลังบันทึก" end
    local okD = pcall(delfile, sessionPath(game.PlaceId, id))
    pcall(delfile, sessionDir(game.PlaceId) .. "/" .. id .. "_report.txt")
    if not okD then return false, "ลบไฟล์ไม่สำเร็จ" end
    return true
end

function Session.export(id)
    local d, why = Session.load(id)
    if not d then return false, why end
    local path = ROOT .. "/exports/" .. tostring(d.placeId) .. "_" .. d.id .. ".json"
    if fexists(path) then return false, "มีไฟล์ส่งออกนี้แล้ว ไม่เขียนทับ" end
    return wjson(path, d)
end

function Session.import(path)
    path = tostring(path or "")
    if path == "" then return false, "ยังไม่ได้ใส่ path ไฟล์" end
    local d, why = rjson(path)
    if not d then return false, why end
    local ok, problems = validateSession(d, game.PlaceId)
    if not ok then return false, table.concat(problems, " | ") end
    if fexists(sessionPath(game.PlaceId, d.id)) then return false, "session นี้มีอยู่แล้ว ข้ามเพื่อไม่ให้ซ้ำ" end
    return wjson(sessionPath(game.PlaceId, d.id), d)
end

-- โหลด session ทั้งหมดของแมพนี้ (เฉพาะที่ใช้เรียนรู้ได้) สำหรับ Analyzer/Replay
function Session.loadAll(learnOnly)
    local out = {}
    for _, s in ipairs((Session.list())) do
        if #out >= LOAD_CAP then break end
        if (not learnOnly) or s.learn then
            local d = Session.load(s.id)
            if d then out[#out + 1] = d end
        end
    end
    return out
end

-- ID ใหม่ = วันเวลา + ส่วนสุ่ม และต้องไม่ตรงกับไฟล์ที่มีอยู่ (กันเขียนทับเมื่อเริ่มในวินาทีเดียวกัน หรือหลายจอใช้ workspace ร่วมกัน)
function Session.newId()
    local stamp = os.date("%Y%m%d_%H%M%S")
    for _ = 1, 20 do
        local tail = string.gsub(tostring(sg(function() return HttpService:GenerateGUID(false) end, "")), "[^%x]", "")
        tail = string.sub(tail, 1, 8)
        if #tail < 8 then tail = string.format("%04x%04x", math.random(0, 65535), math.random(0, 65535)) end
        local id = stamp .. "_" .. string.lower(tail)
        if not fexists(sessionPath(game.PlaceId, id)) then return id end
    end
    return nil
end

--------------------------------------------------------------------
-- MODE 1: MANUAL LEARNING (Recorder)
--------------------------------------------------------------------
local function elapsed()
    local t0 = os.clock()
    local pausedNow = Rec.paused and (t0 - Rec.pausedAt) or 0
    local t = Rec.offset + (t0 - Rec.t0) - Rec.pausedTotal - pausedNow
    return math.floor(math.max(0, t) * 100 + 0.5) / 100
end

local function addEvent(kind, rec, dedupKey)
    local s = Rec.session
    if not s or Rec.paused then return false end
    if #s.events >= MAX_EVENTS then return false end
    if dedupKey then
        local last = Rec.lastEvent[dedupKey]
        if last and elapsed() - last < 0.5 then
            Rec.counts.duplicatesSkipped = Rec.counts.duplicatesSkipped + 1
            return false
        end
        Rec.lastEvent[dedupKey] = elapsed()
    end
    rec.t = elapsed()
    rec.kind = kind
    s.events[#s.events + 1] = rec
    Rec.counts.events = Rec.counts.events + 1
    if kind == "interaction" then Rec.counts.interactions = Rec.counts.interactions + 1 end
    if Rec.mission and Rec.options.job then
        if kind == "interaction" then
            Rec.mission.steps[#Rec.mission.steps + 1] = {t = rec.t, action = rec.action, object = rec.object, path = rec.path, pos = rec.pos, type = rec.type}
        elseif JB.MARK_KINDS[kind] then
            pcall(JB.mark, kind, rec) -- marks เป็นข้อมูลประกอบ พังแล้วต้องไม่ล้มการบันทึกหลัก
        end
    end
    return true
end

local function sampleMovement()
    if Rec.paused or not Rec.session then return end
    local t0 = os.clock()
    if t0 - Rec.lastSample < SAMPLE_EVERY then return end
    Rec.lastSample = t0
    local ch = LP.Character
    local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
    if not hrp then return end
    local p = hrp.Position
    local last = Rec.lastPos
    if last and math.sqrt((p.X - last[1]) ^ 2 + (p.Z - last[3]) ^ 2) < MIN_MOVE then return end
    Rec.lastPos = {p.X, p.Y, p.Z}
    Rec.live.move = Rec.live.move + 1
    if Rec.options.movement then
        if #Rec.session.path >= MAX_POINTS then
            if not Rec.session.capped then
                Rec.session.capped = true
                addEvent("error", {src = "system", note = "ถึงเพดานจุดเส้นทาง หยุดบันทึกตำแหน่งแล้ว"})
            end
        else
            Rec.session.path[#Rec.session.path + 1] = {t = elapsed(), x = p.X, y = p.Y, z = p.Z}
            Rec.counts.points = Rec.counts.points + 1
        end
    end
    if Rec.options.route then
        local lr = Rec.lastRoutePos
        if not lr or math.sqrt((p.X - lr[1]) ^ 2 + (p.Z - lr[3]) ^ 2) >= ROUTE_STEP then
            Rec.lastRoutePos = {p.X, p.Y, p.Z}
            Rec.session.route = Rec.session.route or {}
            if #Rec.session.route < MAX_POINTS then
                Rec.session.route[#Rec.session.route + 1] = {t = elapsed(), x = p.X, y = p.Y, z = p.Z}
            end
        end
    end
end

local function instPos(inst)
    if not inst then return nil end
    local ok, pos = pcall(function()
        if inst:IsA("BasePart") then return inst.Position end
        if inst:IsA("Model") then return inst:GetPivot().Position end
        local parent = inst.Parent
        if parent and parent:IsA("BasePart") then return parent.Position end
        return nil
    end)
    if ok and pos then return {pos.X, pos.Y, pos.Z} end
    return nil
end

local function rconn(sig, fn)
    local c = sig:Connect(fn)
    Rec.conns[#Rec.conns + 1] = c
    return c
end

local function dropCharConns()
    for _, c in ipairs(Rec.charConns) do pcall(function() c:Disconnect() end) end
    Rec.charConns = {}
end

local NP = {}
M.NP = NP

--------------------------------------------------------------------
-- INTERACTION RECORDER v2 (ส่วนที่ 3)
-- บันทึกเฉพาะสิ่งที่ผู้เล่นกดเอง: ProximityPrompt (+ถือค้าง/ปล่อยก่อนครบ), ClickDetector ซ้าย/ขวา, Tool (ถือ/เก็บ/ใช้), ปุ่ม UI
-- อ่านอย่างเดียว: ไม่เรียก Remote ไม่กดแทนผู้เล่น ไม่บันทึกข้อความที่พิมพ์ (TextBox/แชต) ไม่บันทึกปุ่มคีย์บอร์ดทั่วไป
-- src = "game"  : ตรวจจับได้จริงจาก event ฝั่งไคลเอนต์
-- held / dist    : คำนวณฝั่งไคลเอนต์ ไม่ใช่ผลที่เซิร์ฟเวอร์ยืนยัน
-- ใช้ตาราง IX เป็นที่เก็บทั้งหมด (ไม่เพิ่ม local ระดับบนของโมดูล)
--------------------------------------------------------------------
local IX = {
    btnConn = {}, toolSeen = setmetatable({}, {__mode = "k"}), holds = setmetatable({}, {__mode = "k"}),
    lastUse = setmetatable({}, {__mode = "k"}),
    guiCount = 0, toolCount = 0, guiFullNoted = false, lastSweep = 0, errors = 0,
    MAX_GUI = 600, MAX_TOOLS = 200, USE_GAP = 2, HOLD_TOL = 0.1,
}
M.IX = IX

function IX.round(n, d)
    local m = 10 ^ (d or 1)
    return math.floor(n * m + 0.5) / m
end

-- ข้อความจากเกม: ตัดอักขระควบคุม, กัน UTF-8 เสีย (JSONEncode อาจล้ม), ตัดตามจำนวนตัวอักษรไม่ใช่ไบต์
function IX.label(s, n)
    n = n or 60
    s = tostring(s == nil and "" or s)
    s = s:gsub("%c", " ")
    local len = utf8.len(s)
    if not len then
        s = s:gsub("[\128-\255]", "?")
        len = #s
    end
    if len > n then
        local cut = utf8.offset(s, n + 1)
        s = s:sub(1, (cut or (n + 1)) - 1)
    end
    return s
end

function IX.on(sub)
    return Rec.active and Rec.options.interaction == true and Rec.options[sub] ~= false
end

function IX.guard(fn, ...)
    local ok, err = pcall(fn, ...)
    if not ok then
        IX.errors = IX.errors + 1
        Rec.lastError = "Interaction: " .. tostring(err)
    end
    return ok
end

function IX.myPos()
    local ch = LP.Character
    local hrp = ch and ch:FindFirstChild("HumanoidRootPart")
    if not hrp then return nil end
    local p = hrp.Position
    return {IX.round(p.X), IX.round(p.Y), IX.round(p.Z)}
end

function IX.dist(pos)
    local me = IX.myPos()
    if not (pos and me) then return nil end
    return IX.round(math.sqrt((me[1] - pos[1]) ^ 2 + (me[2] - pos[2]) ^ 2 + (me[3] - pos[3]) ^ 2))
end

function IX.seated()
    local ch = LP.Character
    local hum = ch and ch:FindFirstChildOfClass("Humanoid")
    return hum ~= nil and hum.SeatPart ~= nil
end

-- ปล่อยก่อนครบเวลาถือ (ครบแล้วให้รอ PromptTriggered ไม่นับเป็นยกเลิก)
function IX.isAbort(held, required)
    if type(held) ~= "number" or type(required) ~= "number" then return false end
    return held < required - IX.HOLD_TOL
end

-- ทางเดียวที่เขียนเหตุการณ์โต้ตอบ: ผ่าน addEvent เดิม (กัน pause / เพดาน / ซ้ำ) แล้วนับตามประเภท
function IX.emit(kind, rec, key)
    local ok = addEvent(kind, rec, key)
    if ok and kind == "interaction" and rec.npc then NP.interact(rec) end
    if ok then
        local bt = Rec.counts.byType
        if bt then
            local k = kind == "interaction_abort" and "abort" or rec.type
            bt[k] = (bt[k] or 0) + 1
        end
    end
    return ok
end

-- ProximityPrompt
function IX.onPrompt(prompt)
    local st = IX.holds[prompt]
    local held
    if st then
        st.triggered = true
        held = os.clock() - st.t0
    end
    if not IX.on("ixPrompt") then return end
    local path = prompt:GetFullName()
    local pos = instPos(prompt.Parent)
    IX.emit("interaction", {type = "prompt", src = "game", action = IX.label(prompt.ActionText), object = IX.label(prompt.ObjectText),
        path = path, pos = pos, dist = IX.dist(pos), hold = prompt.HoldDuration, key = prompt.KeyboardKeyCode.Name,
        held = held and IX.round(held, 2) or nil, npc = NP.of(prompt)}, "pr:" .. path)
end

function IX.onHoldEnd(prompt)
    local st = IX.holds[prompt]
    IX.holds[prompt] = nil
    if not st then return end
    Rec.live.hold = Rec.live.hold + 1
    if st.triggered or not IX.on("ixPrompt") then return end
    local held = os.clock() - st.t0
    if not IX.isAbort(held, prompt.HoldDuration) then return end
    local path = prompt:GetFullName()
    IX.emit("interaction_abort", {type = "prompt", src = "game", action = IX.label(prompt.ActionText), object = IX.label(prompt.ObjectText),
        path = path, pos = instPos(prompt.Parent), held = IX.round(held, 2), hold = prompt.HoldDuration,
        note = "ปล่อยก่อนครบเวลาถือ (คำนวณฝั่งไคลเอนต์)"}, "ab:" .. path)
end

function IX.hookPrompts()
    rconn(PPS.PromptButtonHoldBegan, function(prompt, player)
        if player ~= LP or not Rec.active then return end
        IX.holds[prompt] = {t0 = os.clock(), triggered = false}
    end)
    rconn(PPS.PromptButtonHoldEnded, function(prompt, player)
        if player ~= LP or not Rec.active then return end
        IX.guard(IX.onHoldEnd, prompt)
    end)
end

-- ClickDetector (ซ้าย/ขวา)
function IX.onClick(det, button)
    if not IX.on("ixClick") then return end
    local par = det.Parent
    local pos = instPos(par)
    local path = det:GetFullName()
    IX.emit("interaction", {type = "click", src = "game", action = button == "right" and "rightclick" or "click",
        object = IX.label(par and par.Name or "?"), path = path, pos = pos, dist = IX.dist(pos),
        maxDist = det.MaxActivationDistance, button = button, npc = NP.of(det)}, "clk:" .. path .. button)
end

-- Tool: ถือ / เก็บ / ใช้ (ใช้ซ้ำเร็ว ๆ บันทึกทุก USE_GAP วินาที ส่วนที่เหลือนับเป็นซ้ำ)
function IX.onTool(tool, act)
    if not Rec.active then return end
    Rec.live.tool = Rec.live.tool + 1
    if act == "use" then
        local t0 = os.clock()
        local last = IX.lastUse[tool]
        if last and t0 - last < IX.USE_GAP then
            Rec.counts.duplicatesSkipped = Rec.counts.duplicatesSkipped + 1
            return
        end
        IX.lastUse[tool] = t0
    end
    if not IX.on("ixTool") then return end
    local nm = IX.label(tool.Name)
    IX.emit("interaction", {type = "tool", src = "game", action = "tool_" .. act, object = nm, path = "Tool:" .. nm,
        at = IX.myPos(), seated = IX.seated() or nil}, "tl:" .. nm .. act)
end

function IX.hookTool(tool)
    if not tool:IsA("Tool") or IX.toolSeen[tool] then return end
    if IX.toolCount >= IX.MAX_TOOLS then return end
    IX.toolSeen[tool] = true
    IX.toolCount = IX.toolCount + 1
    rconn(tool.Activated, function() IX.guard(IX.onTool, tool, "use") end)
    rconn(tool.Equipped, function() IX.guard(IX.onTool, tool, "equip") end)
    rconn(tool.Unequipped, function() IX.guard(IX.onTool, tool, "unequip") end)
end

function IX.hookChar(char)
    for _, t in ipairs(char:GetChildren()) do IX.hookTool(t) end
    Rec.charConns[#Rec.charConns + 1] = char.ChildAdded:Connect(IX.hookTool)
    local bp = LP:FindFirstChild("Backpack") or LP:WaitForChild("Backpack", 3)
    if bp and Rec.active then
        for _, t in ipairs(bp:GetChildren()) do IX.hookTool(t) end
        Rec.charConns[#Rec.charConns + 1] = bp.ChildAdded:Connect(IX.hookTool)
    end
end

-- ปุ่ม UI (TextButton / ImageButton) ที่ผู้เล่นกดเอง ไม่รวม UI ของ BALL KUN เอง
function IX.isOwnGui(inst)
    local scr = inst:FindFirstAncestorOfClass("ScreenGui")
    return scr ~= nil and string.sub(scr.Name, 1, 7) == "BALLKUN"
end

function IX.onGui(btn)
    if not Rec.active then return end
    Rec.live.gui = Rec.live.gui + 1
    if not IX.on("ixGui") then return end
    local text = btn:IsA("TextButton") and btn.Text or ""
    if text == "" then text = btn.Name end
    local scr = btn:FindFirstAncestorOfClass("ScreenGui")
    local path = btn:GetFullName()
    IX.emit("interaction", {type = "gui", src = "game", action = "ui_click", object = IX.label(text), path = path,
        screen = scr and IX.label(scr.Name) or nil, at = IX.myPos()}, "gui:" .. path)
end

-- ปุ่มที่ถูกลบแล้วคืนโควตา (เกมที่สร้าง UI ใหม่บ่อย ๆ จะไม่เต็มเร็ว)
function IX.sweep()
    local freed = 0
    for inst, c in pairs(IX.btnConn) do
        if not inst:IsDescendantOf(PlayerGui) then
            pcall(function() c:Disconnect() end)
            IX.btnConn[inst] = nil
            freed = freed + 1
        end
    end
    IX.guiCount = IX.guiCount - freed
    return freed
end

function IX.hookButton(inst)
    if not (inst:IsA("TextButton") or inst:IsA("ImageButton")) then return end
    if IX.btnConn[inst] or not Rec.active or IX.isOwnGui(inst) then return end
    if IX.guiCount >= IX.MAX_GUI then
        local t0 = os.clock()
        if t0 - IX.lastSweep < 5 then return end
        IX.lastSweep = t0
        IX.sweep()
        if IX.guiCount >= IX.MAX_GUI then
            if not IX.guiFullNoted then
                IX.guiFullNoted = true
                addEvent("error", {src = "system", note = "ถึงเพดานปุ่ม UI ที่ติดตามได้ (" .. IX.MAX_GUI .. ") ปุ่มที่เปิดทีหลังอาจไม่ถูกบันทึก"})
            end
            return
        end
    end
    IX.guiCount = IX.guiCount + 1
    IX.btnConn[inst] = inst.Activated:Connect(function() IX.guard(IX.onGui, inst) end)
end

function IX.hookGui()
    for _, d in ipairs(sg(function() return PlayerGui:GetDescendants() end, {})) do IX.hookButton(d) end
    rconn(PlayerGui.DescendantAdded, function(d) IX.guard(IX.hookButton, d) end)
end

function IX.dropAll()
    for _, c in pairs(IX.btnConn) do pcall(function() c:Disconnect() end) end
    IX.btnConn, IX.guiCount = {}, 0
end

-- เรียกตอน Rec.start (หลังตั้ง Rec.counts แล้ว) นับตามประเภทจากข้อมูลเดิมเมื่อบันทึกต่อ
function IX.reset()
    IX.dropAll()
    IX.toolSeen = setmetatable({}, {__mode = "k"})
    IX.holds = setmetatable({}, {__mode = "k"})
    IX.lastUse = setmetatable({}, {__mode = "k"})
    IX.toolCount, IX.guiFullNoted, IX.lastSweep, IX.errors = 0, false, 0, 0
    local bt = {}
    for _, e in ipairs(Rec.session and Rec.session.events or {}) do
        local k
        if e.kind == "interaction_abort" then
            k = "abort"
        elseif e.kind == "interaction" then
            k = e.type or (e.action == "click" and "click" or "prompt")
        end
        if k then bt[k] = (bt[k] or 0) + 1 end
    end
    Rec.counts.byType = bt
end

function IX.line()
    local bt = Rec.counts.byType or {}
    return string.format("โต้ตอบ: prompt %d | click %d | tool %d | ui %d | ปล่อยก่อนครบ %d",
        bt.prompt or 0, bt.click or 0, bt.tool or 0, bt.gui or 0, bt.abort or 0)
end

--------------------------------------------------------------------
-- NPC RECORDER (ส่วนที่ 4)
-- บันทึก NPC ที่ผู้เล่นเข้าใกล้ (near/leave) และ NPC ที่ผู้เล่นโต้ตอบเอง (interact ผ่าน Prompt/Click ที่ตรวจพบใน Interaction Recorder)
-- อ่านอย่างเดียว: ไม่คุย/ไม่กด/ไม่เดินเข้าหา NPC แทนผู้เล่น ไม่เรียก Remote
-- NPC = Model ที่มี Humanoid และไม่ใช่ตัวละครผู้เล่น (ตัดสินจากโครงสร้าง ไม่ใช่ข้อมูลที่เกมยืนยันว่าเป็น NPC)
-- ระยะ/ชื่อ/พิกัดคำนวณฝั่งไคลเอนต์ ใช้ตาราง NP เป็นที่เก็บ (ประกาศตัวแปรไว้ก่อน IX เพื่อให้ IX อ้างถึงได้)
--------------------------------------------------------------------
NP.cands = setmetatable({}, {__mode = "k"})
NP.inside = setmetatable({}, {__mode = "k"})
NP.nearCount = setmetatable({}, {__mode = "k"})
NP.count, NP.lastStep, NP.errors = 0, 0, 0
NP.RANGE, NP.LEAVE, NP.STEP, NP.MAX_NPC, NP.MAX_NEAR_PER_NPC = 30, 36, 1, 300, 20

function NP.isNpc(model)
    if not model or not model:IsA("Model") then return false end
    if Players:GetPlayerFromCharacter(model) then return false end
    return model:FindFirstChildOfClass("Humanoid") ~= nil
end

function NP.name(model)
    local hum = model:FindFirstChildOfClass("Humanoid")
    local dn = hum and hum.DisplayName or ""
    if dn == "" then dn = model.Name end
    return IX.label(dn)
end

-- หา NPC เจ้าของวัตถุ (Prompt/ClickDetector อยู่ใน Model ที่เป็น NPC) คืนชื่อ หรือ nil
function NP.of(inst)
    local cur = inst
    for _ = 1, 8 do
        if not cur or cur == Workspace then return nil end
        if cur:IsA("Model") and NP.isNpc(cur) then return NP.name(cur) end
        cur = cur.Parent
    end
    return nil
end

-- มีค่าหน่วง (hysteresis) กันเข้า-ออกสลับถี่ที่ขอบรัศมี
function NP.nextState(inside, dist)
    if inside then return dist <= NP.LEAVE end
    return dist <= NP.RANGE
end

function NP.emit(action, rec, key)
    rec.action = action
    local ok = addEvent("npc", rec, key)
    if ok then
        local bt = Rec.counts.byType
        if bt then
            bt.npc = (bt.npc or 0) + 1
            bt["npc_" .. action] = (bt["npc_" .. action] or 0) + 1
        end
    end
    return ok
end

function NP.interact(rec)
    if not (Rec.options.npc and rec.npc) then return end
    Rec.live.npc = Rec.live.npc + 1
    NP.emit("interact", {src = "game", name = rec.npc, via = rec.type, path = rec.path, pos = rec.pos, dist = rec.dist},
        "npci:" .. tostring(rec.path))
end

function NP.addHumanoid(h)
    if not h:IsA("Humanoid") then return end
    local model = h.Parent
    if not model or NP.cands[model] or not NP.isNpc(model) then return end
    if NP.count >= NP.MAX_NPC then
        local n = 0
        for _ in pairs(NP.cands) do n = n + 1 end
        NP.count = n
        if n >= NP.MAX_NPC then return end
    end
    NP.cands[model] = true
    NP.count = NP.count + 1
end

function NP.check(model, me)
    if not model:IsDescendantOf(Workspace) or Players:GetPlayerFromCharacter(model) then
        NP.cands[model], NP.inside[model] = nil, nil
        NP.count = math.max(0, NP.count - 1)
        return
    end
    local p = model:GetPivot().Position
    local d = math.sqrt((me[1] - p.X) ^ 2 + (me[2] - p.Y) ^ 2 + (me[3] - p.Z) ^ 2)
    local was = NP.inside[model] == true
    local isIn = NP.nextState(was, d)
    if isIn == was then return end
    NP.inside[model] = isIn or nil
    local pos = {IX.round(p.X), IX.round(p.Y), IX.round(p.Z)}
    if isIn then
        local n = (NP.nearCount[model] or 0) + 1
        NP.nearCount[model] = n
        if n > NP.MAX_NEAR_PER_NPC then return end
        Rec.live.npc = Rec.live.npc + 1
        NP.emit("near", {src = "game", name = NP.name(model), path = model:GetFullName(), pos = pos, dist = IX.round(d),
            hasPrompt = model:FindFirstChildWhichIsA("ProximityPrompt", true) ~= nil,
            hasClick = model:FindFirstChildWhichIsA("ClickDetector", true) ~= nil,
            hasDialog = model:FindFirstChildWhichIsA("Dialog", true) ~= nil}, "npcn:" .. model:GetFullName())
    else
        NP.emit("leave", {src = "game", name = NP.name(model), path = model:GetFullName(), pos = pos, dist = IX.round(d)},
            "npcl:" .. model:GetFullName())
    end
end

function NP.step()
    if not Rec.active or Rec.paused or not Rec.options.npc then return end
    local t0 = os.clock()
    if t0 - NP.lastStep < NP.STEP then return end
    NP.lastStep = t0
    local me = IX.myPos()
    if not me then return end
    for model in pairs(NP.cands) do
        if not pcall(NP.check, model, me) then NP.errors = NP.errors + 1 end
    end
end

function NP.hook()
    for _, d in ipairs(sg(function() return Workspace:GetDescendants() end, {})) do NP.addHumanoid(d) end
    rconn(Workspace.DescendantAdded, NP.addHumanoid)
    rconn(RunService.Heartbeat, NP.step)
end

function NP.reset()
    NP.cands = setmetatable({}, {__mode = "k"})
    NP.inside = setmetatable({}, {__mode = "k"})
    NP.nearCount = setmetatable({}, {__mode = "k"})
    NP.count, NP.lastStep, NP.errors = 0, 0, 0
    local bt = Rec.counts.byType
    if not bt then return end
    for _, e in ipairs(Rec.session and Rec.session.events or {}) do
        if e.kind == "npc" and type(e.action) == "string" then
            bt.npc = (bt.npc or 0) + 1
            bt["npc_" .. e.action] = (bt["npc_" .. e.action] or 0) + 1
        end
    end
end

function NP.line()
    local bt = Rec.counts.byType or {}
    local n = 0
    for _ in pairs(NP.cands) do n = n + 1 end
    return string.format("NPC: เข้าใกล้ %d | โต้ตอบ %d | กำลังติดตาม %d ตัว", bt.npc_near or 0, bt.npc_interact or 0, n)
end

local function hookHumanoid(char)
    local hum = char:WaitForChild("Humanoid", 5)
    if not hum or not Rec.active then return end
    dropCharConns()
    task.spawn(IX.guard, IX.hookChar, char)
    local c1 = hum:GetPropertyChangedSignal("SeatPart"):Connect(function()
        if not Rec.active then return end
        local seat = hum.SeatPart
        if seat then
            Rec.live.seat = Rec.live.seat + 1
            if Rec.options.vehicle then
                addEvent("vehicle", {action = "enter", seat = seat:GetFullName(), class = seat.ClassName, pos = instPos(seat)}, "veh:" .. seat:GetFullName())
            end
        else
            if Rec.options.vehicle then addEvent("vehicle", {action = "exit"}, "veh-exit") end
        end
    end)
    local c2 = hum.Died:Connect(function()
        if not Rec.active then return end
        Rec.live.died = Rec.live.died + 1
        addEvent("error", {src = "game", note = "ตัวละครตาย"})
    end)
    Rec.charConns[#Rec.charConns + 1] = c1
    Rec.charConns[#Rec.charConns + 1] = c2
end

local function hookClick(det)
    if Rec.counts.clicks >= MAX_CLICKS or not det:IsA("ClickDetector") then return end
    Rec.counts.clicks = Rec.counts.clicks + 1
    local function fire(player, button)
        if player ~= LP or not Rec.active then return end
        Rec.live.click = Rec.live.click + 1
        IX.guard(IX.onClick, det, button)
    end
    rconn(det.MouseClick, function(player) fire(player, "left") end)
    rconn(det.RightMouseClick, function(player) fire(player, "right") end)
end

-- ผลที่เกมยืนยัน: ค่าใน leaderstats ของผู้เล่น (อ่านอย่างเดียว)
local function snapStats()
    local out = {}
    local ls = LP:FindFirstChild("leaderstats")
    if ls then
        for _, v in ipairs(ls:GetChildren()) do
            if v:IsA("IntValue") or v:IsA("NumberValue") then out[v.Name] = v.Value end
        end
    end
    return out
end

local function hookStats()
    local ls = LP:FindFirstChild("leaderstats")
    if not ls then return end
    for _, v in ipairs(ls:GetChildren()) do
        if v:IsA("IntValue") or v:IsA("NumberValue") then
            local last = v.Value
            local name = v.Name
            rconn(v.Changed, function(nv)
                local prev = last
                last = nv
                if not Rec.active or not Rec.options.result then return end
                Rec.statCount[name] = (Rec.statCount[name] or 0) + 1
                if Rec.statCount[name] > MAX_STAT_EVENTS then return end
                Rec.live.stat = Rec.live.stat + 1
                addEvent("result", {src = "game", stat = name, value = nv, delta = nv - prev})
            end)
        end
    end
end

function Rec.setOption(name, on)
    if Rec.options[name] == nil then return false, "ไม่มีประเภท " .. tostring(name) end
    Rec.options[name] = on and true or false
    if Rec.session then
        Rec.session.options[name] = Rec.options[name]
        if name == "aiLearning" then Rec.session.learn = Rec.options[name] end
    end
    return true
end

function Rec.start(profession, continueId)
    if Rec.active then return false, "กำลังบันทึกอยู่" end
    local s
    if continueId and continueId ~= "" then
        local d, why = Session.load(continueId)
        if not d then return false, "เปิด session เดิมไม่ได้: " .. tostring(why) end
        s = d
        s.recording = true
        s.path, s.events, s.missions = s.path or {}, s.events or {}, s.missions or {}
        if s.activeMission ~= nil then
            local okR, whyR = JB.recover(s)
            say(okR and "กู้ภารกิจที่ค้างจากรอบก่อนแล้ว (ผลไม่ทราบ ถูกตัดขาด)" or ("ภารกิจที่ค้างกู้ไม่ได้ ข้ามไป: " .. tostring(whyR or "ข้อมูลเสีย")), okR and "ok" or "warn")
        end
        Rec.offset = tonumber(s.duration) or 0
        if profession and profession ~= "" then s.profession = tostring(profession):sub(1, 60) end
    else
        local newId = Session.newId()
        if not newId then return false, "สร้างรหัส session ที่ไม่ซ้ำไม่ได้" end
        s = {
            schema = SCHEMA, id = newId, name = "", placeId = game.PlaceId, gameId = game.GameId,
            mapName = MM.db and MM.db.name or tostring(game.Name), player = LP.Name,
            startedAt = now(), endedAt = nil, profession = tostring(profession or ""):sub(1, 60),
            options = {}, path = {}, route = {}, events = {}, missions = {}, recording = true, duration = 0,
            version = M.version, counts = {}, sizeBytes = 0, learn = Rec.options.aiLearning,
        }
        s.name = s.profession ~= "" and (s.profession .. " " .. s.id) or s.id
        Rec.offset = 0
    end
    s.options = {}
    for k, v in pairs(Rec.options) do s.options[k] = v end
    s.learn = Rec.options.aiLearning
    Rec.session = s
    Rec.t0, Rec.lastSample, Rec.lastPos, Rec.lastRoutePos = os.clock(), 0, nil, nil
    Rec.pausedTotal, Rec.paused, Rec.pausedAt = 0, false, 0
    Rec.lastEvent, Rec.statCount = {}, {}
    local inter = 0
    for _, e in ipairs(s.events) do if e.kind == "interaction" then inter = inter + 1 end end
    Rec.counts = {points = #s.path, events = #s.events, clicks = 0, interactions = inter, duplicatesSkipped = 0}
    Rec.live = {prompt = 0, click = 0, seat = 0, move = 0, died = 0, stat = 0, gui = 0, tool = 0, hold = 0, npc = 0}
    IX.reset()
    NP.reset()
    Rec.mission = nil
    Rec.active = true
    if LP.Character then task.spawn(hookHumanoid, LP.Character) end
    rconn(LP.CharacterAdded, function(ch) task.spawn(hookHumanoid, ch) end)
    rconn(RunService.Heartbeat, sampleMovement)
    rconn(PPS.PromptTriggered, function(prompt, player)
        if player ~= LP or not Rec.active then return end
        Rec.live.prompt = Rec.live.prompt + 1
        IX.guard(IX.onPrompt, prompt)
    end)
    IX.hookPrompts()
    for _, d in ipairs(sg(function() return Workspace:GetDescendants() end, {})) do hookClick(d) end
    rconn(Workspace.DescendantAdded, hookClick)
    hookStats()
    IX.hookGui()
    NP.hook()
    addEvent("system", {note = (continueId and continueId ~= "" and "บันทึกต่อจาก session เดิม" or "เริ่มบันทึก") .. " อาชีพ: " .. s.profession})
    Rec.autoToken = Rec.autoToken + 1
    local token = Rec.autoToken
    -- เซฟทันที ไม่รอ Autosave รอบแรก ถ้าเซฟไม่ได้ยังบันทึกต่อในหน่วยความจำ และคืนคำเตือนให้ผู้เรียก
    local saved, saveWhy = Rec.save(false)
    local warning = nil
    if not saved then
        warning = "เริ่มบันทึกแล้ว แต่เซฟครั้งแรกไม่สำเร็จ: " .. tostring(saveWhy)
        say(warning, "err")
    end
    task.spawn(function()
        while Rec.active and Rec.autoToken == token do
            task.wait(AUTOSAVE_EVERY)
            if Rec.active and Rec.autoToken == token and not Rec.paused then Rec.save(true) end
        end
    end)
    return true, warning
end

function Rec.pause()
    if not Rec.active then return false, "ยังไม่ได้เริ่มบันทึก" end
    if Rec.paused then return false, "หยุดชั่วคราวอยู่แล้ว" end
    addEvent("system", {note = "หยุดชั่วคราว"})
    Rec.paused, Rec.pausedAt = true, os.clock()
    return true
end

function Rec.resume()
    if not Rec.active then return false, "ยังไม่ได้เริ่มบันทึก" end
    if not Rec.paused then return false, "ไม่ได้หยุดชั่วคราวอยู่" end
    Rec.pausedTotal = Rec.pausedTotal + (os.clock() - Rec.pausedAt)
    Rec.paused = false
    addEvent("system", {note = "กลับมาบันทึกต่อ"})
    return true
end

function Rec.setName(name)
    if not Rec.session then return false, "ไม่มี session" end
    Rec.session.name = tostring(name or ""):sub(1, 80)
    return true
end

function Rec.setProfession(p)
    if not Rec.session then return false, "ไม่มี session" end
    Rec.session.profession = tostring(p or ""):sub(1, 60)
    return true
end

function Rec.startMission(name)
    if not Rec.active then return false, "ยังไม่ได้เริ่มบันทึก" end
    if not Rec.options.job then return false, "Job Recorder ปิดอยู่" end
    if Rec.mission then return false, "มีภารกิจที่ยังไม่จบอยู่: " .. Rec.mission.name end
    local nm = tostring(name or "")
    if nm == "" then nm = "ภารกิจ " .. (#Rec.session.missions + 1) end
    Rec.mission = {name = nm, startT = elapsed(), steps = {}, profession = Rec.session.profession,
        statsStart = Rec.options.result and snapStats() or nil, marks = {}, notes = {}, startPos = IX.myPos()}
    addEvent("mission", {action = "start", name = Rec.mission.name})
    return true
end

-- ผลสำเร็จ/ล้มเหลวมาจากผู้เล่นเท่านั้น (src = player) ส่วน statsDelta มาจากเกม (src = game)
function Rec.endMission(result, note, opts)
    if not Rec.mission then return false, "ไม่มีภารกิจที่กำลังบันทึก" end
    local m = Rec.mission
    m.endT = elapsed()
    m.duration = math.floor((m.endT - m.startT) * 100 + 0.5) / 100
    if Rec.options.result then
        m.result = (result == "success" or result == "fail") and result or "unknown"
        if m.statsStart then
            local delta, any = {}, false
            for k, v in pairs(snapStats()) do
                local before = m.statsStart[k]
                if before ~= nil and v ~= before then delta[k] = v - before any = true end
            end
            if any then m.statsDelta = delta end
        end
    else
        m.result = "unknown"
    end
    m.statsStart = nil
    m.resultSource = "player"
    m.note = tostring(note or "")
    m.interrupted = (type(opts) == "table" and opts.interrupted) and true or nil
    m.endPos = IX.myPos()
    JB.finalize(m, Rec.session)
    Rec.session.activeMission = nil
    Rec.session.missions[#Rec.session.missions + 1] = m
    addEvent("mission", {action = "end", result = m.result, note = m.note})
    Rec.mission = nil
    return true
end

-- ================== JOB RECORDER v2 (ส่วนที่ 5) ==================
-- ต่อยอดจาก Rec.startMission/endMission เดิม: steps ยังมาจาก interaction เหมือนเดิม (Farm Plan/ลายเซ็นไม่เปลี่ยน)
-- เพิ่มข้อมูลแยกจาก steps เพื่อไม่ปนกัน:
--   marks[]  = เหตุการณ์ที่ตรวจจับได้ระหว่างภารกิจ (vehicle/result/error/npc = เกมยืนยัน, interaction_abort = คำนวณฝั่งไคลเอนต์)
--   notes[]  = ข้อความที่ผู้เล่นจดเอง (src = player) ไม่เข้า steps/ลายเซ็น
--   summary  = สรุปต่อภารกิจ (คำนวณจากข้อมูลดิบด้านบน วิเคราะห์ใหม่ทุกครั้งจึงไม่เชื่อค่าที่เก็บไว้)
-- ไม่เรียก Remote ไม่กดปุ่ม ไม่เดิน ไม่สร้างผลภารกิจเอง: ผลสำเร็จ/ล้มเหลวยังมาจากผู้เล่นกดเท่านั้น
function JB.round2(x) return math.floor(x * 100 + 0.5) / 100 end

-- ประเภทของ step (ข้อมูลเก่าไม่มี type ให้อนุมานจาก action แบบเดียวกับ Analyzer)
function JB.stepType(st)
    if type(st.type) == "string" then return st.type end
    local a = tostring(st.action or "")
    if a == "ui_click" then return "gui" end
    if string.sub(a, 1, 5) == "tool_" then return "tool" end
    if a == "click" or a == "rightclick" then return "click" end
    return "prompt"
end

-- เรียกจาก addEvent เท่านั้น (ผ่านด่าน pause/เพดาน/ซ้ำ ของ addEvent มาแล้ว) rec.t ถูกใส่แล้ว
function JB.mark(kind, rec)
    local m = Rec.mission
    if not m then return false end
    m.marks = m.marks or {}
    if #m.marks >= JB.MARK_CAP then
        m.marksDropped = (m.marksDropped or 0) + 1
        return false
    end
    local mk = {t = rec.t, kind = kind}
    if kind == "vehicle" then
        mk.action, mk.class, mk.pos = rec.action, rec.class, rec.pos
    elseif kind == "result" then
        mk.stat, mk.value, mk.delta = rec.stat, rec.value, rec.delta
    elseif kind == "error" then
        mk.src, mk.note = rec.src, rec.note
    elseif kind == "npc" then
        mk.action, mk.name, mk.pos = rec.action, rec.name, rec.pos
    elseif kind == "interaction_abort" then
        mk.action, mk.object, mk.calc = rec.action, rec.object, true
    end
    m.marks[#m.marks + 1] = mk
    return true
end

-- สรุปต่อภารกิจ (ฟังก์ชันล้วน ไม่แก้ m) s = session (ใช้ path คำนวณระยะเดิน)
function JB.summarize(m, s)
    local sum = {stepCount = #(m.steps or {}), byType = {}, vehicleEnter = 0, deaths = 0, playerErrors = 0,
        aborts = 0, statChanges = 0, npcs = {}, noteCount = #(m.notes or {})}
    for _, st in ipairs(m.steps or {}) do
        local k = JB.stepType(st)
        sum.byType[k] = (sum.byType[k] or 0) + 1
    end
    local seen, nn = {}, 0
    for _, mk in ipairs(m.marks or {}) do
        local k = mk.kind
        if k == "vehicle" then
            if mk.action == "enter" then sum.vehicleEnter = sum.vehicleEnter + 1 end
        elseif k == "error" then
            if mk.src == "game" then sum.deaths = sum.deaths + 1 else sum.playerErrors = sum.playerErrors + 1 end
        elseif k == "interaction_abort" then
            sum.aborts = sum.aborts + 1
        elseif k == "result" then
            sum.statChanges = sum.statChanges + 1
        elseif k == "npc" and type(mk.name) == "string" and not seen[mk.name] and nn < 20 then
            seen[mk.name] = true
            nn = nn + 1
            sum.npcs[nn] = mk.name
        end
    end
    local pts = s and s.path
    if type(pts) == "table" and type(m.startT) == "number" and type(m.endT) == "number" then
        local dist, prev, cnt = 0, nil, 0
        for i = #pts, 1, -1 do -- path เรียงตามเวลา: ไล่จากท้ายจนเลยเวลาเริ่มภารกิจ
            local p = pts[i]
            if type(p) ~= "table" or type(p.t) ~= "number" or p.t < m.startT then break end
            if p.t <= m.endT and type(p.x) == "number" and type(p.z) == "number" then
                if prev then dist = dist + math.sqrt((p.x - prev.x) ^ 2 + (p.z - prev.z) ^ 2) end
                prev = p
                cnt = cnt + 1
            end
        end
        if cnt >= 2 then sum.distance = math.floor(dist + 0.5) end -- ไม่มีข้อมูลเส้นทางพอ = nil (ไม่เดาเป็น 0)
    end
    return sum
end

function JB.finalize(m, s)
    local ok, sum = pcall(JB.summarize, m, s)
    if ok then m.summary = sum end
end

-- ภารกิจที่ยังไม่จบ เก็บลง session ทุกครั้งที่ Save/Autosave (Rec.save)
function JB.snapshot()
    local m = Rec.mission
    if not m then return nil end
    local c = {}
    for k, v in pairs(m) do c[k] = v end
    c.open = true
    return c
end

-- ตรวจความเสียหายของภารกิจ (ข้อมูลเก่าไม่มี marks/notes/summary ผ่านได้) คืนข้อความปัญหา หรือ nil
function JB.validateMission(m, i)
    local tag = "ภารกิจลำดับที่ " .. tostring(i)
    if type(m) ~= "table" then return tag .. " ข้อมูลเสียหาย" end
    local function num(v) return type(v) == "number" and v == v end
    if m.startT ~= nil and not num(m.startT) then return tag .. " เวลาเริ่มไม่ถูกต้อง" end
    if m.endT ~= nil and not num(m.endT) then return tag .. " เวลาจบไม่ถูกต้อง" end
    if num(m.startT) and num(m.endT) and m.endT < m.startT then return tag .. " เวลาจบก่อนเวลาเริ่ม" end
    for _, field in ipairs({"steps", "marks", "notes"}) do
        local list = m[field]
        if list ~= nil then
            if type(list) ~= "table" then return tag .. " ฟิลด์ " .. field .. " ไม่ใช่รายการ" end
            for j, it in ipairs(list) do
                if type(it) ~= "table" then return tag .. " " .. field .. " รายการที่ " .. j .. " ข้อมูลเสียหาย" end
                if field == "steps" then
                    if it.t ~= nil and not num(it.t) then return tag .. " steps รายการที่ " .. j .. " เวลาไม่ถูกต้อง" end
                    if it.pos ~= nil and (type(it.pos) ~= "table" or not num(it.pos[1]) or not num(it.pos[3])) then
                        return tag .. " steps รายการที่ " .. j .. " พิกัดไม่ถูกต้อง"
                    end
                elseif not num(it.t) then
                    return tag .. " " .. field .. " รายการที่ " .. j .. " ไม่มีเวลาที่ถูกต้อง"
                end
            end
        end
    end
    return nil
end

-- กู้ภารกิจที่ค้างจากรอบก่อน (เกมปิดกลางคัน) เมื่อบันทึกต่อจาก session เดิม
-- ไม่เดาผล: result = unknown, ติดธง interrupted (ไม่ใช้สร้าง Farm Plan) เวลาจบ = เวลาของ autosave ล่าสุด
function JB.recover(s)
    local m = s.activeMission
    s.activeMission = nil
    if type(m) ~= "table" then return false, "ข้อมูลภารกิจค้างไม่ใช่ตาราง" end
    if type(m.startT) ~= "number" or m.startT ~= m.startT then return false, "ภารกิจค้างไม่มีเวลาเริ่ม" end
    m.open, m.statsStart = nil, nil
    m.steps = type(m.steps) == "table" and m.steps or {}
    m.marks = type(m.marks) == "table" and m.marks or {}
    m.notes = type(m.notes) == "table" and m.notes or {}
    m.endT = math.max(m.startT, tonumber(s.duration) or m.startT)
    m.duration = JB.round2(m.endT - m.startT)
    m.result, m.resultSource, m.interrupted = "unknown", "system", true
    m.note = "ค้างจากปิดเกมกลางคัน (กู้คืนอัตโนมัติ) ผลไม่ทราบ"
    local bad = JB.validateMission(m, #s.missions + 1)
    if bad then return false, bad end
    JB.finalize(m, s)
    s.missions[#s.missions + 1] = m
    return true
end

-- โน้ตขั้นตอนที่ผู้เล่นจดเอง (สำหรับขั้นตอนที่สคริปต์ตรวจจับไม่ได้) เก็บแยกจาก steps
function Rec.noteStep(text)
    if not Rec.active then return false, "ยังไม่ได้เริ่มบันทึก" end
    if Rec.paused then return false, "หยุดชั่วคราวอยู่ กด Resume ก่อน" end
    if not Rec.options.job then return false, "Job Recorder ปิดอยู่" end
    local m = Rec.mission
    if not m then return false, "ยังไม่ได้เริ่มภารกิจ" end
    local txt = IX.label(text, JB.NOTE_LEN)
    if string.match(txt, "^%s*$") then return false, "ข้อความโน้ตว่าง" end
    m.notes = m.notes or {}
    if #m.notes >= JB.NOTE_CAP then return false, "โน้ตเต็มแล้ว (" .. JB.NOTE_CAP .. " รายการต่อภารกิจ)" end
    m.notes[#m.notes + 1] = {t = elapsed(), text = txt, src = "player", pos = IX.myPos()}
    addEvent("mission", {action = "note", name = m.name, note = txt})
    return true
end

-- ยกเลิกภารกิจที่เริ่มผิด: ไม่นับเป็นภารกิจ/ผล/Farm Plan (เหตุการณ์ดิบใน events ยังอยู่ครบ มีบรรทัด mission/cancel เป็นหลักฐาน)
function Rec.cancelMission(reason)
    if not Rec.active then return false, "ยังไม่ได้เริ่มบันทึก" end
    if Rec.paused then return false, "หยุดชั่วคราวอยู่ กด Resume ก่อน" end
    local m = Rec.mission
    if not m then return false, "ไม่มีภารกิจที่กำลังบันทึก" end
    Rec.mission = nil
    Rec.session.activeMission = nil
    addEvent("mission", {action = "cancel", name = m.name, steps = #(m.steps or {}), note = IX.label(reason or "", 80)})
    return true
end

function JB.line()
    local m = Rec.mission
    if not m then
        local n = Rec.session and #(Rec.session.missions or {}) or 0
        return "ภารกิจ: ไม่มีที่กำลังทำ | จบแล้วใน session นี้ " .. n .. " รายการ" .. (Rec.options.job and "" or " | Job Recorder ปิดอยู่")
    end
    return string.format("ภารกิจที่กำลังทำ: %s | %.1f วิ | ขั้นตอน %d | เหตุการณ์ประกอบ %d | โน้ต %d",
        tostring(m.name), elapsed() - (m.startT or 0), #(m.steps or {}), #(m.marks or {}), #(m.notes or {}))
end
M.jobText = JB.line
-- ================== จบ JOB RECORDER v2 (ส่วนที่ 5) ==================

function Rec.markError(note, corrected)
    if not Rec.active then return false, "ไม่ได้บันทึกอยู่" end
    addEvent("error", {src = "player", note = tostring(note or ""), corrected = corrected and tostring(corrected) or nil})
    return true
end

function Rec.save(auto)
    if not Rec.session then return false, "ไม่มี session" end
    local s = Rec.session
    s.counts = Rec.counts
    s.activeMission = JB.snapshot() -- ภารกิจที่ยังไม่จบ: เก็บไว้กู้ถ้าเกมปิดกลางคัน (จบแล้วเป็น nil)
    s.duration = elapsed()
    s.recording = Rec.active
    local ok, info, size = wjson(sessionPath(s.placeId, s.id), s)
    if ok then s.sizeBytes = size else Rec.lastError = tostring(info) end
    return ok, info
end

local function dropConns()
    for _, c in ipairs(Rec.conns) do pcall(function() c:Disconnect() end) end
    Rec.conns = {}
    dropCharConns()
    IX.dropAll()
end
M.dropConns = dropConns

function Rec.stop()
    if not Rec.active then return false, "ไม่ได้บันทึกอยู่" end
    if Rec.paused then Rec.resume() end
    if Rec.mission then Rec.endMission("unknown", "จบการบันทึกก่อนภารกิจเสร็จ", {interrupted = true}) end
    addEvent("system", {note = "หยุดบันทึก"})
    dropConns()
    Rec.active = false
    Rec.autoToken = Rec.autoToken + 1
    Rec.session.endedAt = now()
    local ok, info = Rec.save(false)
    if ok and Rec.options.aiAnalyzer then
        local okA, rep = pcall(Analyzer.analyzeAndSave, Rec.session)
        if okA then
            Rec.lastReport = rep
            M.lastReport = rep
        else
            Rec.lastError = tostring(rep)
        end
    end
    return ok, info
end

--------------------------------------------------------------------
-- AI ANALYZER: แยก "ยืนยัน (เกม)" / "ผู้เล่นป้อน" / "ยังไม่ยืนยัน (อนุมาน)" / "ข้อมูลขาด"
--------------------------------------------------------------------
local function missionSig(m)
    local parts = {}
    for _, s in ipairs(m.steps or {}) do parts[#parts + 1] = tostring(s.path or s.action) end
    return table.concat(parts, " > ")
end

local function d3(a, b)
    return math.sqrt((a[1] - b[1]) ^ 2 + (a[3] - b[3]) ^ 2)
end

-- JOB RECORDER v2: วิเคราะห์ภารกิจละเอียด (ต้องอยู่หลัง missionSig) คำนวณใหม่จากข้อมูลดิบทุกครั้ง
function JB.analyze(d, r)
    local jobs = {list = {}, byName = {}, order = {}, interrupted = 0, noSteps = 0}
    for i, m in ipairs(d.missions or {}) do
        local sm = JB.summarize(m, d)
        local e = {idx = i, name = tostring(m.name), duration = m.duration, result = m.result, sum = sm,
            interrupted = m.interrupted == true, notes = m.notes or {}, sig = m.interrupted and "" or missionSig(m)}
        jobs.list[#jobs.list + 1] = e
        local g = jobs.byName[e.name]
        if not g then
            g = {n = 0, ok = 0, fail = 0, unk = 0, durSum = 0, durN = 0, stepSum = 0, sigs = {}, nsig = 0}
            jobs.byName[e.name] = g
            jobs.order[#jobs.order + 1] = e.name
        end
        g.n = g.n + 1
        if m.result == "success" then g.ok = g.ok + 1 elseif m.result == "fail" then g.fail = g.fail + 1 else g.unk = g.unk + 1 end
        if type(m.duration) == "number" then g.durSum, g.durN = g.durSum + m.duration, g.durN + 1 end
        g.stepSum = g.stepSum + sm.stepCount
        if e.sig ~= "" and not g.sigs[e.sig] then
            g.sigs[e.sig] = true
            g.nsig = g.nsig + 1
        end
        if e.interrupted then
            jobs.interrupted = jobs.interrupted + 1
            r.missing[#r.missing + 1] = "ภารกิจ '" .. e.name .. "' ถูกตัดขาด (หยุดบันทึก/ปิดเกมก่อนจบ) ไม่ถูกนำไปสร้าง Farm Plan"
        elseif sm.stepCount == 0 then
            jobs.noSteps = jobs.noSteps + 1
            r.missing[#r.missing + 1] = "ภารกิจ '" .. e.name .. "' ไม่มีขั้นตอนที่ตรวจจับได้ (งานนี้อาจไม่ใช้ Prompt/Click/Tool/ปุ่ม UI หรือสวิตช์ย่อยปิดอยู่) ใช้ปุ่ม จดโน้ต ช่วยจดเองได้"
        end
        local parts = {}
        if sm.vehicleEnter > 0 then parts[#parts + 1] = "นั่งรถ " .. sm.vehicleEnter .. " ครั้ง" end
        if sm.deaths > 0 then parts[#parts + 1] = "ตัวละครตาย " .. sm.deaths .. " ครั้ง" end
        if sm.statChanges > 0 then parts[#parts + 1] = "ค่า leaderstats เปลี่ยน " .. sm.statChanges .. " ครั้ง" end
        if #parts > 0 then r.confirmed[#r.confirmed + 1] = "เกมยืนยัน: ในภารกิจ '" .. e.name .. "' " .. table.concat(parts, " | ") end
        if sm.aborts > 0 then
            r.inferred[#r.inferred + 1] = "ในภารกิจ '" .. e.name .. "' ปล่อยปุ่มก่อนครบเวลาถือ " .. sm.aborts .. " ครั้ง (คำนวณฝั่งไคลเอนต์)"
        end
        if sm.noteCount > 0 then
            r.playerEntered[#r.playerEntered + 1] = "โน้ตขั้นตอนในภารกิจ '" .. e.name .. "' " .. sm.noteCount .. " รายการ (ผู้เล่นจดเอง)"
        end
    end
    for _, name in ipairs(jobs.order) do
        local g = jobs.byName[name]
        if g.nsig > 1 then
            r.inferred[#r.inferred + 1] = string.format("ภารกิจชื่อ '%s' ทำ %d ครั้ง มีลำดับขั้นตอนต่างกัน %d แบบ (อาจเป็นคนละภารกิจหรือทำคนละวิธี ยังไม่ยืนยัน)", name, g.n, g.nsig)
        end
    end
    if type(d.activeMission) == "table" then
        r.missing[#r.missing + 1] = "มีภารกิจ '" .. tostring(d.activeMission.name) .. "' ที่ยังไม่จบตอนบันทึกล่าสุด (ยังไม่นับเป็นภารกิจ จะกู้เมื่อบันทึกต่อจาก session นี้)"
    end
    r.jobs = jobs
end

function JB.reportLines(r, L)
    local jobs = r.jobs
    if not jobs or #jobs.list == 0 then return end
    L[#L + 1] = "[รายละเอียดภารกิจ (Job Recorder v2)]"
    for _, e in ipairs(jobs.list) do
        local sm = e.sum
        local bt = sm.byType
        L[#L + 1] = string.format("- #%d %s: %s วิ | ขั้นตอน %d (prompt %d, click %d, tool %d, ui %d) | เดิน %s สตั๊ด | นั่งรถ %d | ตาย %d | ผล(ผู้เล่นป้อน) %s%s",
            e.idx, e.name, tostring(e.duration), sm.stepCount, bt.prompt or 0, bt.click or 0, bt.tool or 0, bt.gui or 0,
            sm.distance ~= nil and tostring(sm.distance) or "ไม่มีข้อมูล", sm.vehicleEnter, sm.deaths, tostring(e.result),
            e.interrupted and " | ถูกตัดขาด" or "")
        for k, n in ipairs(e.notes) do
            if k > 5 then
                L[#L + 1] = "    ... โน้ตเพิ่มเติมอีก " .. (#e.notes - 5) .. " รายการ"
                break
            end
            L[#L + 1] = string.format("    โน้ต t=%.1f (ผู้เล่นจด): %s", tonumber(n.t) or 0, tostring(n.text))
        end
    end
    L[#L + 1] = "[สรุปตามชื่อภารกิจ]"
    for _, name in ipairs(jobs.order) do
        local g = jobs.byName[name]
        L[#L + 1] = string.format("- %s: ทำ %d ครั้ง | สำเร็จ %d ล้มเหลว %d ไม่ทราบ %d (ผู้เล่นป้อน) | เวลาเฉลี่ย %s วิ | ขั้นตอนเฉลี่ย %.1f",
            name, g.n, g.ok, g.fail, g.unk, g.durN > 0 and string.format("%.1f", g.durSum / g.durN) or "-", g.stepSum / g.n)
    end
end

function Analyzer.analyze(d)
    local r = {confirmed = {}, playerEntered = {}, inferred = {}, missing = {}, sequence = {}, path = {}, results = {},
        gameResults = {}, errors = {game = 0, player = 0, system = 0}, steps = {}, legs = {}}
    local seq, byKey, byType, aborts = {}, {}, {}, 0
    local npcMet, npcInt = {}, {}
    local hasVehicle = false
    local lastPos
    for _, e in ipairs(d.events or {}) do
        if e.kind == "interaction" then
            seq[#seq + 1] = {t = e.t, action = e.action, object = e.object, pos = e.pos}
            local ty = e.type or (e.action == "click" and "click" or "prompt")
            byType[ty] = (byType[ty] or 0) + 1
            local key = tostring(e.action) .. " | " .. tostring(e.object)
            byKey[key] = (byKey[key] or 0) + 1
            if e.pos then
                if lastPos then r.legs[#r.legs + 1] = math.floor(d3(lastPos, e.pos) + 0.5) end
                lastPos = e.pos
            end
        elseif e.kind == "interaction_abort" then
            aborts = aborts + 1
        elseif e.kind == "npc" then
            local nm = tostring(e.name or "?")
            if e.action == "near" then npcMet[nm] = (npcMet[nm] or 0) + 1
            elseif e.action == "interact" then npcInt[nm] = (npcInt[nm] or 0) + 1 end
        elseif e.kind == "vehicle" then
            hasVehicle = true
        elseif e.kind == "result" and e.src == "game" then
            local g = r.gameResults[e.stat] or {changes = 0, net = 0}
            g.changes = g.changes + 1
            g.net = g.net + (tonumber(e.delta) or 0)
            r.gameResults[e.stat] = g
        elseif e.kind == "error" then
            local k = e.src == "game" and "game" or (e.src == "player" and "player" or "system")
            r.errors[k] = r.errors[k] + 1
        end
    end
    r.sequence = seq
    r.interactionCount = #seq
    r.byType, r.aborts = byType, aborts
    r.npc = {met = 0, interact = 0, names = {}}
    for k, n in pairs(byKey) do r.confirmed[#r.confirmed + 1] = "การโต้ตอบ " .. n .. " ครั้ง: " .. k end
    table.sort(r.confirmed)
    do
        local names, met, inter = {}, 0, 0
        for nm, n in pairs(npcMet) do met = met + 1 names[nm] = true end
        for nm, n in pairs(npcInt) do inter = inter + n names[nm] = true end
        local list = {}
        for nm in pairs(names) do list[#list + 1] = nm .. (npcInt[nm] and (" x" .. npcInt[nm]) or "") end
        table.sort(list)
        r.npc = {met = met, interact = inter, names = list}
        if #list > 0 then
            r.confirmed[#r.confirmed + 1] = "NPC ที่ตรวจพบ " .. #list .. " ตัว (เข้าใกล้ " .. met .. " ตัว | โต้ตอบ " .. inter .. " ครั้ง): " .. table.concat(list, ", ", 1, math.min(#list, 15))
        end
    end
    if #seq > 0 then
        r.confirmed[#r.confirmed + 1] = string.format("ประเภทการโต้ตอบที่ตรวจจับได้: prompt %d | click %d | tool %d | ui %d",
            byType.prompt or 0, byType.click or 0, byType.tool or 0, byType.gui or 0)
    end

    local pts = d.path or {}
    local dist, maxGap, minX, maxX, minZ, maxZ = 0, 0, math.huge, -math.huge, math.huge, -math.huge
    local idleGaps = 0
    for i, p in ipairs(pts) do
        minX, maxX = math.min(minX, p.x), math.max(maxX, p.x)
        minZ, maxZ = math.min(minZ, p.z), math.max(maxZ, p.z)
        if i > 1 then
            local q = pts[i - 1]
            dist = dist + math.sqrt((p.x - q.x) ^ 2 + (p.z - q.z) ^ 2)
            if type(p.t) == "number" and type(q.t) == "number" then
                local gap = p.t - q.t
                maxGap = math.max(maxGap, gap)
                if gap > 10 then idleGaps = idleGaps + 1 end
            end
        end
    end
    r.path = {points = #pts, distance = math.floor(dist + 0.5), maxGapSec = math.floor(maxGap * 10 + 0.5) / 10,
        idleGaps = idleGaps,
        box = #pts > 0 and {math.floor(maxX - minX + 0.5), math.floor(maxZ - minZ + 0.5)} or nil,
        avgSpeed = (d.duration or 0) > 0 and math.floor(dist / d.duration * 10 + 0.5) / 10 or nil}
    r.routePoints = #(d.route or {})

    local ok, fail, unk = 0, 0, 0
    for _, m in ipairs(d.missions or {}) do
        if m.result == "success" then ok = ok + 1 elseif m.result == "fail" then fail = fail + 1 else unk = unk + 1 end
        r.steps[#r.steps + 1] = {name = m.name, count = #(m.steps or {}), duration = m.duration, result = m.result,
            statsDelta = m.statsDelta, signature = missionSig(m)}
    end
    r.results = {success = ok, fail = fail, unknown = unk, total = #(d.missions or {})}

    -- ผู้เล่นป้อน
    r.playerEntered[#r.playerEntered + 1] = "อาชีพ: " .. ((d.profession or "") ~= "" and d.profession or "(ไม่ระบุ)")
    r.playerEntered[#r.playerEntered + 1] = "ผลภารกิจ: สำเร็จ " .. ok .. " | ล้มเหลว " .. fail .. " | ไม่ทราบ " .. unk
    if r.errors.player > 0 then r.playerEntered[#r.playerEntered + 1] = "ข้อผิดพลาดที่ผู้เล่นบันทึก " .. r.errors.player .. " รายการ" end

    -- ข้อมูลที่ขาด
    local opts = d.options or {}
    if #pts < 2 then r.missing[#r.missing + 1] = "ไม่มีเส้นทางการเดินเพียงพอ (ต้องมีอย่างน้อย 2 ตำแหน่ง)" end
    if opts.vehicle and not hasVehicle then
        r.missing[#r.missing + 1] = "เปิด Vehicle Recorder แต่ไม่มีเหตุการณ์การนั่งรถ (ถ้าไม่ได้ขับรอบนี้ถือเป็นปกติ)"
    end
    if opts.interaction and #seq == 0 then r.missing[#r.missing + 1] = "ไม่มีการกดปุ่มหรือคลิกที่บันทึกได้" end
    if opts.npc and #(r.npc.names or {}) == 0 then r.missing[#r.missing + 1] = "เปิด NPC Recorder แต่ไม่พบ NPC ในรัศมี " .. NP.RANGE .. " สตั๊ด (ถ้าแมพนี้ไม่มี NPC ถือเป็นปกติ)" end
    if opts.npc == false then r.missing[#r.missing + 1] = "NPC Recorder ปิดอยู่ตอนบันทึก จึงไม่มีข้อมูล NPC" end
    for _, k in ipairs({"ixPrompt", "ixClick", "ixTool", "ixGui"}) do
        if opts.interaction and opts[k] == false then r.missing[#r.missing + 1] = "สวิตช์ย่อย " .. k .. " ปิดอยู่ตอนบันทึก จึงไม่มีข้อมูลโต้ตอบประเภทนี้" end
    end
    if #(d.missions or {}) == 0 then r.missing[#r.missing + 1] = "ไม่มีภารกิจที่บันทึกจุดเริ่มและจบ" end
    if unk > 0 then r.missing[#r.missing + 1] = "ภารกิจ " .. unk .. " ครั้งไม่มีผลสำเร็จ/ล้มเหลวที่ผู้เล่นป้อน" end
    if (d.duration or 0) <= 0 then r.missing[#r.missing + 1] = "ไม่มีเวลาบันทึกที่ใช้งานได้" end
    for _, m in ipairs(d.missions or {}) do
        if not m.endT then r.missing[#r.missing + 1] = "ภารกิจ '" .. tostring(m.name) .. "' ไม่มีจุดจบ" end
    end
    if opts.result and next(r.gameResults) == nil then
        r.missing[#r.missing + 1] = "ไม่พบการเปลี่ยนค่าใน leaderstats จึงไม่มีผลลัพธ์ที่เกมยืนยัน (แมพอาจไม่มี leaderstats)"
    end
    if d.recording == true then r.missing[#r.missing + 1] = "session นี้ยังไม่ปิด (อาจค้างจากการปิดเกมกลางคัน)" end

    for stat, g in pairs(r.gameResults) do
        r.confirmed[#r.confirmed + 1] = string.format("เกมยืนยัน: ค่า %s เปลี่ยน %d ครั้ง สุทธิ %+d", tostring(stat), g.changes, g.net)
    end
    r.confirmed[#r.confirmed + 1] = "เกมยืนยัน: ตัวละครตาย " .. r.errors.game .. " ครั้ง"

    r.inferred[#r.inferred + 1] = "ผู้เล่นเป็น NPC หรือไม่ ตัดสินจากโครงสร้าง (Model ที่มี Humanoid ไม่ใช่ตัวละครผู้เล่น) ยังไม่ยืนยันกับเกม"
    r.inferred[#r.inferred + 1] = "ลำดับขั้นตอนเป็นลำดับเวลาที่เกิดจริง ยังไม่ยืนยันว่าเป็นลำดับที่เกมกำหนด"
    if aborts > 0 then
        r.inferred[#r.inferred + 1] = "ผู้เล่นปล่อยปุ่มก่อนครบเวลาถือ " .. aborts .. " ครั้ง (คำนวณฝั่งไคลเอนต์ ไม่ใช่ผลที่เกมยืนยัน)"
    end
    if r.results.total > 0 and ok + fail == 0 then
        r.inferred[#r.inferred + 1] = "ยังไม่มีผลที่ผู้เล่นป้อน จึงยังไม่ทราบอัตราสำเร็จ"
    end
    local okJ, errJ = pcall(JB.analyze, d, r) -- ส่วนที่ 5: พังแล้วรายงานเดิมต้องยังออก
    if not okJ then r.missing[#r.missing + 1] = "วิเคราะห์ภารกิจละเอียดไม่สำเร็จ: " .. tostring(errJ) end
    return r
end

local function reportText(d, r)
    local L = {}
    L[#L + 1] = "=== รายงาน Session: " .. tostring(d.name) .. " ==="
    L[#L + 1] = "PlaceId " .. tostring(d.placeId) .. " | อาชีพ " .. ((d.profession or "") ~= "" and d.profession or "(ไม่ระบุ)") .. " | เวลา " .. tostring(d.duration) .. " วินาที"
    L[#L + 1] = "[ยืนยัน: จากเหตุการณ์จริงที่บันทึก]"
    L[#L + 1] = "- การกดปุ่มและคลิก " .. r.interactionCount .. " ครั้ง"
    L[#L + 1] = "- เส้นทาง " .. r.path.points .. " ตำแหน่ง ระยะรวม " .. tostring(r.path.distance) .. " สตั๊ด ช่วงห่างสูงสุด " .. tostring(r.path.maxGapSec) .. " วินาที (หยุดนิ่งเกิน 10 วิ: " .. tostring(r.path.idleGaps) .. " ช่วง)"
    if r.path.box then L[#L + 1] = "- ขอบเขตการเดิน " .. r.path.box[1] .. " x " .. r.path.box[2] .. " สตั๊ด" end
    if r.path.avgSpeed then L[#L + 1] = "- ความเร็วเฉลี่ย " .. r.path.avgSpeed .. " สตั๊ดต่อวินาที" end
    for _, c in ipairs(r.confirmed) do L[#L + 1] = "- " .. c end
    L[#L + 1] = "[ผู้เล่นป้อนเอง: ไม่ใช่ผลที่เกมยืนยัน]"
    for _, t in ipairs(r.playerEntered) do L[#L + 1] = "- " .. t end
    L[#L + 1] = "[ขั้นตอนต่อภารกิจ]"
    if #r.steps == 0 then L[#L + 1] = "- ไม่มี" end
    for _, s in ipairs(r.steps) do
        L[#L + 1] = string.format("- %s: %d ขั้นตอน ใช้เวลา %s วิ ผล(ผู้เล่นป้อน) %s", tostring(s.name), s.count, tostring(s.duration), tostring(s.result))
    end
    pcall(JB.reportLines, r, L)
    if #r.legs > 0 then
        local parts = {}
        for i, v in ipairs(r.legs) do
            if i > 12 then break end
            parts[#parts + 1] = tostring(v)
        end
        L[#L + 1] = "- ระยะระหว่างจุดโต้ตอบที่ต่อเนื่อง (สตั๊ด): " .. table.concat(parts, ", ")
    end
    L[#L + 1] = "[ยังไม่ยืนยัน: การอนุมาน]"
    for _, t in ipairs(r.inferred) do L[#L + 1] = "- " .. t end
    L[#L + 1] = "[ข้อมูลที่ขาดหาย]"
    if #r.missing == 0 then L[#L + 1] = "- ไม่พบข้อมูลขาดหาย" end
    for _, t in ipairs(r.missing) do L[#L + 1] = "- " .. t end
    L[#L + 1] = "[ลำดับเหตุการณ์ (สูงสุด 30 รายการแรก)]"
    for i, s in ipairs(r.sequence) do
        if i > 30 then break end
        L[#L + 1] = string.format("%d) t=%.1f %s | %s", i, s.t or 0, tostring(s.action), tostring(s.object))
    end
    return table.concat(L, "\n")
end

function Analyzer.analyzeAndSave(d)
    local r = Analyzer.analyze(d)
    local text = reportText(d, r)
    local path = sessionDir(d.placeId) .. "/" .. tostring(d.id) .. "_report.txt"
    local ok = false
    if canW() and safeId(d.id) then
        mkdirs(sessionDir(d.placeId))
        ok = pcall(writefile, path, text)
    end
    return {ok = ok, path = path, text = text, data = r}
end

-- หาลำดับที่เห็นซ้ำ (ต้องมี session/ภารกิจสนับสนุนอย่างน้อย minSupport) — ไม่ผูกกับสวิตช์ Replay
local function findPlan(sessions, minSupport)
    minSupport = minSupport or 2
    local groups = {}
    for _, d in ipairs(sessions) do
        for _, m in ipairs(d.missions or {}) do
            local sig = m.interrupted and "" or missionSig(m) -- ภารกิจที่ถูกตัดขาดมีลำดับไม่ครบ ไม่ใช้สร้างแผน
            if sig ~= "" then
                local g = groups[sig]
                if not g then g = {n = 0, missions = {}, sessions = {}} groups[sig] = g end
                g.n = g.n + 1
                g.missions[#g.missions + 1] = m
                g.sessions[d.id] = true
            end
        end
    end
    local best, bestN = nil, 0
    for sig, g in pairs(groups) do if g.n > bestN then best, bestN = sig, g.n end end
    if not best or bestN < minSupport then
        return {ok = false, why = "ข้อมูลไม่พอ: ลำดับที่เห็นซ้ำได้สูงสุด " .. bestN .. " ครั้ง (ต้องการอย่างน้อย " .. minSupport .. ")"}
    end
    local g = groups[best]
    local steps = {}
    local first = g.missions[1].steps
    for i, s0 in ipairs(first) do
        local sx, sy, sz, np, gapSum, ng = 0, 0, 0, 0, 0, 0
        for _, m in ipairs(g.missions) do
            local st = m.steps[i]
            if st then
                if st.pos then sx, sy, sz, np = sx + st.pos[1], sy + st.pos[2], sz + st.pos[3], np + 1 end
                local prevT = i == 1 and m.startT or (m.steps[i - 1] and m.steps[i - 1].t)
                if type(st.t) == "number" and type(prevT) == "number" then gapSum, ng = gapSum + (st.t - prevT), ng + 1 end
            end
        end
        steps[i] = {order = i, action = s0.action, object = s0.object, path = s0.path,
            pos = np > 0 and {math.floor(sx / np + 0.5), math.floor(sy / np + 0.5), math.floor(sz / np + 0.5)} or nil,
            avgGapSec = ng > 0 and math.floor(gapSum / ng * 10 + 0.5) / 10 or nil}
    end
    local sids = {}
    for id in pairs(g.sessions) do sids[#sids + 1] = id end
    table.sort(sids)
    return {ok = true, supporters = bestN, steps = steps, signature = best, missions = g.missions, sessionIds = sids}
end

-- สร้าง Farm Plan จากข้อมูลจริงที่เห็นซ้ำเท่านั้น (ไม่ส่งเข้าเกม)
function Analyzer.farmPlan(sessions, minSupport)
    local plan = findPlan(sessions, minSupport)
    if not plan.ok then return plan end
    local ok, fail, durSum, durN = 0, 0, 0, 0
    local statSum, statN = {}, {}
    for _, m in ipairs(plan.missions) do
        if m.result == "success" then ok = ok + 1 elseif m.result == "fail" then fail = fail + 1 end
        if type(m.duration) == "number" then durSum, durN = durSum + m.duration, durN + 1 end
        for k, v in pairs(m.statsDelta or {}) do
            statSum[k] = (statSum[k] or 0) + v
            statN[k] = (statN[k] or 0) + 1
        end
    end
    local gain = {}
    for k, v in pairs(statSum) do gain[k] = math.floor(v / statN[k] * 100 + 0.5) / 100 end
    local fp = {
        ok = true, schema = SCHEMA, placeId = game.PlaceId, mapName = MM.db and MM.db.name or tostring(game.Name),
        generatedAt = now(), minSupport = minSupport or 2, supporters = plan.supporters, basedOnSessions = plan.sessionIds,
        steps = plan.steps, avgMissionSec = durN > 0 and math.floor(durSum / durN * 10 + 0.5) / 10 or nil,
        playerEntered = {success = ok, fail = fail, successRatePct = (ok + fail) > 0 and math.floor(ok / (ok + fail) * 100 + 0.5) or nil},
        gameConfirmed = {avgStatDeltaPerMission = gain, missionsWithStats = statN},
        executed = false,
        notes = {"แผนจากลำดับที่ผู้เล่นทำซ้ำจริง ยังไม่ได้ทดสอบกับเกม", "อัตราสำเร็จมาจากผู้เล่นป้อน ส่วน avgStatDelta มาจาก leaderstats ที่เกมแสดง",
            "แผนนี้ไม่ได้ถูกส่งเข้าเกม ใช้จำลองเท่านั้น"},
    }
    wjson(mapDir(game.PlaceId) .. "/farmplan.json", fp)
    return fp
end

-- รายงานความสอดคล้องของข้อมูลหลาย session ในแมพเดียวกัน
function Analyzer.consistency(sessions)
    local L = {}
    local n = #sessions
    L[#L + 1] = "=== รายงานความสอดคล้อง (แมพ " .. tostring(game.PlaceId) .. ") ==="
    L[#L + 1] = "จำนวน session ที่ใช้: " .. n
    if n == 0 then L[#L + 1] = "ไม่มีข้อมูล" return table.concat(L, "\n"), {n = 0} end
    local wrongMap, unclosed, noPos, total = 0, 0, 0, 0
    local sigCount, sigDur, objPos = {}, {}, {}
    local conflicts = {}
    local totalMissions = 0
    for _, d in ipairs(sessions) do
        if d.placeId ~= game.PlaceId then wrongMap = wrongMap + 1 end
        if d.recording == true then unclosed = unclosed + 1 end
        for _, e in ipairs(d.events or {}) do
            if e.kind == "interaction" then
                total = total + 1
                if not e.pos then
                    if e.type ~= "gui" and e.type ~= "tool" then noPos = noPos + 1 end
                else
                    local k = tostring(e.path)
                    objPos[k] = objPos[k] or {}
                    objPos[k][#objPos[k] + 1] = e.pos
                end
            end
        end
        for _, m in ipairs(d.missions or {}) do
            totalMissions = totalMissions + 1
            local sig = m.interrupted and "" or missionSig(m)
            if sig ~= "" then
                sigCount[sig] = (sigCount[sig] or 0) + 1
                sigDur[sig] = sigDur[sig] or {}
                if type(m.duration) == "number" then sigDur[sig][#sigDur[sig] + 1] = m.duration end
            end
            if m.result == "success" and m.statsDelta then
                local anyUp = false
                for _, v in pairs(m.statsDelta) do if v > 0 then anyUp = true end end
                if not anyUp then conflicts[#conflicts + 1] = "ภารกิจ '" .. tostring(m.name) .. "' (session " .. tostring(d.id) .. ") ผู้เล่นป้อนสำเร็จ แต่ค่าใน leaderstats ไม่เพิ่ม ควรตรวจสอบ" end
            elseif m.result == "fail" and m.statsDelta then
                local anyUp = false
                for _, v in pairs(m.statsDelta) do if v > 0 then anyUp = true end end
                if anyUp then conflicts[#conflicts + 1] = "ภารกิจ '" .. tostring(m.name) .. "' (session " .. tostring(d.id) .. ") ผู้เล่นป้อนล้มเหลว แต่ค่าใน leaderstats เพิ่ม ควรตรวจสอบ" end
            end
        end
    end
    L[#L + 1] = "ข้อมูลจากแมพอื่นที่ปนมา: " .. wrongMap .. (wrongMap == 0 and " (ปกติ)" or " (ผิดปกติ)")
    L[#L + 1] = "session ที่ยังไม่ปิด: " .. unclosed
    L[#L + 1] = string.format("การโต้ตอบทั้งหมด %d ครั้ง ไม่มีตำแหน่ง %d ครั้ง", total, noPos)
    local bestSig, bestN, distinct = nil, 0, 0
    for sig, c in pairs(sigCount) do
        distinct = distinct + 1
        if c > bestN then bestSig, bestN = sig, c end
    end
    local pct = totalMissions > 0 and math.floor(bestN / totalMissions * 100 + 0.5) or 0
    L[#L + 1] = string.format("ภารกิจทั้งหมด %d | ลำดับขั้นตอนที่ต่างกัน %d แบบ | แบบที่พบบ่อยสุดคิดเป็น %d%%", totalMissions, distinct, pct)
    if bestSig then
        local ds = sigDur[bestSig]
        if ds and #ds > 0 then
            local mn, mx, sum = math.huge, -math.huge, 0
            for _, v in ipairs(ds) do mn, mx, sum = math.min(mn, v), math.max(mx, v), sum + v end
            L[#L + 1] = string.format("เวลาภารกิจแบบที่พบบ่อย: เฉลี่ย %.1f วิ (ต่ำสุด %.1f สูงสุด %.1f)", sum / #ds, mn, mx)
        end
    end
    local worst, worstK = 0, nil
    for k, list in pairs(objPos) do
        for i = 2, #list do
            local dd = d3(list[1], list[i])
            if dd > worst then worst, worstK = dd, k end
        end
    end
    if worstK then L[#L + 1] = string.format("จุดโต้ตอบเดียวกันที่ตำแหน่งต่างกันมากสุด %.1f สตั๊ด (%s)", worst, tostring(worstK)) end
    for i, c in ipairs(conflicts) do
        if i > 8 then break end
        L[#L + 1] = "ข้อมูลขัดกัน: " .. c
    end
    if #conflicts == 0 then L[#L + 1] = "ไม่พบข้อมูลผู้เล่นป้อนที่ขัดกับค่าจากเกม (เท่าที่มี leaderstats)" end
    L[#L + 1] = "หมายเหตุ: ความสอดคล้องวัดจากข้อมูลที่บันทึกไว้ ไม่ได้ยืนยันว่าตรงกับกลไกของเกม"
    return table.concat(L, "\n"), {n = n, wrongMap = wrongMap, consistencyPct = pct, conflicts = #conflicts}
end

--------------------------------------------------------------------
-- MODE 2: AI REPLAY (จำลองเท่านั้น ไม่ส่งการกด/เดินเข้าเกม)
--------------------------------------------------------------------
Replay.execute = function() return false, "ปิดไว้: ยังไม่ตรวจกฎเกมและกลไกที่เกมอนุญาต (Replay เป็น Simulation เท่านั้น)" end

local function replayGate()
    if not Rec.options.aiReplay then return false, "AI Replay ปิดอยู่" end
    return true
end

function Replay.analyze(d)
    local r = Analyzer.analyze(d)
    return {id = d.id, profession = d.profession or "", pointCount = #(d.path or {}), distance = r.path.distance,
        steps = r.interactionCount, missions = d.missions or {}, notes = r.missing}
end

function Replay.plan(sessions, minSupport)
    local ok, why = replayGate()
    if not ok then return {ok = false, why = why} end
    return findPlan(sessions, minSupport)
end

function Replay.accuracy(sessions, plan)
    local ok, why = replayGate()
    if not ok then return {ok = false, why = why} end
    if not plan or not plan.ok then return {ok = false, why = plan and plan.why or "ไม่มีแผน"} end
    local matched, total, success, judged = 0, 0, 0, 0
    for _, d in ipairs(sessions) do
        for _, m in ipairs(d.missions or {}) do
            total = total + 1
            if missionSig(m) == plan.signature then matched = matched + 1 end
            if m.result == "success" then success = success + 1 end
            if m.result == "success" or m.result == "fail" then judged = judged + 1 end
        end
    end
    return {ok = true, matchedMissions = matched, totalMissions = total,
        consistencyPct = total > 0 and math.floor(matched / total * 100 + 0.5) or 0,
        successRatePct = judged > 0 and math.floor(success / judged * 100 + 0.5) or nil,
        judged = judged, note = "วัดจากบันทึกที่ผู้เล่นป้อนเอง ไม่ใช่ผลที่เกมยืนยัน"}
end

function Replay.simulate(plan)
    local ok, why = replayGate()
    if not ok then return {ok = false, why = why} end
    if not plan or not plan.ok then return {ok = false, why = plan and plan.why or "ไม่มีแผน"} end
    local steps, prev = {}, nil
    for i, s in ipairs(plan.steps or {}) do
        local dist
        if prev and s.pos then dist = math.floor(d3(prev, s.pos) + 0.5) end
        if s.pos then prev = s.pos end
        steps[i] = {order = i, action = s.action, object = s.object, path = s.path, pos = s.pos, distFromPrev = dist, avgGapSec = s.avgGapSec}
    end
    return {ok = true, executed = false, steps = steps, note = "จำลองเท่านั้น ไม่ได้ส่งการกดหรือการเดินเข้าเกม"}
end

Replay.export = Session.export
Replay.import = Session.import
function Replay.listSessions()
    local out = {}
    for _, s in ipairs((Session.list())) do out[#out + 1] = s.id end
    return out
end
Replay.load = Session.load

