    out[#out + 1] = result("ClickDetector", pcall(function() return Instance.new("ClickDetector").MouseClick end) and "API มี" or "ล้มเหลว", "ClickDetector.MouseClick")
    local hasMove = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart") ~= nil
    out[#out + 1] = result("Movement", hasMove and "API มี" or "ยังไม่มีตัวละคร", "HumanoidRootPart.Position")
