function Tests.saveLoad()
    if not canW() or not canR() then return result("Save / Load", "ทำไม่ได้", "ตัวรันไม่มี writefile/readfile") end
    local id = "_test_" .. tostring(math.random(100000, 999999))
    local probe = {id = id, placeId = game.PlaceId, path = {{t = 0, x = 1, y = 2, z = 3}}, events = {}, missions = {}, options = {}}
    local path = sessionPath(game.PlaceId, id)
    local ok, why = wjson(path, probe)
    local back = ok and rjson(path)
    local same = back and back.id == id and #back.path == 1 and back.path[1].x == 1
    if type(delfile) == "function" then pcall(delfile, path) end
    if not ok then return result("Save / Load", "ล้มเหลว", tostring(why)) end
    if not same then return result("Save / Load", "ล้มเหลว", "อ่านกลับแล้วไม่ตรง") end
    return result("Save / Load", "ผ่าน (ไฟล์ทดสอบ เขียน-อ่าน-ลบ)", "ยังไม่ได้ทดสอบกับ session จริงจนกว่าจะบันทึกหนึ่งรอบ")
end

function Tests.pauseResume()
