    local saved = {session = Rec.session, active = Rec.active, t0 = Rec.t0, offset = Rec.offset,
        pausedTotal = Rec.pausedTotal, paused = Rec.paused, pausedAt = Rec.pausedAt}
    Rec.session = {id = "_test_pause", events = {}, path = {}, options = {}, placeId = game.PlaceId}
