-- ทดสอบสวิตช์ว่าควบคุมค่าจริง แล้วคืนค่าเดิม
function Tests.switches()
    local bad = {}
    for _, def in ipairs(M.switchDefs) do
        local before = def.get()
        def.set(not before)
        local flipped = def.get() == (not before)
        def.set(before)
        if not flipped or def.get() ~= before then bad[#bad + 1] = def.id end
    end
    if #bad == 0 then return result("Switches", "ผ่าน (ตรรกะ) " .. #M.switchDefs .. " ตัว", "สลับค่าและคืนค่าได้ ผลจริงต่อ Scanner/Recorder ต้องดูตอนใช้งาน") end
    return result("Switches", "ล้มเหลว", table.concat(bad, ", "))
end

function Tests.interaction()
    if Rec.active then return result("Interaction Recorder", "ทดสอบข้ามไป", "กำลังบันทึกอยู่ ทดสอบหลังหยุดก่อน") end
    local bad = {}
    -- ข้อความ: ตัดตามตัวอักษร / ตัดอักขระควบคุม / กัน UTF-8 เสีย
    if utf8.len(IX.label(string.rep("ก", 100), 60)) ~= 60 then bad[#bad + 1] = "label ตัดข้อความไทยผิด" end
    if IX.label("a\nb\tc") ~= "a b c" then bad[#bad + 1] = "label ไม่ตัดอักขระควบคุม" end
    if IX.label(nil) ~= "" then bad[#bad + 1] = "label(nil)" end
    if utf8.len(IX.label("ab" .. string.char(255) .. "c")) == nil then bad[#bad + 1] = "label ยังมี UTF-8 เสีย" end
    -- ตัดสินปล่อยก่อนครบเวลาถือ
    if IX.isAbort(0.2, 1) ~= true or IX.isAbort(0.95, 1) ~= false or IX.isAbort(nil, 1) ~= false or IX.isAbort(1, 0) ~= false then
        bad[#bad + 1] = "isAbort"
    end
    -- เขียนเหตุการณ์ผ่าน session จำลอง แล้วคืนค่าเดิม
    local saved = {session = Rec.session, active = Rec.active, t0 = Rec.t0, offset = Rec.offset, pausedTotal = Rec.pausedTotal,
        paused = Rec.paused, pausedAt = Rec.pausedAt, counts = Rec.counts, lastEvent = Rec.lastEvent, mission = Rec.mission}
    Rec.session = {id = "_test_ix", events = {}, path = {}, options = {}, placeId = game.PlaceId}
    Rec.active, Rec.t0, Rec.offset, Rec.pausedTotal, Rec.paused, Rec.pausedAt = true, os.clock(), 0, 0, false, 0
    Rec.counts = {points = 0, events = 0, clicks = 0, interactions = 0, duplicatesSkipped = 0, byType = {}}
    Rec.lastEvent, Rec.mission = {}, nil
    local o1 = IX.emit("interaction", {type = "gui", action = "ui_click", object = "x", path = "p1"}, "k1")
    local o2 = IX.emit("interaction", {type = "gui", action = "ui_click", object = "x", path = "p1"}, "k1")
    local o3 = IX.emit("interaction_abort", {type = "prompt", action = "a", object = "b", path = "p2"}, "k2")
    Rec.paused = true
    local o4 = IX.emit("interaction", {type = "tool", action = "tool_use", object = "t", path = "Tool:t"}, "k3")
    Rec.paused = false
    local evs, bt, ci = Rec.session.events, Rec.counts.byType, Rec.counts.interactions
    local okGood = validateSession({id = "x", placeId = game.PlaceId, path = {}, events = evs}, game.PlaceId)
    local okBadT = validateSession({id = "x", placeId = game.PlaceId, path = {}, events = {{kind = "interaction", action = "a"}}}, game.PlaceId)
    local okBadK = validateSession({id = "x", placeId = game.PlaceId, path = {}, events = {{t = 1}}}, game.PlaceId)
    local okBadP = validateSession({id = "x", placeId = game.PlaceId, path = {}, events = {{kind = "interaction", t = 1, pos = {"a", 0, 0}}}}, game.PlaceId)
    Rec.session, Rec.active, Rec.t0, Rec.offset = saved.session, saved.active, saved.t0, saved.offset
    Rec.pausedTotal, Rec.paused, Rec.pausedAt = saved.pausedTotal, saved.paused, saved.pausedAt
    Rec.counts, Rec.lastEvent, Rec.mission = saved.counts, saved.lastEvent, saved.mission
    if not (o1 == true and o2 == false and o3 == true and o4 == false) then bad[#bad + 1] = "emit (ซ้ำ/pause)" end
    if #evs ~= 2 or bt.gui ~= 1 or bt.abort ~= 1 or ci ~= 1 then bad[#bad + 1] = "นับตามประเภทผิด" end
    if okGood ~= true then bad[#bad + 1] = "validate ปฏิเสธข้อมูลปกติ" end
    if okBadT ~= false or okBadK ~= false or okBadP ~= false then bad[#bad + 1] = "validate ไม่จับเหตุการณ์เสียหาย" end
    if #bad == 0 then
        return result("Interaction Recorder", "ผ่าน (ตรรกะ)", "ทดสอบการตัดข้อความ/ซ้ำ/pause/นับประเภท/ตรวจข้อมูลเสียหาย ยังไม่ได้ทดสอบกับ Prompt/Click/Tool/UI จริง")
    end
    return result("Interaction Recorder", "ล้มเหลว", table.concat(bad, ", "))
end

