    Rec.counts, Rec.lastEvent, Rec.mission, Rec.options.npc, Rec.live.npc = saved.counts, saved.lastEvent, saved.mission, saved.npc, saved.live
    if not (o1 == true and o2 == false and o4 == false) then bad[#bad + 1] = "emit (ซ้ำ/pause)" end
    if #evs ~= 2 or bt.npc ~= 2 or bt.npc_near ~= 1 or bt.npc_interact ~= 1 then bad[#bad + 1] = "นับเหตุการณ์ NPC ผิด/สวิตช์ npc ไม่มีผล" end
    if okGood ~= true then bad[#bad + 1] = "validate ปฏิเสธข้อมูลปกติ" end
    if okBad ~= false then bad[#bad + 1] = "validate ไม่จับ npc ที่ไม่มีเวลา" end
    if #bad == 0 then
        return result("NPC Recorder", "ผ่าน (ตรรกะ)", "ทดสอบ hysteresis/ซ้ำ/pause/สวิตช์/นับ/ตรวจข้อมูลเสียหาย ยังไม่ได้ทดสอบกับ NPC จริง")
    end
    return result("NPC Recorder", "ล้มเหลว", table.concat(bad, ", "))
end

function Tests.job()
    if Rec.active then return result("Job Recorder v2", "ทดสอบข้ามไป", "กำลังบันทึกอยู่ ทดสอบหลังหยุดก่อน") end
    local bad = {}
    local function chk(cond, why) if not cond then bad[#bad + 1] = why end end
    local saved = {session = Rec.session, active = Rec.active, t0 = Rec.t0, offset = Rec.offset, pausedTotal = Rec.pausedTotal,
        paused = Rec.paused, pausedAt = Rec.pausedAt, counts = Rec.counts, lastEvent = Rec.lastEvent, mission = Rec.mission,
        job = Rec.options.job, result = Rec.options.result}
    Rec.session = {id = "_test_job", events = {}, path = {}, options = {}, missions = {}, placeId = game.PlaceId, profession = ""}
    Rec.active, Rec.t0, Rec.offset, Rec.pausedTotal, Rec.paused, Rec.pausedAt = true, os.clock(), 0, 0, false, 0
    Rec.counts = {points = 0, events = 0, clicks = 0, interactions = 0, duplicatesSkipped = 0, byType = {}}
    Rec.lastEvent, Rec.mission, Rec.options.job, Rec.options.result = {}, nil, true, false
    local okP, errP = pcall(function()
        chk(select(1, Rec.noteStep("x")) == false, "noteStep ตอนไม่มีภารกิจต้องถูกปฏิเสธ")
        chk(Rec.startMission("T1") == true, "startMission")
        addEvent("interaction", {type = "prompt", action = "a", object = "o", path = "p1", pos = {1, 2, 3}})
        addEvent("vehicle", {action = "enter", class = "VehicleSeat", pos = {1, 2, 3}})
        addEvent("error", {src = "game", note = "ตัวละครตาย"})
        addEvent("result", {src = "game", stat = "Cash", value = 5, delta = 5})
        addEvent("interaction_abort", {type = "prompt", action = "a", object = "o"})
        addEvent("npc", {src = "game", action = "near", name = "N", path = "np", pos = {1, 2, 3}})
        chk(Rec.noteStep("ส่งของที่ร้าน") == true, "noteStep ปกติ")
        chk(select(1, Rec.noteStep("   ")) == false, "noteStep ข้อความว่างต้องถูกปฏิเสธ")
        Rec.paused = true
        chk(select(1, Rec.noteStep("pause")) == false, "noteStep ตอน pause ต้องถูกปฏิเสธ")
        chk(select(1, Rec.cancelMission("x")) == false, "cancelMission ตอน pause ต้องถูกปฏิเสธ")
        Rec.paused = false
        local m = Rec.mission
        chk(m and #m.steps == 1 and m.steps[1].type == "prompt", "step ต้องมี type และไม่ปนกับ marks")
        chk(m and #m.marks == 5, "marks ต้องมี 5 (vehicle/error/result/abort/npc)")
        chk(m and #m.notes == 1 and m.notes[1].src == "player", "notes เก็บแยกและติด src=player")
        chk(Rec.endMission("success", "") == true, "endMission")
        local done = Rec.session.missions[1]
        local sm = done and done.summary
        chk(sm and sm.stepCount == 1 and sm.vehicleEnter == 1 and sm.deaths == 1 and sm.aborts == 1 and sm.statChanges == 1, "summary นับผิด")
        chk(sm and sm.npcs[1] == "N" and sm.noteCount == 1, "summary npc/note ผิด")
        chk(Rec.session.activeMission == nil and Rec.mission == nil, "จบภารกิจแล้วต้องเคลียร์ activeMission")
        chk(Rec.startMission("T2") == true, "startMission T2")
        local snap = JB.snapshot()
        chk(snap and snap.open == true and snap.name == "T2", "snapshot ภารกิจที่ยังเปิด")
        chk(Rec.cancelMission("test") == true and Rec.mission == nil and #Rec.session.missions == 1, "cancelMission ต้องไม่นับเป็นภารกิจ")
        local last = Rec.session.events[#Rec.session.events]
        chk(last and last.kind == "mission" and last.action == "cancel", "cancelMission ต้องมีบรรทัดหลักฐานใน events")
        Rec.options.job = false
        chk(select(1, Rec.startMission("off")) == false, "ปิด Job Recorder แล้ว startMission ต้องถูกปฏิเสธ")
        Rec.options.job = true
        -- ระยะเดิน: (0,0)->(3,4) = 5 จุดนอกช่วงเวลาไม่นับ
        local dsum = JB.summarize({startT = 0, endT = 10, steps = {}, marks = {}, notes = {}},
            {path = {{t = 0, x = 0, z = 0}, {t = 5, x = 3, z = 4}, {t = 20, x = 100, z = 100}}})
        chk(dsum.distance == 5, "ระยะเดินในภารกิจคำนวณผิด")
        chk(JB.summarize({startT = 0, endT = 10}, {path = {}}).distance == nil, "ไม่มีเส้นทางต้องเป็น nil ไม่ใช่ 0")
        -- กู้ภารกิจที่ค้าง
        local s = {missions = {}, duration = 12, activeMission = {name = "T3", startT = 5, steps = {}, marks = {}, notes = {}, open = true}}
        chk(JB.recover(s) == true and s.activeMission == nil, "recover ภารกิจที่ค้าง")
        local rm = s.missions[1]
        chk(rm and rm.interrupted == true and rm.result == "unknown" and rm.endT == 12 and rm.duration == 7, "ภารกิจที่กู้ต้องเป็น unknown + interrupted")
        chk(select(1, JB.recover({missions = {}, activeMission = {name = "x", startT = "a"}})) == false, "recover ข้อมูลเสียต้องถูกปฏิเสธ")
        -- ตรวจความเสียหาย
        local pid = game.PlaceId
        chk(validateSession({id = "x", placeId = pid, path = {}, events = {}, missions = {Rec.session.missions[1]}}, pid) == true, "validate ภารกิจปกติ")
        chk(validateSession({id = "x", placeId = pid, path = {}, events = {}, missions = {{result = "success", steps = {{t = 1, action = "a"}}}}}, pid) == true, "validate ภารกิจรุ่นเก่า (ไม่มี marks/notes)")
        chk(validateSession({id = "x", placeId = pid, path = {}, events = {}, missions = {{result = "unknown", startT = 5, endT = 1}}}, pid) == false, "validate ต้องจับเวลาจบก่อนเริ่ม")
        chk(validateSession({id = "x", placeId = pid, path = {}, events = {}, missions = {{result = "unknown", marks = {{kind = "vehicle"}}}}}, pid) == false, "validate ต้องจับ marks ที่ไม่มีเวลา")
        chk(validateSession({id = "x", placeId = pid, path = {}, events = {}, missions = {"bad"}}, pid) == false, "validate ต้องจับภารกิจที่ไม่ใช่ตาราง")
        -- ภารกิจถูกตัดขาดไม่เข้า Farm Plan
        local mkMission = function(intr) return {name = "x", startT = 0, interrupted = intr, steps = {{action = "a", path = "p", t = 1}}} end
        chk(findPlan({{id = "s1", missions = {mkMission(true)}}}, 1).ok == false, "ภารกิจ interrupted ต้องไม่เข้าแผน")
        chk(findPlan({{id = "s1", missions = {mkMission(nil)}}}, 1).ok == true, "ภารกิจปกติต้องเข้าแผนได้ (พฤติกรรมเดิม)")
        -- รายงาน
        local rep = Analyzer.analyze({placeId = pid, duration = 20, path = {}, events = {}, options = {job = true},
            missions = {Rec.session.missions[1], rm}, activeMission = {name = "open"}})
        chk(rep.jobs and #rep.jobs.list == 2 and rep.jobs.interrupted == 1, "analyzer ต้องแยกภารกิจที่ถูกตัดขาด")
        local L = {}
        JB.reportLines(rep, L)
        chk(#L > 3, "reportLines ต้องมีเนื้อหา")
    end)
    Rec.session, Rec.active, Rec.t0, Rec.offset = saved.session, saved.active, saved.t0, saved.offset
    Rec.pausedTotal, Rec.paused, Rec.pausedAt = saved.pausedTotal, saved.paused, saved.pausedAt
    Rec.counts, Rec.lastEvent, Rec.mission, Rec.options.job, Rec.options.result = saved.counts, saved.lastEvent, saved.mission, saved.job, saved.result
    if not okP then bad[#bad + 1] = "ทดสอบล้ม: " .. tostring(errP) end
    if #bad == 0 then
        return result("Job Recorder v2", "ผ่าน (ตรรกะ)", "ทดสอบ steps/marks/notes/cancel/recover/summary/validate/Farm Plan/รายงาน ยังไม่ได้ทดสอบกับเกมจริง")
    end
    return result("Job Recorder v2", "ล้มเหลว", table.concat(bad, ", "))
end

function Tests.live()
    local out = {}
    for _, k in ipairs({"prompt", "click", "seat", "move", "died", "stat", "hold", "tool", "gui", "npc"}) do
        local n = Rec.live[k] or 0
        out[#out + 1] = result("ได้รับเหตุการณ์จริง: " .. k, n > 0 and ("ยืนยันแล้ว " .. n .. " ครั้ง") or "ยังไม่ยืนยันในเกมจริง",
            n > 0 and "" or "ต้องบันทึกขณะเล่นแล้วทำเหตุการณ์นี้เอง")
    end
    return out
end

function Tests.runAll()
    local all = {}
    for _, r in ipairs(Tests.apiPresence()) do all[#all + 1] = r end
    all[#all + 1] = Tests.saveLoad()
    all[#all + 1] = Tests.pauseResume()
    all[#all + 1] = Tests.sessionRecovery()
    all[#all + 1] = Tests.multiMap()
    all[#all + 1] = Tests.switches()
    all[#all + 1] = Tests.interaction()
    all[#all + 1] = Tests.npc()
    all[#all + 1] = Tests.job()
    for _, r in ipairs(Tests.live()) do all[#all + 1] = r end
    return all
end

function Tests.text(list)
    local L = {"=== ผลทดสอบ V" .. M.version .. " ==="}
    for _, r in ipairs(list) do
        L[#L + 1] = "- " .. r.name .. ": " .. r.status .. (r.detail ~= "" and (" (" .. r.detail .. ")") or "")
    end
    L[#L + 1] = "หมายเหตุ: 'ยืนยันในเกมจริง' เกิดได้เฉพาะเมื่อมีเหตุการณ์จริงระหว่างบันทึก ผลอื่นเป็นการตรวจโค้ด/ไฟล์เท่านั้น"
    return table.concat(L, "\n")
end

