local SETTINGS_PATH = ROOT .. "/v102_settings.json"
function M.saveSettings()
    local data = {schema = SCHEMA, options = {}, scanners = {}}
    for _, k in ipairs(OPTION_NAMES) do data.options[k] = Rec.options[k] end
    for _, id in ipairs(ORDER) do data.scanners[id] = ScanMgr.enabled[id] ~= false end
    return wjson(SETTINGS_PATH, data)
end
function M.loadSettings()
    local d = rjson(SETTINGS_PATH)
    if not d then return false end
    for _, k in ipairs(OPTION_NAMES) do
        if type(d.options) == "table" and type(d.options[k]) == "boolean" then Rec.options[k] = d.options[k] end
    end
    for _, id in ipairs(ORDER) do
        if type(d.scanners) == "table" and type(d.scanners[id]) == "boolean" then ScanMgr.enabled[id] = d.scanners[id] end
    end
    return true
end

function M.selfCheck()
    local missing = {}
    local need = {"scan_map", "scan_npc", "scan_vehicle", "scan_job", "interaction", "ixPrompt", "ixClick", "ixTool", "ixGui", "npc", "movement", "vehicle", "route", "result", "aiLearning", "aiAnalyzer", "aiReplay"}
    local have = {}
    for _, def in ipairs(M.switchDefs) do have[def.id] = true end
    for _, k in ipairs(need) do if not have[k] then missing[#missing + 1] = k end end
    return #missing == 0, missing
end

