-- UI: หน้าทั้งหมดอยู่ในหน้าต่างหลักเดียวของ V9 (ใช้ card/row/btn/switch/liveLabel เดิม)
--------------------------------------------------------------------
local function inputBox(parent, key, placeholder, w)
    local t = mk("TextBox", {Size = UDim2.fromOffset(w or 180, 36), BackgroundColor3 = "@panel2", TextColor3 = "@text",
        PlaceholderText = placeholder, PlaceholderColor3 = "@muted", Font = Enum.Font.Gotham, TextSize = 13,
        ClearTextOnFocus = false, Text = M.inputs[key] or "", BorderSizePixel = 0}, parent)
    corner(t, 9)
    pconnect(t:GetPropertyChangedSignal("Text"), function() M.inputs[key] = t.Text end)
    return t
end

local function textBlock(parent, text, color)
    return mk("TextLabel", {Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1,
        Text = text, TextColor3 = color or "@text", Font = Enum.Font.Gotham, TextSize = 13, TextWrapped = true,
        TextXAlignment = Enum.TextXAlignment.Left, TextYAlignment = Enum.TextYAlignment.Top}, parent)
end

local function switchRow(parent, def)
    switch(parent, def.label, def.desc, def.get(), function(on)
        local ok, why = def.set(on)
        if not ok then
            say(def.label .. ": " .. tostring(why), "warn")
            return
        end
        M.saveSettings()
        say(def.label .. (on and " เปิด" or " ปิด"), "ok")
    end)
end

local function report(label, ok, why, okMsg)
    if ok then say(okMsg or (label .. " สำเร็จ"), "ok") else say(label .. ": " .. tostring(why), "warn") end
    return ok
end

function M.dashText()
    local s = Rec.session
    local state = Rec.active and (Rec.paused and "⏸ หยุดชั่วคราว" or "🔴 กำลังบันทึก") or "⚪ ยังไม่ได้บันทึก"
    local dur = s and (Rec.active and elapsed() or (s.duration or 0)) or 0
    local L = {
        "สถานะบันทึก: " .. state,
        string.format("เวลา %.1f วิ | เหตุการณ์ %d | ตำแหน่ง %d | โต้ตอบ %d", dur, s and #s.events or 0, s and #s.path or 0, Rec.counts.interactions or 0),
        IX.line(),
        NP.line(),
        JB.line(),
        "อาชีพ: " .. ((s and s.profession and s.profession ~= "") and s.profession or "-"),
        "แมพ: " .. tostring(game.PlaceId) .. " | " .. tostring(MM.db and MM.db.name or "?") .. (MM.isNew and " (แมพใหม่ สร้าง DB แล้ว)" or ""),
        "ขนาดข้อมูลที่บันทึกล่าสุด: " .. tostring(s and s.sizeBytes or 0) .. " ไบต์",
        "สแกน: " .. runLine(),
        "ล่าสุด: " .. tostring(M.lastMsg),
    }
    return table.concat(L, "\n")
end

-- ปุ่มควบคุมหลัก 8 ปุ่ม
function M.latestId()
    local l = Session.list()
    return l[1] and l[1].id or nil
end

function M.analyzeData()
    if not Rec.options.aiAnalyzer then return false, "AI Analyzer ปิดอยู่" end
    local d = Rec.session or M.loaded
    if not d then
        local id = M.latestId()
        if id then d = Session.load(id) end
    end
    if not d then return false, "ไม่มี session ให้วิเคราะห์" end
    if d == Rec.session then Rec.save(true) end
    local rep = Analyzer.analyzeAndSave(d)
    M.lastReport = rep
    return true, rep
end

local function controlButtons(c)
    local r1 = row(c)
    btn(r1, "▶ START SCAN", function()
        local ids = {}
        for _, id in ipairs(ORDER) do if ScanMgr.enabled[id] ~= false then ids[#ids + 1] = id end end
        if #ids == 0 then say("ปิดสแกนเนอร์ครบทุกตัว ไม่มีอะไรให้สแกน", "warn") return end
        runScan(ids)
    end, 150, true)
    btn(r1, "● START RECORDING", function()
        local ok, why = Rec.start(M.inputs.prof or "", M.inputs.sid)
        if ok and why then
            say(why, "warn")
        else
            report("เริ่มบันทึก", ok, why, "เริ่มบันทึกแล้ว (ควบคุมตัวละครเองตามปกติ)")
        end
    end, 170, true)
    btn(r1, "■ STOP RECORDING", function()
        local ok, why = Rec.stop()
        report("หยุดบันทึก", ok, why, "หยุดบันทึกและเซฟแล้ว" .. (Rec.lastReport and " | AI วิเคราะห์แล้ว" or ""))
    end, 170)
    local r2 = row(c)
    btn(r2, "⏸ PAUSE", function()
        local ok, why = Rec.pause()
        report("หยุดชั่วคราว", ok, why, "หยุดชั่วคราวแล้ว")
    end, 110)
    btn(r2, "⏵ RESUME", function()
        local ok, why = Rec.resume()
        report("เล่นต่อ", ok, why, "กลับมาบันทึกต่อ")
    end, 110)
    btn(r2, "💾 SAVE SESSION", function()
        local ok, why = Rec.save(false)
        report("บันทึก session", ok, why, "บันทึก session แล้ว")
    end, 150)
    btn(r2, "📂 LOAD SESSION", function()
        local id = M.inputs.sid
        if not id or id == "" then id = M.latestId() end
        if not id then say("ยังไม่มี session ในแมพนี้", "warn") return end
