        say("โหลดแล้ว: " .. tostring(d.name) .. " | ขั้นตอน " .. rep.interactionCount .. " | ระยะ " .. rep.path.distance, "ok")
    end, 150)
    btn(r2, "🧠 ANALYZE DATA", function()
        local ok, rep = M.analyzeData()
        if ok then say("วิเคราะห์แล้ว ดูรายงานในแท็บ AI Analyzer", "ok") showTab("v_ai") else say("วิเคราะห์ไม่ได้: " .. tostring(rep), "warn") end
    end, 150, true)
end

