local function planText(fp)
    if not fp.ok then return "สร้างแผนไม่ได้: " .. tostring(fp.why) end
    local L = {"=== Farm Plan (แมพ " .. tostring(fp.placeId) .. ") ===",
        "สร้างจากลำดับที่ทำซ้ำ " .. fp.supporters .. " ครั้ง ใน " .. #(fp.basedOnSessions or {}) .. " session",
        "เวลาภารกิจเฉลี่ย: " .. tostring(fp.avgMissionSec) .. " วิ"}
    if fp.playerEntered then
        L[#L + 1] = "ผลที่ผู้เล่นป้อน: สำเร็จ " .. fp.playerEntered.success .. " | ล้มเหลว " .. fp.playerEntered.fail ..
            (fp.playerEntered.successRatePct and (" | อัตรา " .. fp.playerEntered.successRatePct .. "%") or "")
    end
    local any = false
    for k, v in pairs((fp.gameConfirmed or {}).avgStatDeltaPerMission or {}) do
        L[#L + 1] = "เกมยืนยัน: " .. tostring(k) .. " เฉลี่ย " .. tostring(v) .. " ต่อภารกิจ"
        any = true
    end
    if not any then L[#L + 1] = "เกมยืนยัน: ไม่มีค่า leaderstats ที่เปลี่ยนในภารกิจเหล่านี้" end
    for _, s in ipairs(fp.steps or {}) do
        L[#L + 1] = string.format("%d) %s | %s%s%s", s.order, tostring(s.action), tostring(s.object),
            s.pos and string.format(" @(%d,%d,%d)", s.pos[1], s.pos[2], s.pos[3]) or "",
            s.avgGapSec and (" ~" .. s.avgGapSec .. " วิ") or "")
    end
    for _, n in ipairs(fp.notes or {}) do L[#L + 1] = "หมายเหตุ: " .. n end
    return table.concat(L, "\n")
end

