local function simText(sim)
    if not sim.ok then return "จำลองไม่ได้: " .. tostring(sim.why) end
    local L = {"=== Simulation (ไม่ได้ส่งคำสั่งเข้าเกม) ==="}
    for _, s in ipairs(sim.steps) do
        L[#L + 1] = string.format("%d) %s | %s%s%s", s.order, tostring(s.action), tostring(s.object),
            s.distFromPrev and (" | ห่างจากจุดก่อน " .. s.distFromPrev .. " สตั๊ด") or "",
            s.avgGapSec and (" | ~" .. s.avgGapSec .. " วิ") or "")
    end
    L[#L + 1] = sim.note
    return table.concat(L, "\n")
end

