-- เริ่มระบบ V10.2: โหลดค่าสวิตช์ ลงทะเบียนแมพ ผูกกับตัวตรวจระบบของ V9
--------------------------------------------------------------------
pcall(M.loadSettings)
local okMM, errMM = pcall(MM.register)
if not okMM then logf("Multi Map ลงทะเบียนแมพไม่สำเร็จ: " .. tostring(errMM), "warn") end
for _, w in ipairs({
    {"V102.Rec.start", function() return Rec.start end}, {"V102.Rec.stop", function() return Rec.stop end},
    {"V102.Rec.save", function() return Rec.save end}, {"V102.Session.list", function() return Session.list end},
    {"V102.Analyzer.analyze", function() return Analyzer.analyze end}, {"V102.Replay.simulate", function() return Replay.simulate end},
    {"V102.MultiMap.register", function() return MM.register end},
}) do Diag.watch[#Diag.watch + 1] = w end
do
    local okS, miss = M.selfCheck()
    if okS then
        logf("V" .. M.version .. " พร้อม: สวิตช์ครบ " .. #M.switchDefs .. " ตัว | แมพ " .. tostring(game.PlaceId) .. (MM.isNew and " (แมพใหม่ สร้าง DB แล้ว)" or ""), "ok")
    else
        logf("V" .. M.version .. " ขาดสวิตช์: " .. table.concat(miss, ", "), "err")
    end
    if not canW() then logf("ตัวรันนี้ไม่มี writefile ระบบบันทึกจะเก็บได้เฉพาะในหน่วยความจำ", "warn") end
end
ENV.BALLKUN_V102 = M

return M
end)()

