local navBtns = {}

-- ใช้ค่าตัวอักษรที่ตั้งไว้กับทุกข้อความใน UI (ค่าเดิม: ฟอนต์ว่าง ขนาด 1 ระยะบรรทัด 1 ไม่เปลี่ยนสี)
function applyFonts()
    if not root then return end
    local fontName = Set.fontName or ""
    local scale = Set.fontScale or 1
    local spacing = Set.lineSpacing or 1
    local tcol = nil
    local hx = string.gsub(Set.textHex or "", "#", "")
    if #hx == 6 then
        local r, g, b = tonumber(hx:sub(1, 2), 16), tonumber(hx:sub(3, 4), 16), tonumber(hx:sub(5, 6), 16)
        if r and g and b then tcol = Color3.fromRGB(r, g, b) end
    end
    for _, o in ipairs(root:GetDescendants()) do
        if o:IsA("TextLabel") or o:IsA("TextButton") or o:IsA("TextBox") then
            if o:GetAttribute("bkBaseSize") == nil then o:SetAttribute("bkBaseSize", o.TextSize) end
            local base = o:GetAttribute("bkBaseSize") or o.TextSize
            pcall(function() o.TextSize = math.max(8, math.floor(base * scale + 0.5)) end)
            pcall(function() o.LineHeight = spacing end)
            if fontName ~= "" then pcall(function() o.Font = Enum.Font[fontName] end) end
            if tcol and o:IsA("TextLabel") then pcall(function() o.TextColor3 = tcol end) end
        end
    end
end

function showTab(id)
    currentTab = id
    clearBody()
    for _, t in ipairs(ALL_TABS) do
        if t[1] == id then
            pageTitle.Text = t[2]
            pageDesc.Text = t[3]
            local ok, err = xpcall(t[4], debug.traceback)
            if not ok then logf("หน้า " .. id .. " แสดงผลไม่สำเร็จ: " .. cut(err, 200), "err") pcall(ErrLog.add, "ui:" .. tostring(id), err) end
        end
    end
    for tid, b in pairs(navBtns) do
        b.BackgroundColor3 = tid == id and T.accent or T.panel2
        b.TextColor3 = tid == id and T.bg or T.text
    end
    applyFonts()
    body.CanvasPosition = Vector2.new(0, 0)
end

