local saveQueued = false
function saveSettings()
    if saveQueued then return end
    saveQueued = true
    task.delay(0.8, function()
        saveQueued = false
        local data = {}
        for k, v in pairs(Set) do data[k] = v end
        local ok, js = pcall(function() return HttpService:JSONEncode(data) end)
        if ok then writeFile("settings.json", js, true) end
    end)
end
local function loadSettings()
    local c = readFile("settings.json")
    if not c then return end
    local ok, data = pcall(function() return HttpService:JSONDecode(c) end)
    if ok and type(data) == "table" then
        for k, v in pairs(data) do if Set[k] ~= nil and type(v) == type(Set[k]) then Set[k] = v end end
        Set.palette = math.clamp(math.floor(Set.palette), 1, #PALETTES)
        applyPalette(Set.palette)
    end
end
loadSettings()

