local function prepareBackground()
    local assetFn = getcustomasset or getsynasset
    if type(assetFn) ~= "function" or type(writefile) ~= "function" then return nil, "ตัวรันไม่รองรับรูปจากไฟล์ (getcustomasset)" end
    local name = "bg_v7.jpg"
    local path = FOLDER .. "/" .. name
    local needWrite = true
    if type(isfile) == "function" then
        local ok, ex = pcall(isfile, path)
        if ok and ex then needWrite = false end
    end
    if needWrite then
        local bytes = b64decode(BG_B64)
        if #bytes < 1000 then return nil, "ถอดรหัสรูปพื้นหลังไม่สำเร็จ" end
        local w, err = writeFile(name, bytes)
        if not w then return nil, tostring(err) end
    end
    local ok, asset = pcall(assetFn, path)
    if ok and asset then return asset end
    return nil, "สร้าง asset จากไฟล์ไม่สำเร็จ"
end

